import type { BankQuestion } from "@/lib/bank";

/** Science and Technology (Space, Defence, IT) (General Knowledge): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"gk-science-tech-1","question":"The headquarters of the Indian Space Research Organisation (ISRO) is in:","options":["Bengaluru","Ahmedabad","Sriharikota","Thiruvananthapuram"],"answer":0,"explanation":"ISRO is headquartered at Antariksh Bhavan, Bengaluru. Sriharikota is the launch centre and Thiruvananthapuram has VSSC.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"भारतीय अंतरिक्ष अनुसंधान संगठन (ISRO) का मुख्यालय कहाँ स्थित है?","optionsHi":["बेंगलुरु","अहमदाबाद","श्रीहरिकोटा","तिरुवनंतपुरम"],"explanationHi":"ISRO का मुख्यालय बेंगलुरु के अंतरिक्ष भवन में है। श्रीहरिकोटा प्रक्षेपण केंद्र है और तिरुवनंतपुरम में VSSC स्थित है।"},
  {"id":"gk-science-tech-2","question":"India’s first satellite, launched in 1975, was:","options":["Aryabhata","Rohini","Bhaskara","INSAT-1A"],"answer":0,"explanation":"Aryabhata, named after the ancient astronomer, was launched on 19 April 1975.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"1975 में प्रक्षेपित भारत का प्रथम उपग्रह कौन-सा था?","optionsHi":["आर्यभट्ट","रोहिणी","भास्कर","INSAT-1A"],"explanationHi":"प्राचीन खगोलशास्त्री के नाम पर रखा गया आर्यभट्ट 19 अप्रैल 1975 को प्रक्षेपित किया गया था।"},
  {"id":"gk-science-tech-3","question":"Chandrayaan-3’s lander touched down near the Moon’s south pole on 23 August 2023. What is that date now observed as in India?","options":["National Astronomy Day","National Technology Day","National Space Day","National Science Day"],"answer":2,"explanation":"23 August is observed as National Space Day. National Science Day is 28 February and National Technology Day (Pokhran-II) is 11 May.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"चंद्रयान-3 का लैंडर 23 अगस्त 2023 को चंद्रमा के दक्षिणी ध्रुव के निकट उतरा था। भारत में अब यह तिथि किस रूप में मनाई जाती है?","optionsHi":["राष्ट्रीय खगोल दिवस","राष्ट्रीय प्रौद्योगिकी दिवस","राष्ट्रीय अंतरिक्ष दिवस","राष्ट्रीय विज्ञान दिवस"],"explanationHi":"23 अगस्त को राष्ट्रीय अंतरिक्ष दिवस के रूप में मनाया जाता है। राष्ट्रीय विज्ञान दिवस 28 फरवरी को और राष्ट्रीय प्रौद्योगिकी दिवस (पोखरण-II) 11 मई को मनाया जाता है।"},
  {"id":"gk-science-tech-4","question":"DRDO stands for:","options":["Defence Research and Development Organisation","Defence Research and Design Office","Department of Research and Defence Operations","Defence Resource and Deployment Office"],"answer":0,"explanation":"DRDO, formed in 1958, is the R&D wing of the Ministry of Defence that developed the Agni, Prithvi and Akash missiles.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"DRDO का पूर्ण रूप क्या है?","optionsHi":["रक्षा अनुसंधान एवं विकास संगठन (Defence Research and Development Organisation)","रक्षा अनुसंधान एवं डिज़ाइन कार्यालय (Defence Research and Design Office)","अनुसंधान एवं रक्षा संचालन विभाग (Department of Research and Defence Operations)","रक्षा संसाधन एवं तैनाती कार्यालय (Defence Resource and Deployment Office)"],"explanationHi":"1958 में गठित DRDO रक्षा मंत्रालय की अनुसंधान एवं विकास शाखा है, जिसने अग्नि, पृथ्वी और आकाश मिसाइलें विकसित की हैं।"},
  {"id":"gk-science-tech-5","question":"India’s Mars Orbiter Mission (Mangalyaan), launched in November 2013, was carried by:","options":["PSLV","LVM3","GSLV Mk II","SSLV"],"answer":0,"explanation":"PSLV-C25 launched the Mars Orbiter Mission; it entered Mars orbit on 24 September 2014, making India the first country to succeed on its first attempt.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · UPSC Prelims","questionHi":"नवंबर 2013 में प्रक्षेपित भारत के मंगल कक्षित्र मिशन (मंगलयान) को किस प्रक्षेपण यान ने ले जाया था?","optionsHi":["PSLV","LVM3","GSLV Mk II","SSLV"],"explanationHi":"PSLV-C25 ने मंगल कक्षित्र मिशन का प्रक्षेपण किया; यह 24 सितंबर 2014 को मंगल की कक्षा में पहुँचा, जिससे भारत पहले ही प्रयास में सफल होने वाला पहला देश बना।"},
  {"id":"gk-science-tech-6","question":"Aditya-L1, India’s solar observatory launched in 2023, is placed:","options":["In orbit around the Moon","In a halo orbit around the Sun–Earth Lagrange point L1","In a geostationary orbit","In a low Earth polar orbit"],"answer":1,"explanation":"Aditya-L1 sits about 1.5 million km from Earth around L1, from where it can watch the Sun without being blocked by Earth or the Moon.","difficulty":"moderate","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"2023 में प्रक्षेपित भारत की सौर वेधशाला आदित्य-L1 को कहाँ स्थापित किया गया है?","optionsHi":["चंद्रमा की परिक्रमा करती कक्षा में","सूर्य–पृथ्वी लैग्रेंज बिंदु L1 के चारों ओर हेलो कक्षा में","भूस्थिर कक्षा में","निम्न पृथ्वी ध्रुवीय कक्षा में"],"explanationHi":"आदित्य-L1 पृथ्वी से लगभग 1.5 मिलियन km दूर L1 के चारों ओर स्थित है, जहाँ से वह पृथ्वी या चंद्रमा की बाधा के बिना सूर्य का अवलोकन कर सकता है।"},
  {"id":"gk-science-tech-7","question":"BrahMos, a supersonic cruise missile, is a joint venture between India and:","options":["France","Russia","USA","Israel"],"answer":1,"explanation":"BrahMos Aerospace is an India–Russia joint venture; the name joins the Brahmaputra and Moskva rivers.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"ब्रह्मोस, एक सुपरसोनिक क्रूज़ मिसाइल, भारत और किस देश का संयुक्त उद्यम है?","optionsHi":["फ्रांस","रूस","अमेरिका","इज़राइल"],"explanationHi":"ब्रह्मोस एयरोस्पेस भारत–रूस का संयुक्त उद्यम है; इसका नाम ब्रह्मपुत्र और मोस्कवा नदियों को मिलाकर बना है।"},
  {"id":"gk-science-tech-8","question":"The launch centre at Sriharikota is named after:","options":["Vikram Sarabhai","A.P.J. Abdul Kalam","Satish Dhawan","Homi J. Bhabha"],"answer":2,"explanation":"It is the Satish Dhawan Space Centre (SDSC SHAR). The Vikram Sarabhai Space Centre is at Thiruvananthapuram.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"श्रीहरिकोटा स्थित प्रक्षेपण केंद्र का नाम किसके नाम पर रखा गया है?","optionsHi":["विक्रम साराभाई","ए.पी.जे. अब्दुल कलाम","सतीश धवन","होमी जे. भाभा"],"explanationHi":"यह सतीश धवन अंतरिक्ष केंद्र (SDSC SHAR) है। विक्रम साराभाई अंतरिक्ष केंद्र तिरुवनंतपुरम में है।"},
  {"id":"gk-science-tech-9","question":"India’s first nuclear test at Pokhran in May 1974 was code-named:","options":["Smiling Buddha","Operation Shakti","Operation Meghdoot","Operation Vijay"],"answer":0,"explanation":"The 1974 test was “Smiling Buddha”. The 1998 tests were Operation Shakti; Operation Vijay (1999) was the Kargil operation.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · UPSC Prelims","questionHi":"मई 1974 में पोखरण में भारत के प्रथम परमाणु परीक्षण का सांकेतिक नाम क्या था?","optionsHi":["स्माइलिंग बुद्धा","ऑपरेशन शक्ति","ऑपरेशन मेघदूत","ऑपरेशन विजय"],"explanationHi":"1974 के परीक्षण का नाम \"स्माइलिंग बुद्धा\" था। 1998 के परीक्षण ऑपरेशन शक्ति थे; ऑपरेशन विजय (1999) कारगिल का सैन्य अभियान था।"},
  {"id":"gk-science-tech-10","question":"Who is known as the father of the Indian space programme?","options":["Satish Dhawan","Vikram Sarabhai","U.R. Rao","Homi J. Bhabha"],"answer":1,"explanation":"Vikram Sarabhai founded INCOSPAR (1962), which became ISRO in 1969. Homi Bhabha is called the father of India’s nuclear programme.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"भारतीय अंतरिक्ष कार्यक्रम के जनक के रूप में किसे जाना जाता है?","optionsHi":["सतीश धवन","विक्रम साराभाई","U.R. राव","होमी जे. भाभा"],"explanationHi":"विक्रम साराभाई ने INCOSPAR (1962) की स्थापना की, जो 1969 में ISRO बना। होमी भाभा को भारत के परमाणु कार्यक्रम का जनक कहा जाता है।"},
  {"id":"gk-science-tech-11","question":"In cyber security, “phishing” means:","options":["Secretly recording keystrokes on a computer","Encrypting a victim’s files and demanding payment","Tricking people into revealing sensitive details by posing as a trustworthy source","Flooding a server with traffic so that it crashes"],"answer":2,"explanation":"Phishing uses fake emails, messages or websites to steal passwords and bank details. Flooding a server is a DoS attack and encrypting files for money is ransomware.","difficulty":"moderate","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"साइबर सुरक्षा में \"फ़िशिंग\" का अर्थ है:","optionsHi":["कंप्यूटर पर की-स्ट्रोक्स को चुपके से रिकॉर्ड करना","पीड़ित की फ़ाइलों को एन्क्रिप्ट करके भुगतान की माँग करना","किसी विश्वसनीय स्रोत का रूप धरकर लोगों से संवेदनशील जानकारी उगलवाना","किसी सर्वर पर इतना ट्रैफ़िक डालना कि वह ठप हो जाए"],"explanationHi":"फ़िशिंग में नकली ईमेल, संदेश या वेबसाइट के ज़रिए पासवर्ड और बैंक विवरण चुराए जाते हैं। सर्वर पर ट्रैफ़िक की बाढ़ लाना DoS हमला है और पैसे के लिए फ़ाइलें एन्क्रिप्ट करना रैनसमवेयर है।"},
  {"id":"gk-science-tech-12","question":"Bt cotton is resistant to bollworm because it carries a gene from:","options":["Rhizobium","Agrobacterium tumefaciens","Escherichia coli","Bacillus thuringiensis"],"answer":3,"explanation":"The cry gene from the soil bacterium Bacillus thuringiensis makes a protein toxic to bollworm larvae. Agrobacterium is a vector used to insert genes.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"Bt कपास सूंडी (बॉलवर्म) के प्रति प्रतिरोधी होता है, क्योंकि उसमें किसके जीन होते हैं?","optionsHi":["राइज़ोबियम","एग्रोबैक्टीरियम ट्यूमेफेशियंस","एशेरिशिया कोलाई","बैसिलस थुरिंजिएन्सिस"],"explanationHi":"मृदा जीवाणु बैसिलस थुरिंजिएन्सिस का cry जीन ऐसा प्रोटीन बनाता है जो सूंडी के लार्वा के लिए विषैला होता है। एग्रोबैक्टीरियम जीन डालने के लिए प्रयुक्त वाहक है।"},
  {"id":"gk-science-tech-13","question":"In June 2025, who became the first Indian astronaut to visit the International Space Station, on the Axiom-4 mission?","options":["Rakesh Sharma","Ajit Krishnan","Prasanth Balakrishnan Nair","Shubhanshu Shukla"],"answer":3,"explanation":"Group Captain Shubhanshu Shukla flew to the ISS on Axiom-4, launched on 25 June 2025. Rakesh Sharma flew to the Soviet Salyut-7 station in 1984; Nair and Krishnan are fellow Gaganyaan astronaut-designates.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"जून 2025 में Axiom-4 मिशन के तहत अंतरराष्ट्रीय अंतरिक्ष स्टेशन जाने वाले प्रथम भारतीय अंतरिक्ष यात्री कौन बने?","optionsHi":["राकेश शर्मा","अजित कृष्णन","प्रशांत बालकृष्णन नायर","शुभांशु शुक्ला"],"explanationHi":"ग्रुप कैप्टन शुभांशु शुक्ला Axiom-4 से ISS गए, जिसका प्रक्षेपण 25 जून 2025 को हुआ। राकेश शर्मा 1984 में सोवियत सैल्यूट-7 स्टेशन गए थे; नायर और कृष्णन गगनयान के अन्य नामित अंतरिक्ष यात्री हैं।"},
  {"id":"gk-science-tech-14","question":"LVM3 (earlier GSLV Mk III), which launched Chandrayaan-3, uses which upper stage?","options":["L110 liquid stage","S200 solid stage","C25 cryogenic stage","PS4 liquid stage"],"answer":2,"explanation":"LVM3 has two S200 solid boosters, an L110 liquid core and the indigenous C25 cryogenic upper stage. PS4 is the fourth stage of the PSLV.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"LVM3 (पहले GSLV Mk III), जिसने चंद्रयान-3 का प्रक्षेपण किया, किस ऊपरी चरण का उपयोग करता है?","optionsHi":["L110 द्रव चरण","S200 ठोस चरण","C25 क्रायोजेनिक चरण","PS4 द्रव चरण"],"explanationHi":"LVM3 में दो S200 ठोस बूस्टर, एक L110 द्रव कोर और स्वदेशी C25 क्रायोजेनिक ऊपरी चरण होता है। PS4 PSLV का चौथा चरण है।"},
  {"id":"gk-science-tech-15","question":"“Mission Divyastra” (March 2024) was the first flight test of the Agni-V missile with:","options":["An anti-satellite warhead","A hypersonic glide vehicle","Multiple Independently targetable Re-entry Vehicle (MIRV) technology","A submarine launch platform"],"answer":2,"explanation":"Mission Divyastra tested Agni-V carrying MIRVs, which let one missile strike several targets. India’s anti-satellite test was Mission Shakti (2019).","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"\"मिशन दिव्यास्त्र\" (मार्च 2024) अग्नि-V मिसाइल का किसके साथ पहला उड़ान परीक्षण था?","optionsHi":["उपग्रह-रोधी (एंटी-सैटेलाइट) वारहेड","अतिध्वनिक ग्लाइड वाहन","बहु-लक्ष्य पुनःप्रवेश यान (MIRV) प्रौद्योगिकी","पनडुब्बी प्रक्षेपण मंच"],"explanationHi":"मिशन दिव्यास्त्र में MIRV से युक्त अग्नि-V का परीक्षण किया गया, जो एक मिसाइल को कई लक्ष्यों पर प्रहार करने में सक्षम बनाता है। भारत का उपग्रह-रोधी परीक्षण मिशन शक्ति (2019) था।"},
  {"id":"gk-science-tech-16","question":"India’s nuclear doctrine, made public in 2003, is based on:","options":["Launch on warning","Credible minimum deterrence and no first use","First use against any conventional attack","Nuclear sharing with allies"],"answer":1,"explanation":"The doctrine commits India to no first use, building a credible minimum deterrent, with massive retaliation if attacked and no use against non-nuclear states.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"2003 में सार्वजनिक की गई भारत की परमाणु नीति (डॉक्ट्रिन) किस पर आधारित है?","optionsHi":["चेतावनी पर प्रक्षेपण","विश्वसनीय न्यूनतम प्रतिरोध और प्रथम प्रयोग नहीं","किसी भी पारंपरिक हमले के विरुद्ध प्रथम प्रयोग","सहयोगियों के साथ परमाणु साझेदारी"],"explanationHi":"यह नीति भारत को प्रथम प्रयोग न करने, विश्वसनीय न्यूनतम प्रतिरोध बनाने, हमला होने पर व्यापक जवाबी कार्रवाई करने और परमाणु-विहीन देशों के विरुद्ध प्रयोग न करने के लिए प्रतिबद्ध करती है।"},
  {"id":"gk-science-tech-17","question":"The third stage of India’s three-stage nuclear power programme aims to use:","options":["Enriched uranium in light water reactors","Plutonium in fast breeder reactors only","Natural uranium in pressurised heavy water reactors","Thorium, through uranium-233 based reactors"],"answer":3,"explanation":"Stage 1: natural uranium in PHWRs; stage 2: plutonium in fast breeder reactors; stage 3: thorium converted to U-233. India has large thorium reserves but little uranium.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"भारत के त्रि-चरणीय परमाणु ऊर्जा कार्यक्रम के तीसरे चरण का उद्देश्य किसका उपयोग करना है?","optionsHi":["हल्के जल रिएक्टरों में समृद्ध यूरेनियम","केवल तीव्र प्रजनक रिएक्टरों में प्लूटोनियम","दाबित भारी जल रिएक्टरों में प्राकृतिक यूरेनियम","यूरेनियम-233 आधारित रिएक्टरों के माध्यम से थोरियम"],"explanationHi":"चरण 1: PHWR में प्राकृतिक यूरेनियम; चरण 2: तीव्र प्रजनक रिएक्टरों में प्लूटोनियम; चरण 3: थोरियम को U-233 में बदलना। भारत में थोरियम के विशाल भंडार हैं, पर यूरेनियम कम है।"},
  {"id":"gk-science-tech-18","question":"NavIC is the operational name of:","options":["India’s weather satellite series","India’s satellite-based internet service","The Indian Regional Navigation Satellite System","ISRO’s deep-space tracking network"],"answer":2,"explanation":"NavIC (Navigation with Indian Constellation) is the IRNSS, giving position data over India and about 1,500 km around it.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"NavIC किसका परिचालन नाम है?","optionsHi":["भारत की मौसम उपग्रह श्रृंखला","भारत की उपग्रह-आधारित इंटरनेट सेवा","भारतीय क्षेत्रीय नौवहन उपग्रह प्रणाली","ISRO का गहन-अंतरिक्ष अनुवीक्षण नेटवर्क"],"explanationHi":"NavIC (Navigation with Indian Constellation) ही IRNSS है, जो भारत और उसके आसपास लगभग 1,500 km तक स्थिति संबंधी आँकड़े देती है।"},
  {"id":"gk-science-tech-19","question":"INS Arihant, commissioned in 2016, is India’s first indigenous:","options":["Stealth frigate","Nuclear-powered ballistic missile submarine","Aircraft carrier","Diesel-electric attack submarine"],"answer":1,"explanation":"INS Arihant is an SSBN that carries nuclear-tipped ballistic missiles, completing India’s land–air–sea nuclear triad. INS Vikrant (2022) is the first indigenous aircraft carrier.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"2016 में सेवा में शामिल INS अरिहंत भारत की पहली स्वदेशी कौन-सी है?","optionsHi":["स्टेल्थ फ्रिगेट","परमाणु-चालित बैलिस्टिक मिसाइल पनडुब्बी","विमानवाहक पोत","डीज़ल-इलेक्ट्रिक आक्रमण पनडुब्बी"],"explanationHi":"INS अरिहंत एक SSBN है जो परमाणु-शीर्ष वाली बैलिस्टिक मिसाइलें ले जाती है और भारत की भूमि–वायु–समुद्र परमाणु त्रयी को पूरा करती है। INS विक्रांत (2022) पहला स्वदेशी विमानवाहक पोत है।"},
  {"id":"gk-science-tech-20","question":"Which of these is a surface-to-air missile?","options":["Nirbhay","Akash","Prithvi","Nag"],"answer":1,"explanation":"Akash is a surface-to-air missile. Prithvi is a surface-to-surface ballistic missile, Nag an anti-tank missile and Nirbhay a subsonic cruise missile.","difficulty":"hard","source":"SSC CGL · RRB NTPC · UPSC Prelims","questionHi":"इनमें से कौन-सी सतह से हवा में मार करने वाली मिसाइल है?","optionsHi":["निर्भय","आकाश","पृथ्वी","नाग"],"explanationHi":"आकाश सतह से हवा में मार करने वाली मिसाइल है। पृथ्वी सतह से सतह पर मार करने वाली बैलिस्टिक मिसाइल है, नाग टैंक-रोधी मिसाइल है और निर्भय अवध्वनिक क्रूज़ मिसाइल है।"},
  {"id":"gk-science-tech-21","question":"Golden Rice is genetically engineered to be rich in:","options":["Lysine","Vitamin C","Iron","Beta-carotene (provitamin A)"],"answer":3,"explanation":"Golden Rice makes beta-carotene, which the body turns into vitamin A, to fight vitamin A deficiency. Its golden colour comes from the beta-carotene.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"गोल्डन राइस को आनुवंशिक रूप से किसमें समृद्ध करने के लिए बनाया गया है?","optionsHi":["लाइसिन","विटामिन C","आयरन (लोहा)","बीटा-कैरोटीन (प्रोविटामिन A)"],"explanationHi":"गोल्डन राइस बीटा-कैरोटीन बनाता है, जिसे शरीर विटामिन A में बदल लेता है, ताकि विटामिन A की कमी से लड़ा जा सके। इसका सुनहरा रंग बीटा-कैरोटीन से आता है।"},
  {"id":"gk-science-tech-22","question":"In India, approval for the environmental release of genetically modified crops is given by the:","options":["Food Safety and Standards Authority of India","Department of Biotechnology’s Review Committee on Genetic Manipulation","Indian Council of Agricultural Research","Genetic Engineering Appraisal Committee under the Ministry of Environment"],"answer":3,"explanation":"The GEAC, under the MoEFCC, appraises proposals for the release of GM organisms. The Review Committee on Genetic Manipulation oversees research-stage work.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"भारत में आनुवंशिक रूप से संशोधित फसलों के पर्यावरणीय विमोचन की स्वीकृति कौन देता है?","optionsHi":["भारतीय खाद्य सुरक्षा और मानक प्राधिकरण","जैव प्रौद्योगिकी विभाग की आनुवंशिक हेरफेर समीक्षा समिति","भारतीय कृषि अनुसंधान परिषद","पर्यावरण मंत्रालय के अधीन आनुवंशिक अभियांत्रिकी मूल्यांकन समिति"],"explanationHi":"MoEFCC के अधीन GEAC आनुवंशिक रूप से संशोधित जीवों के विमोचन के प्रस्तावों का मूल्यांकन करती है। आनुवंशिक हेरफेर समीक्षा समिति अनुसंधान-चरण के कार्य की निगरानी करती है।"},
  {"id":"gk-science-tech-23","question":"India’s first satellite, Aryabhata, was launched from:","options":["Thumba","Sriharikota","The Soviet Union","French Guiana"],"answer":2,"explanation":"Aryabhata went up on a Soviet Kosmos-3M rocket from Kapustin Yar in 1975. India’s own launch capability came with SLV-3 in 1980.","difficulty":"hard","source":"SSC CGL · RRB NTPC · UPSC Prelims","questionHi":"भारत के प्रथम उपग्रह आर्यभट्ट का प्रक्षेपण कहाँ से किया गया था?","optionsHi":["थुंबा","श्रीहरिकोटा","सोवियत संघ","फ्रेंच गयाना"],"explanationHi":"आर्यभट्ट को 1975 में कपुस्तिन यार से सोवियत कॉसमॉस-3M रॉकेट द्वारा भेजा गया था। भारत की अपनी प्रक्षेपण क्षमता 1980 में SLV-3 के साथ आई।"},
  {"id":"gk-science-tech-24","question":"India’s first indigenous launch vehicle SLV-3 successfully placed which satellite in orbit in 1980?","options":["Aryabhata","Bhaskara-I","Rohini","APPLE"],"answer":2,"explanation":"SLV-3, with A.P.J. Abdul Kalam as project director, put Rohini RS-1 into orbit on 18 July 1980, giving India its own satellite launch capability.","difficulty":"hard","source":"SSC CGL · RRB NTPC · UPSC Prelims","questionHi":"भारत के प्रथम स्वदेशी प्रक्षेपण यान SLV-3 ने 1980 में किस उपग्रह को सफलतापूर्वक कक्षा में स्थापित किया?","optionsHi":["आर्यभट्ट","भास्कर-I","रोहिणी","APPLE"],"explanationHi":"SLV-3, जिसके परियोजना निदेशक ए.पी.जे. अब्दुल कलाम थे, ने 18 जुलाई 1980 को रोहिणी RS-1 को कक्षा में स्थापित किया, जिससे भारत को अपनी उपग्रह प्रक्षेपण क्षमता मिली।"},
  {"id":"gk-science-tech-25","question":"Match the mission with its main purpose: 1. Chandrayaan-1 (2008)  2. AstroSat (2015)  3. Aditya-L1 (2023)  4. XPoSat (2024); a. Measuring X-ray polarisation from cosmic sources  b. Lunar orbiter that helped detect water molecules on the Moon  c. Study of the Sun  d. Multi-wavelength space observatory","options":["1-d, 2-b, 3-c, 4-a","1-b, 2-d, 3-a, 4-c","1-b, 2-a, 3-c, 4-d","1-b, 2-d, 3-c, 4-a"],"answer":3,"explanation":"Chandrayaan-1 carried NASA’s Moon Mineralogy Mapper, which found water signatures; AstroSat is India’s first multi-wavelength observatory; Aditya-L1 studies the Sun; XPoSat is an X-ray polarimetry satellite.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"मिशन का उसके मुख्य उद्देश्य से मिलान कीजिए: 1. चंद्रयान-1 (2008)  2. एस्ट्रोसैट (2015)  3. आदित्य-L1 (2023)  4. XPoSat (2024); a. ब्रह्मांडीय स्रोतों से X-किरण ध्रुवण का मापन  b. चंद्र कक्षित्र जिसने चंद्रमा पर जल अणुओं का पता लगाने में सहायता की  c. सूर्य का अध्ययन  d. बहु-तरंगदैर्घ्य अंतरिक्ष वेधशाला","optionsHi":["1-d, 2-b, 3-c, 4-a","1-b, 2-d, 3-a, 4-c","1-b, 2-a, 3-c, 4-d","1-b, 2-d, 3-c, 4-a"],"explanationHi":"चंद्रयान-1 में NASA का मून मिनरलॉजी मैपर था, जिसने जल के संकेत खोजे; एस्ट्रोसैट भारत की पहली बहु-तरंगदैर्घ्य वेधशाला है; आदित्य-L1 सूर्य का अध्ययन करता है; XPoSat एक X-किरण ध्रुवणमापी उपग्रह है।"},
  {"id":"gk-science-tech-26","question":"How many of these statements about Chandrayaan-3 are correct? I. Its lander was named Pragyan and its rover Vikram. II. It was launched by PSLV. III. India became the first country to soft-land near the Moon’s south pole. IV. India became the first country to soft-land on the Moon.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only III is correct. The lander was Vikram and the rover Pragyan, and the mission was launched by LVM3 (PSLV launched Chandrayaan-1). India was the fourth country to soft-land on the Moon, after the USSR, the USA and China.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"चंद्रयान-3 के बारे में इनमें से कितने कथन सही हैं? I. इसके लैंडर का नाम प्रज्ञान और रोवर का नाम विक्रम था। II. इसका प्रक्षेपण PSLV द्वारा किया गया। III. भारत चंद्रमा के दक्षिणी ध्रुव के निकट सॉफ्ट लैंडिंग करने वाला पहला देश बना। IV. भारत चंद्रमा पर सॉफ्ट लैंडिंग करने वाला पहला देश बना।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल III सही है। लैंडर विक्रम और रोवर प्रज्ञान था, तथा मिशन का प्रक्षेपण LVM3 से हुआ (चंद्रयान-1 का प्रक्षेपण PSLV से हुआ था)। सोवियत संघ, अमेरिका और चीन के बाद भारत चंद्रमा पर सॉफ्ट लैंडिंग करने वाला चौथा देश था।"},
  {"id":"gk-science-tech-27","question":"Match the missile with its type: 1. Prithvi  2. Astra  3. Nag  4. Nirbhay; a. Beyond-visual-range air-to-air missile  b. Anti-tank guided missile  c. Surface-to-surface ballistic missile  d. Long-range subsonic cruise missile","options":["1-c, 2-a, 3-d, 4-b","1-a, 2-c, 3-b, 4-d","1-c, 2-a, 3-b, 4-d","1-c, 2-b, 3-a, 4-d"],"answer":2,"explanation":"Prithvi: short-range surface-to-surface ballistic; Astra: air-to-air BVR; Nag: anti-tank; Nirbhay: subsonic cruise.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · UPSC Prelims","questionHi":"मिसाइल का उसके प्रकार से मिलान कीजिए: 1. पृथ्वी  2. अस्त्र  3. नाग  4. निर्भय; a. दृश्य-सीमा से परे हवा से हवा में मार करने वाली मिसाइल  b. टैंक-रोधी निर्देशित मिसाइल  c. सतह से सतह पर मार करने वाली बैलिस्टिक मिसाइल  d. लंबी दूरी की अवध्वनिक क्रूज़ मिसाइल","optionsHi":["1-c, 2-a, 3-d, 4-b","1-a, 2-c, 3-b, 4-d","1-c, 2-a, 3-b, 4-d","1-c, 2-b, 3-a, 4-d"],"explanationHi":"पृथ्वी: कम दूरी की सतह से सतह पर मार करने वाली बैलिस्टिक; अस्त्र: हवा से हवा में BVR; नाग: टैंक-रोधी; निर्भय: अवध्वनिक क्रूज़।"},
  {"id":"gk-science-tech-28","question":"Assertion (A): A geostationary satellite appears fixed over one point on Earth. Reason (R): It orbits in the equatorial plane, in the direction of Earth’s rotation, with a period equal to one rotation of Earth.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: matching Earth’s rotation in the equatorial plane at about 35,786 km altitude keeps the satellite over the same spot.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · UPSC Prelims","questionHi":"अभिकथन (A): भूस्थिर उपग्रह पृथ्वी पर एक ही बिंदु के ऊपर स्थिर दिखाई देता है। कारण (R): यह भूमध्यरेखीय तल में, पृथ्वी के घूर्णन की दिशा में, पृथ्वी के एक घूर्णन के बराबर आवर्तकाल के साथ परिक्रमा करता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है: लगभग 35,786 km की ऊँचाई पर भूमध्यरेखीय तल में पृथ्वी के घूर्णन के साथ मेल रखने से उपग्रह एक ही स्थान के ऊपर बना रहता है।"},
  {"id":"gk-science-tech-29","question":"Arrange in chronological order: 1. Mars Orbiter Mission  2. Launch of Aryabhata  3. Chandrayaan-1  4. Rohini launched by SLV-3","options":["2, 3, 4, 1","2, 4, 1, 3","2, 4, 3, 1","4, 2, 3, 1"],"answer":2,"explanation":"Aryabhata: 1975; SLV-3/Rohini: 1980; Chandrayaan-1: 2008; Mars Orbiter Mission: 2013.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · UPSC Prelims","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. मंगल कक्षित्र मिशन  2. आर्यभट्ट का प्रक्षेपण  3. चंद्रयान-1  4. SLV-3 द्वारा रोहिणी का प्रक्षेपण","optionsHi":["2, 3, 4, 1","2, 4, 1, 3","2, 4, 3, 1","4, 2, 3, 1"],"explanationHi":"आर्यभट्ट: 1975; SLV-3/रोहिणी: 1980; चंद्रयान-1: 2008; मंगल कक्षित्र मिशन: 2013।"},
  {"id":"gk-science-tech-30","question":"How many of these statements are correct? I. The Pokhran tests of May 1998 were code-named Operation Shakti. II. India is a signatory to the Nuclear Non-Proliferation Treaty. III. Tarapur was India’s first nuclear power plant. IV. India has signed the Comprehensive Nuclear-Test-Ban Treaty.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. India has signed neither the NPT nor the CTBT, calling both discriminatory (II and IV wrong). Tarapur began operating in 1969.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इनमें से कितने कथन सही हैं? I. मई 1998 के पोखरण परीक्षणों का सांकेतिक नाम ऑपरेशन शक्ति था। II. भारत परमाणु अप्रसार संधि का हस्ताक्षरकर्ता है। III. तारापुर भारत का पहला परमाणु ऊर्जा संयंत्र था। IV. भारत ने व्यापक परमाणु परीक्षण प्रतिबंध संधि पर हस्ताक्षर किए हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। भारत ने न तो NPT और न ही CTBT पर हस्ताक्षर किए हैं और दोनों को भेदभावपूर्ण बताता है (II और IV गलत हैं)। तारापुर ने 1969 में संचालन शुरू किया।"},
  {"id":"gk-science-tech-31","question":"Which of the following is NOT a launch vehicle of ISRO?","options":["PSLV","Vikas","LVM3","SSLV"],"answer":1,"explanation":"Vikas is ISRO’s liquid-fuel rocket engine, used in the PSLV, GSLV and LVM3; it is not a launch vehicle. SSLV, PSLV and LVM3 are all launch vehicles.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"निम्नलिखित में से कौन-सा ISRO का प्रक्षेपण यान नहीं है?","optionsHi":["PSLV","विकास","LVM3","SSLV"],"explanationHi":"विकास ISRO का द्रव-ईंधन रॉकेट इंजन है, जिसका उपयोग PSLV, GSLV और LVM3 में होता है; यह प्रक्षेपण यान नहीं है। SSLV, PSLV और LVM3 सभी प्रक्षेपण यान हैं।"},
  {"id":"gk-science-tech-32","question":"How many of these statements about the PSLV are correct? I. It has four stages. II. Its stages alternate between solid and liquid propulsion. III. In 2017 it placed 104 satellites in orbit in a single mission. IV. It launched Chandrayaan-1 in 2008.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The PSLV’s stages are solid, liquid, solid and liquid; PSLV-C37 launched 104 satellites in February 2017; PSLV-C11 launched Chandrayaan-1 in October 2008.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"PSLV के बारे में इनमें से कितने कथन सही हैं? I. इसमें चार चरण होते हैं। II. इसके चरण ठोस और द्रव प्रणोदन के बीच बारी-बारी से आते हैं। III. 2017 में इसने एक ही मिशन में 104 उपग्रह कक्षा में स्थापित किए। IV. इसने 2008 में चंद्रयान-1 का प्रक्षेपण किया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। PSLV के चरण क्रमशः ठोस, द्रव, ठोस और द्रव हैं; PSLV-C37 ने फरवरी 2017 में 104 उपग्रह प्रक्षेपित किए; PSLV-C11 ने अक्टूबर 2008 में चंद्रयान-1 का प्रक्षेपण किया।"},
  {"id":"gk-science-tech-33","question":"Match the cyber term with its meaning: 1. Ransomware  2. Spoofing  3. Botnet  4. Zero-day vulnerability; a. A flaw unknown to the vendor, with no patch yet  b. A network of infected computers controlled remotely  c. Malware that locks or encrypts data and demands payment  d. Disguising a message or website as coming from a trusted source","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-c, 2-b, 3-d, 4-a"],"answer":2,"explanation":"Ransomware encrypts data for ransom; spoofing fakes the sender’s identity; a botnet is a herd of hijacked machines; a zero-day flaw is exploited before the vendor can fix it.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"साइबर शब्द का उसके अर्थ से मिलान कीजिए: 1. रैनसमवेयर  2. स्पूफिंग  3. बॉटनेट  4. ज़ीरो-डे सुभेद्यता; a. विक्रेता को अज्ञात दोष, जिसका अभी कोई पैच नहीं है  b. दूर से नियंत्रित संक्रमित कंप्यूटरों का नेटवर्क  c. मैलवेयर जो डेटा को लॉक या एन्क्रिप्ट करके भुगतान माँगता है  d. किसी संदेश या वेबसाइट को विश्वसनीय स्रोत से आया हुआ दिखाना","optionsHi":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-c, 2-b, 3-d, 4-a"],"explanationHi":"रैनसमवेयर फिरौती के लिए डेटा एन्क्रिप्ट करता है; स्पूफिंग भेजने वाले की पहचान नकली बनाती है; बॉटनेट हाइजैक की गई मशीनों का झुंड है; ज़ीरो-डे दोष का फायदा विक्रेता के उसे ठीक करने से पहले ही उठा लिया जाता है।"},
  {"id":"gk-science-tech-34","question":"Assertion (A): NavIC is a regional rather than a global navigation system. Reason (R): Its satellites are in geostationary and inclined geosynchronous orbits that keep them over India and its surrounding region.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: unlike GPS satellites in medium Earth orbit that circle the globe, NavIC satellites stay over the Indian region, so coverage extends only about 1,500 km beyond India.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): NavIC वैश्विक नहीं, बल्कि एक क्षेत्रीय नौवहन प्रणाली है। कारण (R): इसके उपग्रह भूस्थिर तथा झुकी हुई भूतुल्यकालिक कक्षाओं में हैं, जो उन्हें भारत और उसके आसपास के क्षेत्र के ऊपर बनाए रखती हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है: पूरे विश्व की परिक्रमा करने वाले मध्यम पृथ्वी कक्षा के GPS उपग्रहों के विपरीत, NavIC के उपग्रह भारतीय क्षेत्र के ऊपर बने रहते हैं, इसलिए कवरेज भारत से केवल लगभग 1,500 km आगे तक फैला है।"},
  {"id":"gk-science-tech-35","question":"How many of these statements are correct? I. Bt cotton was approved for commercial cultivation in India in 2010. II. Commercial release of Bt brinjal in India has been under a moratorium since 2010. III. Dolly the sheep was cloned from an adult skin cell. IV. CRISPR-Cas9 is a technique for sequencing genomes.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only II is correct. Bt cotton was approved in 2002; Dolly was cloned from an adult mammary (udder) cell; and CRISPR-Cas9 is a gene-editing tool that cuts DNA at a chosen site, not a sequencing method.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इनमें से कितने कथन सही हैं? I. भारत में Bt कपास को 2010 में व्यावसायिक खेती की स्वीकृति मिली। II. भारत में Bt बैंगन का व्यावसायिक विमोचन 2010 से स्थगन (मोरेटोरियम) के अधीन है। III. डॉली भेड़ का क्लोन एक वयस्क त्वचा कोशिका से बनाया गया था। IV. CRISPR-Cas9 जीनोम अनुक्रमण की एक तकनीक है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल II सही है। Bt कपास को 2002 में स्वीकृति मिली थी; डॉली का क्लोन एक वयस्क स्तन (थन) कोशिका से बनाया गया था; और CRISPR-Cas9 जीन-संपादन का एक उपकरण है जो चुने हुए स्थान पर DNA को काटता है, अनुक्रमण की विधि नहीं।"},
  {"id":"gk-science-tech-36","question":"Match the ISRO centre with its location: 1. Vikram Sarabhai Space Centre  2. U R Rao Satellite Centre  3. Space Applications Centre  4. National Remote Sensing Centre; a. Thiruvananthapuram  b. Ahmedabad  c. Hyderabad  d. Bengaluru","options":["1-a, 2-d, 3-b, 4-c","1-a, 2-b, 3-d, 4-c","1-a, 2-d, 3-c, 4-b","1-d, 2-a, 3-b, 4-c"],"answer":0,"explanation":"VSSC (launch vehicles): Thiruvananthapuram; URSC (satellites): Bengaluru; SAC (payloads and applications): Ahmedabad; NRSC (remote-sensing data): Hyderabad.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · UPSC Prelims","questionHi":"ISRO केंद्र का उसके स्थान से मिलान कीजिए: 1. विक्रम साराभाई अंतरिक्ष केंद्र  2. U R राव उपग्रह केंद्र  3. अंतरिक्ष अनुप्रयोग केंद्र  4. राष्ट्रीय सुदूर संवेदन केंद्र; a. तिरुवनंतपुरम  b. अहमदाबाद  c. हैदराबाद  d. बेंगलुरु","optionsHi":["1-a, 2-d, 3-b, 4-c","1-a, 2-b, 3-d, 4-c","1-a, 2-d, 3-c, 4-b","1-d, 2-a, 3-b, 4-c"],"explanationHi":"VSSC (प्रक्षेपण यान): तिरुवनंतपुरम; URSC (उपग्रह): बेंगलुरु; SAC (पेलोड और अनुप्रयोग): अहमदाबाद; NRSC (सुदूर संवेदन आँकड़े): हैदराबाद।"},
  {"id":"gk-science-tech-37","question":"Which of the following is NOT an aircraft carrier?","options":["INS Vikrant","INS Arihant","INS Vikramaditya","INS Viraat"],"answer":1,"explanation":"INS Arihant is a nuclear-powered submarine. INS Vikrant (both the 1961 ship and the 2022 indigenous one), INS Vikramaditya and INS Viraat (decommissioned 2017) are carriers.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"निम्नलिखित में से कौन-सा विमानवाहक पोत नहीं है?","optionsHi":["INS विक्रांत","INS अरिहंत","INS विक्रमादित्य","INS विराट"],"explanationHi":"INS अरिहंत परमाणु-चालित पनडुब्बी है। INS विक्रांत (1961 का पोत और 2022 का स्वदेशी पोत, दोनों), INS विक्रमादित्य और INS विराट (2017 में सेवामुक्त) विमानवाहक पोत हैं।"},
  {"id":"gk-science-tech-38","question":"How many of these statements are correct? I. One byte is equal to 8 bits. II. An IPv6 address is 128 bits long. III. An IPv4 address is 64 bits long. IV. HTTPS uses port 80 by default.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. IPv4 addresses are 32 bits (III wrong), and HTTPS uses port 443; port 80 is for plain HTTP (IV wrong).","difficulty":"very-hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"इनमें से कितने कथन सही हैं? I. एक बाइट 8 बिट के बराबर होता है। II. एक IPv6 पता 128 बिट लंबा होता है। III. एक IPv4 पता 64 बिट लंबा होता है। IV. HTTPS डिफ़ॉल्ट रूप से पोर्ट 80 का उपयोग करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। IPv4 पते 32 बिट के होते हैं (III गलत) और HTTPS पोर्ट 443 का उपयोग करता है; पोर्ट 80 सामान्य HTTP के लिए है (IV गलत)।"},
  {"id":"gk-science-tech-39","question":"Assertion (A): Remote-sensing satellites are usually placed in polar sun-synchronous orbits. Reason (R): A sun-synchronous orbit keeps the satellite fixed above one point on Earth.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A is true, R is false. A sun-synchronous orbit passes over each place at the same local solar time, giving uniform lighting for images, and the polar path covers the whole globe. Staying fixed over one point describes a geostationary orbit.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): सुदूर संवेदन उपग्रह प्रायः ध्रुवीय सूर्य-तुल्यकालिक कक्षाओं में रखे जाते हैं। कारण (R): सूर्य-तुल्यकालिक कक्षा उपग्रह को पृथ्वी के एक ही बिंदु के ऊपर स्थिर रखती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"A सत्य है, R असत्य है। सूर्य-तुल्यकालिक कक्षा प्रत्येक स्थान के ऊपर से एक ही स्थानीय सौर समय पर गुज़रती है, जिससे चित्रों में एकसमान प्रकाश मिलता है, और ध्रुवीय पथ पूरे विश्व को कवर करता है। एक ही बिंदु के ऊपर स्थिर रहना भूस्थिर कक्षा का वर्णन है।"},
  {"id":"gk-science-tech-40","question":"Match the nuclear power station with its state: 1. Kudankulam  2. Kakrapar  3. Kaiga  4. Narora; a. Gujarat  b. Tamil Nadu  c. Karnataka  d. Uttar Pradesh","options":["1-a, 2-b, 3-c, 4-d","1-b, 2-c, 3-a, 4-d","1-b, 2-a, 3-d, 4-c","1-b, 2-a, 3-c, 4-d"],"answer":3,"explanation":"Kudankulam: Tamil Nadu (Russian-built VVERs); Kakrapar: Gujarat; Kaiga: Karnataka; Narora: Uttar Pradesh.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"परमाणु विद्युत केंद्र का उसके राज्य से मिलान कीजिए: 1. कुडनकुलम  2. काकरापार  3. कैगा  4. नरौरा; a. गुजरात  b. तमिलनाडु  c. कर्नाटक  d. उत्तर प्रदेश","optionsHi":["1-a, 2-b, 3-c, 4-d","1-b, 2-c, 3-a, 4-d","1-b, 2-a, 3-d, 4-c","1-b, 2-a, 3-c, 4-d"],"explanationHi":"कुडनकुलम: तमिलनाडु (रूस-निर्मित VVER); काकरापार: गुजरात; कैगा: कर्नाटक; नरौरा: उत्तर प्रदेश।"},
  {"id":"gk-science-tech-41","question":"The Indian Space Research Organisation (ISRO) was set up in:","options":["1962","1969","1975","1980"],"answer":1,"explanation":"ISRO was formed on 15 August 1969, replacing INCOSPAR (1962). The Department of Space followed in 1972.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"भारतीय अंतरिक्ष अनुसंधान संगठन (ISRO) की स्थापना कब हुई थी?","optionsHi":["1962","1969","1975","1980"],"explanationHi":"ISRO का गठन 15 अगस्त 1969 को INCOSPAR (1962) के स्थान पर हुआ। अंतरिक्ष विभाग की स्थापना 1972 में हुई।"},
  {"id":"gk-science-tech-42","question":"Gaganyaan is India's programme to:","options":["Land a rover on Mars","Send Indian astronauts into orbit on an Indian rocket","Build a space telescope","Launch navigation satellites"],"answer":1,"explanation":"Gaganyaan aims to carry an Indian crew to low Earth orbit and bring them back safely, using a human-rated LVM3.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"गगनयान भारत का कार्यक्रम है:","optionsHi":["मंगल पर रोवर उतारने का","भारतीय रॉकेट से भारतीय अंतरिक्ष यात्रियों को कक्षा में भेजने का","अंतरिक्ष दूरबीन बनाने का","नौवहन उपग्रह प्रक्षेपित करने का"],"explanationHi":"गगनयान का उद्देश्य मानव-योग्य LVM3 की सहायता से भारतीय दल को निम्न पृथ्वी कक्षा में ले जाना और सुरक्षित वापस लाना है।"},
  {"id":"gk-science-tech-43","question":"Tejas, built by Hindustan Aeronautics Limited, is India's indigenous:","options":["Light combat aircraft","Attack helicopter","Aircraft carrier","Cruise missile"],"answer":0,"explanation":"Tejas is the Light Combat Aircraft (LCA) designed by ADA and built by HAL; it entered IAF service in 2016.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"हिंदुस्तान एयरोनॉटिक्स लिमिटेड द्वारा निर्मित तेजस भारत का स्वदेशी क्या है?","optionsHi":["हल्का लड़ाकू विमान","आक्रमणकारी हेलीकॉप्टर","विमानवाहक पोत","क्रूज़ मिसाइल"],"explanationHi":"तेजस हल्का लड़ाकू विमान (LCA) है, जिसका डिज़ाइन ADA ने तैयार किया और निर्माण HAL ने किया; यह 2016 में वायुसेना में शामिल हुआ।"},
  {"id":"gk-science-tech-44","question":"The Defence Research and Development Organisation (DRDO) has its headquarters in:","options":["Bengaluru","Hyderabad","New Delhi","Pune"],"answer":2,"explanation":"DRDO, formed in 1958, is headquartered at DRDO Bhawan, New Delhi. Bengaluru is ISRO's headquarters, which makes it the tempting wrong answer.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"रक्षा अनुसंधान एवं विकास संगठन (DRDO) का मुख्यालय कहाँ है?","optionsHi":["बेंगलुरु","हैदराबाद","नई दिल्ली","पुणे"],"explanationHi":"1958 में गठित DRDO का मुख्यालय नई दिल्ली के DRDO भवन में है। बेंगलुरु ISRO का मुख्यालय है, इसीलिए यह भ्रमित करने वाला गलत उत्तर है।"},
  {"id":"gk-science-tech-45","question":"Who, later the 11th President of India, is called the 'Missile Man of India'?","options":["Homi Bhabha","A. P. J. Abdul Kalam","Vikram Sarabhai","Satish Dhawan"],"answer":1,"explanation":"Dr Kalam led the SLV-3 project at ISRO and then DRDO's Integrated Guided Missile Development Programme (Agni, Prithvi, Akash, Trishul, Nag).","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"भारत के 11वें राष्ट्रपति बने कौन व्यक्ति \"भारत के मिसाइल मैन\" कहलाते हैं?","optionsHi":["होमी भाभा","ए. पी. जे. अब्दुल कलाम","विक्रम साराभाई","सतीश धवन"],"explanationHi":"डॉ. कलाम ने ISRO में SLV-3 परियोजना का नेतृत्व किया और फिर DRDO के एकीकृत निर्देशित मिसाइल विकास कार्यक्रम (अग्नि, पृथ्वी, आकाश, त्रिशूल, नाग) का।"},
  {"id":"gk-science-tech-46","question":"INS Vikrant, commissioned in September 2022, is notable as:","options":["India's first nuclear submarine","India's first indigenously built aircraft carrier","India's largest destroyer","A former Russian carrier"],"answer":1,"explanation":"The new INS Vikrant was designed by the Navy and built at Cochin Shipyard. INS Vikramaditya is the former Russian Admiral Gorshkov.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"सितंबर 2022 में सेवा में शामिल INS विक्रांत किस रूप में उल्लेखनीय है?","optionsHi":["भारत की पहली परमाणु पनडुब्बी","भारत का पहला स्वदेशी रूप से निर्मित विमानवाहक पोत","भारत का सबसे बड़ा विध्वंसक पोत","पूर्व रूसी विमानवाहक पोत"],"explanationHi":"नए INS विक्रांत का डिज़ाइन नौसेना ने तैयार किया और इसका निर्माण कोचीन शिपयार्ड में हुआ। INS विक्रमादित्य पूर्व रूसी एडमिरल गोर्शकोव है।"},
  {"id":"gk-science-tech-47","question":"Chandrayaan-2 (2019) lost its lander Vikram during the descent. Which part of the mission continues to work?","options":["The rover Pragyan","The orbiter","The lander's seismometer","Nothing; the mission ended"],"answer":1,"explanation":"The Chandrayaan-2 orbiter kept circling the Moon and even served as a communication backup for Chandrayaan-3's lander in 2023.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"चंद्रयान-2 (2019) ने अवतरण के दौरान अपना लैंडर विक्रम खो दिया। मिशन का कौन-सा भाग आज भी कार्य कर रहा है?","optionsHi":["रोवर प्रज्ञान","कक्षित्र (ऑर्बिटर)","लैंडर का भूकंपमापी","कुछ नहीं; मिशन समाप्त हो गया"],"explanationHi":"चंद्रयान-2 का ऑर्बिटर चंद्रमा की परिक्रमा करता रहा और 2023 में चंद्रयान-3 के लैंडर के लिए संचार के बैकअप के रूप में भी काम आया।"},
  {"id":"gk-science-tech-48","question":"With the SpaDeX mission, India in January 2025 became the fourth country to:","options":["Land on the Moon","Dock two spacecraft in orbit","Send a probe to Mars","Launch a space station module"],"answer":1,"explanation":"SpaDeX docked two small satellites (SDX01 and SDX02) on 16 January 2025, after the USA, Russia and China.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"SpaDeX मिशन के साथ भारत जनवरी 2025 में किस कार्य को करने वाला चौथा देश बना?","optionsHi":["चंद्रमा पर उतरने वाला","कक्षा में दो अंतरिक्ष यानों को जोड़ने (डॉकिंग) वाला","मंगल पर अंतरिक्ष यान भेजने वाला","अंतरिक्ष स्टेशन का मॉड्यूल प्रक्षेपित करने वाला"],"explanationHi":"SpaDeX ने अमेरिका, रूस और चीन के बाद 16 जनवरी 2025 को दो छोटे उपग्रहों (SDX01 और SDX02) को जोड़ा।"},
  {"id":"gk-science-tech-49","question":"In computing, a 'firewall' is used to:","options":["Cool the processor","Monitor and control network traffic according to security rules","Recover deleted files","Speed up the internet connection"],"answer":1,"explanation":"A firewall, in hardware or software, filters incoming and outgoing traffic to block unauthorised access.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कंप्यूटिंग में \"फ़ायरवॉल\" का उपयोग किसलिए किया जाता है?","optionsHi":["प्रोसेसर को ठंडा रखने के लिए","सुरक्षा नियमों के अनुसार नेटवर्क ट्रैफ़िक की निगरानी और नियंत्रण के लिए","मिटाई गई फ़ाइलें वापस पाने के लिए","इंटरनेट कनेक्शन की गति बढ़ाने के लिए"],"explanationHi":"फ़ायरवॉल, हार्डवेयर या सॉफ़्टवेयर के रूप में, अनधिकृत पहुँच रोकने के लिए आने-जाने वाले ट्रैफ़िक को छानता है।"},
  {"id":"gk-science-tech-50","question":"The Bhabha Atomic Research Centre (BARC) is located at:","options":["Kalpakkam","Tarapur","Trombay, Mumbai","Narora"],"answer":2,"explanation":"BARC is at Trombay in Mumbai. Kalpakkam hosts the Indira Gandhi Centre for Atomic Research, while Tarapur and Narora are power stations.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"भाभा परमाणु अनुसंधान केंद्र (BARC) कहाँ स्थित है?","optionsHi":["कलपक्कम","तारापुर","ट्रॉम्बे, मुंबई","नरौरा"],"explanationHi":"BARC मुंबई के ट्रॉम्बे में है। कलपक्कम में इंदिरा गांधी परमाणु अनुसंधान केंद्र है, जबकि तारापुर और नरौरा विद्युत केंद्र हैं।"},
  {"id":"gk-science-tech-51","question":"In February 2017 ISRO set a record by launching how many satellites on a single rocket (PSLV-C37)?","options":["83","104","130","143"],"answer":1,"explanation":"PSLV-C37 placed 104 satellites in orbit, most of them small foreign satellites. SpaceX later exceeded this with 143 on one rocket in 2021.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"फरवरी 2017 में ISRO ने एक ही रॉकेट (PSLV-C37) से कितने उपग्रह प्रक्षेपित करके रिकॉर्ड बनाया?","optionsHi":["83","104","130","143"],"explanationHi":"PSLV-C37 ने 104 उपग्रह कक्षा में स्थापित किए, जिनमें अधिकांश छोटे विदेशी उपग्रह थे। बाद में SpaceX ने 2021 में एक रॉकेट से 143 उपग्रह भेजकर इसे पार कर लिया।"},
  {"id":"gk-science-tech-52","question":"CRISPR-Cas9 is a technology used for:","options":["Editing genes at specific locations in DNA","Producing nuclear fuel","Storing data in the cloud","Detecting gravitational waves"],"answer":0,"explanation":"CRISPR-Cas9 acts like molecular scissors guided by RNA to cut DNA at a chosen site; Charpentier and Doudna won the 2020 Chemistry Nobel for it.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"CRISPR-Cas9 प्रौद्योगिकी का उपयोग किसके लिए किया जाता है?","optionsHi":["DNA में विशिष्ट स्थानों पर जीन का संपादन करने के लिए","नाभिकीय ईंधन बनाने के लिए","क्लाउड में डेटा संग्रहीत करने के लिए","गुरुत्वीय तरंगों का पता लगाने के लिए"],"explanationHi":"CRISPR-Cas9 RNA द्वारा निर्देशित आणविक कैंची की तरह काम करता है, जो चुने हुए स्थान पर DNA को काटता है; इसके लिए शार्पेंटियर और डूडना को 2020 का रसायन विज्ञान का नोबेल पुरस्कार मिला।"},
  {"id":"gk-science-tech-53","question":"The Unified Payments Interface (UPI) was developed by:","options":["The Reserve Bank of India","The State Bank of India","The National Payments Corporation of India","The Ministry of Electronics and IT"],"answer":2,"explanation":"NPCI, an RBI-promoted body owned by banks, launched UPI in 2016. RBI regulates the system but did not build it.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"एकीकृत भुगतान इंटरफ़ेस (UPI) का विकास किसने किया?","optionsHi":["भारतीय रिज़र्व बैंक","भारतीय स्टेट बैंक","भारतीय राष्ट्रीय भुगतान निगम","इलेक्ट्रॉनिकी और सूचना प्रौद्योगिकी मंत्रालय"],"explanationHi":"NPCI, जो RBI द्वारा प्रवर्तित और बैंकों के स्वामित्व वाली संस्था है, ने 2016 में UPI शुरू किया। RBI इस प्रणाली का नियमन करता है, पर उसने इसे बनाया नहीं।"},
  {"id":"gk-science-tech-54","question":"Rafale fighter aircraft bought by the Indian Air Force are made in:","options":["Russia","France","Sweden","United States"],"answer":1,"explanation":"Rafale is made by Dassault Aviation of France; the first jets reached India in 2020.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"भारतीय वायुसेना द्वारा खरीदे गए राफेल लड़ाकू विमान कहाँ बने हैं?","optionsHi":["रूस","फ्रांस","स्वीडन","संयुक्त राज्य अमेरिका"],"explanationHi":"राफेल फ्रांस की दसॉ एविएशन द्वारा बनाया जाता है; पहले विमान 2020 में भारत पहुँचे।"},
  {"id":"gk-science-tech-55","question":"Which ISRO launch vehicle was developed specifically to place small satellites (up to about 500 kg) in low Earth orbit at short notice?","options":["PSLV","GSLV","SSLV","LVM3"],"answer":2,"explanation":"The Small Satellite Launch Vehicle is a three-stage solid rocket with a liquid trim module; its first successful flight was SSLV-D2 in February 2023.","difficulty":"hard","source":"UPSC Prelims","questionHi":"ISRO का कौन-सा प्रक्षेपण यान विशेष रूप से छोटे उपग्रहों (लगभग 500 kg तक) को अल्प सूचना पर निम्न पृथ्वी कक्षा में स्थापित करने के लिए विकसित किया गया?","optionsHi":["PSLV","GSLV","SSLV","LVM3"],"explanationHi":"लघु उपग्रह प्रक्षेपण यान तीन चरणों वाला ठोस रॉकेट है जिसमें एक द्रव ट्रिम मॉड्यूल होता है; इसकी पहली सफल उड़ान फरवरी 2023 में SSLV-D2 की थी।"},
  {"id":"gk-science-tech-56","question":"Pralay, developed by DRDO, is a:","options":["Long-range cruise missile","Short-range quasi-ballistic surface-to-surface missile","Anti-tank missile","Submarine-launched ballistic missile"],"answer":1,"explanation":"Pralay is a conventional short-range quasi-ballistic missile that can manoeuvre in flight to evade interceptors.","difficulty":"hard","source":"UPSC Prelims","questionHi":"DRDO द्वारा विकसित प्रलय क्या है?","optionsHi":["लंबी दूरी की क्रूज़ मिसाइल","कम दूरी की अर्ध-बैलिस्टिक सतह से सतह पर मार करने वाली मिसाइल","टैंक-रोधी मिसाइल","पनडुब्बी से दागी जाने वाली बैलिस्टिक मिसाइल"],"explanationHi":"प्रलय पारंपरिक वारहेड वाली कम दूरी की अर्ध-बैलिस्टिक मिसाइल है, जो अवरोधकों से बचने के लिए उड़ान के दौरान दिशा बदल सकती है।"},
  {"id":"gk-science-tech-57","question":"'Prachand', inducted into the Indian Air Force in October 2022, is:","options":["An indigenous light combat helicopter","A main battle tank","A stealth frigate","An unmanned aerial vehicle"],"answer":0,"explanation":"Prachand is HAL's Light Combat Helicopter, designed to operate at very high altitudes such as the Siachen region.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अक्टूबर 2022 में भारतीय वायुसेना में शामिल किया गया \"प्रचंड\" क्या है?","optionsHi":["स्वदेशी हल्का लड़ाकू हेलीकॉप्टर","मुख्य युद्धक टैंक","स्टेल्थ फ्रिगेट","मानवरहित हवाई वाहन"],"explanationHi":"प्रचंड HAL का हल्का लड़ाकू हेलीकॉप्टर है, जिसे सियाचिन क्षेत्र जैसी अत्यधिक ऊँचाई पर संचालन के लिए डिज़ाइन किया गया है।"},
  {"id":"gk-science-tech-58","question":"The Prototype Fast Breeder Reactor at Kalpakkam uses:","options":["Natural uranium fuel and heavy water coolant","Uranium–plutonium mixed oxide fuel and liquid sodium coolant","Thorium fuel and light water coolant","Enriched uranium fuel and helium coolant"],"answer":1,"explanation":"The 500 MWe PFBR runs on U–Pu MOX fuel cooled by liquid sodium; it belongs to the second stage of India's nuclear programme. Heavy water is used in the first-stage PHWRs.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कलपक्कम स्थित प्रोटोटाइप फास्ट ब्रीडर रिएक्टर में क्या उपयोग होता है?","optionsHi":["प्राकृतिक यूरेनियम ईंधन और भारी जल शीतलक","यूरेनियम–प्लूटोनियम मिश्रित ऑक्साइड ईंधन और द्रव सोडियम शीतलक","थोरियम ईंधन और हल्का जल शीतलक","समृद्ध यूरेनियम ईंधन और हीलियम शीतलक"],"explanationHi":"500 MWe का PFBR U–Pu MOX ईंधन पर चलता है जिसे द्रव सोडियम से ठंडा किया जाता है; यह भारत के परमाणु कार्यक्रम के दूसरे चरण का अंग है। भारी जल का उपयोग प्रथम चरण के PHWR में होता है।"},
  {"id":"gk-science-tech-59","question":"Vyommitra, associated with the Gaganyaan programme, is:","options":["The crew capsule","A female humanoid robot to fly on uncrewed test missions","The tracking ship","The astronaut training centre"],"answer":1,"explanation":"Vyommitra is a half-humanoid robot that will monitor the crew module on uncrewed flights before astronauts fly.","difficulty":"hard","source":"UPSC Prelims","questionHi":"गगनयान कार्यक्रम से जुड़ा \"व्योममित्र\" क्या है?","optionsHi":["चालक दल का कैप्सूल","मानवरहित परीक्षण उड़ानों में भेजा जाने वाला महिला ह्यूमनॉइड रोबोट","अनुवीक्षण पोत","अंतरिक्ष यात्री प्रशिक्षण केंद्र"],"explanationHi":"व्योममित्र आधा-मानवाकार रोबोट है, जो अंतरिक्ष यात्रियों के उड़ान भरने से पहले मानवरहित उड़ानों में क्रू मॉड्यूल की निगरानी करेगा।"},
  {"id":"gk-science-tech-60","question":"Shukrayaan, ISRO's planned mission approved by the Union Cabinet in 2024, is meant to study:","options":["Mercury","Venus","Jupiter's moons","An asteroid"],"answer":1,"explanation":"The Venus Orbiter Mission (Shukrayaan) will study Venus's surface, atmosphere and its interaction with the Sun. 'Shukra' is the Sanskrit name for Venus.","difficulty":"hard","source":"UPSC Prelims","questionHi":"2024 में केंद्रीय मंत्रिमंडल द्वारा स्वीकृत ISRO का प्रस्तावित मिशन शुक्रयान किसके अध्ययन के लिए है?","optionsHi":["बुध","शुक्र","बृहस्पति के चंद्रमा","एक क्षुद्रग्रह"],"explanationHi":"शुक्र कक्षित्र मिशन (शुक्रयान) शुक्र की सतह, उसके वायुमंडल और सूर्य के साथ उसकी अंतःक्रिया का अध्ययन करेगा। \"शुक्र\" संस्कृत में Venus का नाम है।"},
  {"id":"gk-science-tech-61","question":"The National Quantum Mission, to develop quantum computing, communication and sensing, was approved by the Union Cabinet in:","options":["2019","2021","2023","2025"],"answer":2,"explanation":"The Cabinet approved the mission in April 2023 with an outlay of about Rs 6,000 crore over eight years (2023–31).","difficulty":"hard","source":"UPSC Prelims","questionHi":"क्वांटम कंप्यूटिंग, संचार और संवेदन विकसित करने वाले राष्ट्रीय क्वांटम मिशन को केंद्रीय मंत्रिमंडल ने किस वर्ष स्वीकृति दी?","optionsHi":["2019","2021","2023","2025"],"explanationHi":"मंत्रिमंडल ने यह मिशन अप्रैल 2023 में आठ वर्षों (2023–31) के लिए लगभग ₹6,000 करोड़ के परिव्यय के साथ स्वीकृत किया।"},
  {"id":"gk-science-tech-62","question":"The PARAM series of supercomputers is developed by:","options":["ISRO","C-DAC","DRDO","IIT Bombay"],"answer":1,"explanation":"The Centre for Development of Advanced Computing built PARAM 8000 (1991) and later systems under the National Supercomputing Mission.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"सुपरकंप्यूटरों की PARAM श्रृंखला का विकास किसने किया है?","optionsHi":["ISRO","C-DAC","DRDO","IIT बॉम्बे"],"explanationHi":"प्रगत संगणन विकास केंद्र (C-DAC) ने PARAM 8000 (1991) और बाद में राष्ट्रीय सुपरकंप्यूटिंग मिशन के अंतर्गत अन्य प्रणालियाँ बनाईं।"},
  {"id":"gk-science-tech-63","question":"Agni-Prime (Agni-P), tested by DRDO, is a:","options":["New-generation, canister-launched medium-range ballistic missile","Surface-to-air missile","Hypersonic glide vehicle","Ship-launched cruise missile"],"answer":0,"explanation":"Agni-Prime is a two-stage, solid-fuel, nuclear-capable ballistic missile with a range of 1,000–2,000 km, launched from a canister for quick deployment.","difficulty":"hard","source":"UPSC Prelims","questionHi":"DRDO द्वारा परीक्षण की गई अग्नि-प्राइम (Agni-P) क्या है?","optionsHi":["नई पीढ़ी की, कैनिस्टर से दागी जाने वाली मध्यम दूरी की बैलिस्टिक मिसाइल","सतह से हवा में मार करने वाली मिसाइल","अतिध्वनिक ग्लाइड वाहन","पोत से दागी जाने वाली क्रूज़ मिसाइल"],"explanationHi":"अग्नि-प्राइम दो चरणों वाली, ठोस ईंधन से चलने वाली, परमाणु-सक्षम बैलिस्टिक मिसाइल है जिसकी मारक सीमा 1,000–2,000 km है; इसे शीघ्र तैनाती के लिए कैनिस्टर से दागा जाता है।"},
  {"id":"gk-science-tech-64","question":"NISAR, the Earth-observation radar satellite launched on a GSLV in July 2025, was built jointly by ISRO and:","options":["ESA","JAXA","NASA","Roscosmos"],"answer":2,"explanation":"NASA-ISRO Synthetic Aperture Radar carries NASA's L-band and ISRO's S-band radar to map changes in land, ice and vegetation.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जुलाई 2025 में GSLV से प्रक्षेपित पृथ्वी-अवलोकन रडार उपग्रह NISAR को ISRO और किसने मिलकर बनाया?","optionsHi":["ESA","JAXA","NASA","रॉसकॉसमॉस"],"explanationHi":"NASA-ISRO सिंथेटिक अपर्चर रडार में NASA का L-बैंड और ISRO का S-बैंड रडार लगा है, जो भूमि, बर्फ और वनस्पति में होने वाले परिवर्तनों का मानचित्रण करता है।"},
  {"id":"gk-science-tech-65","question":"India plans to complete its own space station, the Bharatiya Antariksh Station, by:","options":["2028","2030","2035","2040"],"answer":2,"explanation":"The government's plan is for the first module (BAS-1) around 2028 and the full station by 2035, with an Indian on the Moon by 2040.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत अपना स्वयं का अंतरिक्ष स्टेशन, भारतीय अंतरिक्ष स्टेशन, किस वर्ष तक पूरा करने की योजना बना रहा है?","optionsHi":["2028","2030","2035","2040"],"explanationHi":"सरकार की योजना है कि पहला मॉड्यूल (BAS-1) लगभग 2028 में और पूरा स्टेशन 2035 तक तैयार हो, तथा 2040 तक चंद्रमा पर भारतीय पहुँचे।"},
  {"id":"gk-science-tech-66","question":"IN-SPACe, set up in 2020, is:","options":["ISRO's new launch pad","A single-window agency that authorises and promotes private space activities","India's space defence command","A satellite navigation system"],"answer":1,"explanation":"The Indian National Space Promotion and Authorisation Centre, under the Department of Space, authorises and hand-holds non-government space companies.","difficulty":"hard","source":"UPSC Prelims","questionHi":"2020 में स्थापित IN-SPACe क्या है?","optionsHi":["ISRO का नया प्रक्षेपण स्थल","एकल-खिड़की एजेंसी जो निजी अंतरिक्ष गतिविधियों को अधिकृत और प्रोत्साहित करती है","भारत का अंतरिक्ष रक्षा कमान","उपग्रह नौवहन प्रणाली"],"explanationHi":"अंतरिक्ष विभाग के अधीन भारतीय राष्ट्रीय अंतरिक्ष संवर्धन एवं प्राधिकरण केंद्र गैर-सरकारी अंतरिक्ष कंपनियों को अधिकृत करता है और उनकी सहायता करता है।"},
  {"id":"gk-science-tech-67","question":"Agnikul Cosmos's Agnibaan SOrTeD, launched in May 2024, was notable for using:","options":["The world's first single-piece 3D-printed semi-cryogenic engine","A nuclear thermal engine","A reusable first stage that landed at sea","Solar sails"],"answer":0,"explanation":"Its Agnilet engine, printed in one piece, burns kerosene with liquid oxygen; it flew from Agnikul's private launch pad at Sriharikota.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मई 2024 में प्रक्षेपित अग्निकुल कॉसमॉस का अग्निबाण SOrTeD किस कारण उल्लेखनीय था?","optionsHi":["विश्व का पहला एक-खंड वाला 3D-प्रिंटेड अर्ध-क्रायोजेनिक इंजन","नाभिकीय ऊष्मीय इंजन","पुनः उपयोग योग्य पहला चरण जो समुद्र में उतरा","सौर पाल"],"explanationHi":"इसका अग्निलेट इंजन, जो एक ही खंड में प्रिंट किया गया, केरोसिन को द्रव ऑक्सीजन के साथ जलाता है; इसने श्रीहरिकोटा में अग्निकुल के निजी प्रक्षेपण स्थल से उड़ान भरी।"},
  {"id":"gk-science-tech-68","question":"Arrange in chronological order: 1. SpaDeX docking 2. Chandrayaan-3 landing 3. Mars Orbiter Mission enters Mars orbit 4. PSLV-C37 launches 104 satellites","options":["3-4-2-1","4-3-2-1","3-2-4-1","3-4-1-2"],"answer":0,"explanation":"MOM entered Mars orbit in September 2014; PSLV-C37 flew in February 2017; Chandrayaan-3 landed in August 2023; SpaDeX docked in January 2025.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. SpaDeX डॉकिंग 2. चंद्रयान-3 की लैंडिंग 3. मंगल कक्षित्र मिशन का मंगल की कक्षा में प्रवेश 4. PSLV-C37 द्वारा 104 उपग्रहों का प्रक्षेपण","optionsHi":["3-4-2-1","4-3-2-1","3-2-4-1","3-4-1-2"],"explanationHi":"MOM ने सितंबर 2014 में मंगल की कक्षा में प्रवेश किया; PSLV-C37 ने फरवरी 2017 में उड़ान भरी; चंद्रयान-3 अगस्त 2023 में उतरा; SpaDeX की डॉकिंग जनवरी 2025 में हुई।"},
  {"id":"gk-science-tech-69","question":"Match the mission or vehicle with its purpose: A. Vikram-S B. Pushpak (RLV-LEX) C. Gaganyaan TV-D1 D. POEM — 1. Test of the crew escape system 2. Using the spent fourth stage of PSLV as an orbital platform 3. First privately built rocket launched from India 4. Autonomous landing test of a reusable winged vehicle","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2"],"answer":2,"explanation":"Vikram-S (Skyroot, November 2022) – first private rocket; Pushpak – RLV landing experiments; TV-D1 (October 2023) – crew escape test; POEM – PSLV Orbital Experimental Module.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मिशन या यान का उसके उद्देश्य से मिलान कीजिए: A. विक्रम-S B. पुष्पक (RLV-LEX) C. गगनयान TV-D1 D. POEM — 1. चालक दल निकास प्रणाली का परीक्षण 2. PSLV के प्रयुक्त चौथे चरण को कक्षीय मंच के रूप में उपयोग करना 3. भारत से प्रक्षेपित पहला निजी रूप से निर्मित रॉकेट 4. पुनः उपयोग योग्य पंखयुक्त यान का स्वचालित लैंडिंग परीक्षण","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2"],"explanationHi":"विक्रम-S (स्काईरूट, नवंबर 2022) – पहला निजी रॉकेट; पुष्पक – RLV के लैंडिंग प्रयोग; TV-D1 (अक्टूबर 2023) – चालक दल निकास परीक्षण; POEM – PSLV कक्षीय प्रायोगिक मॉड्यूल।"},
  {"id":"gk-science-tech-70","question":"How many of these statements about the Gaganyaan programme are correct? I. The four astronaut-designates named in 2024 are Indian Air Force officers. II. The crew is to fly on a human-rated version of LVM3. III. The crew module is planned for a low Earth orbit of about 400 km. IV. With it India would be the fourth nation to send humans into space on its own.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The four IAF astronaut-designates were named in 2024, the crew will fly on a human-rated LVM3 to about 400 km, and India would be the fourth nation after the USSR, the USA and China.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"गगनयान कार्यक्रम के बारे में इनमें से कितने कथन सही हैं? I. 2024 में नामित चार अंतरिक्ष यात्री-नामांकित भारतीय वायुसेना के अधिकारी हैं। II. दल को LVM3 के मानव-योग्य संस्करण से उड़ान भरनी है। III. क्रू मॉड्यूल के लिए लगभग 400 km की निम्न पृथ्वी कक्षा की योजना है। IV. इसके साथ भारत अपने बल पर मनुष्यों को अंतरिक्ष में भेजने वाला चौथा राष्ट्र होगा।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। वायुसेना के चार अंतरिक्ष यात्री-नामांकितों के नाम 2024 में घोषित हुए, दल मानव-योग्य LVM3 से लगभग 400 km तक उड़ान भरेगा, और सोवियत संघ, अमेरिका तथा चीन के बाद भारत चौथा राष्ट्र होगा।"},
  {"id":"gk-science-tech-71","question":"Match the naval vessel with its type: A. INS Vikramaditya B. INS Arighaat C. INS Vagsheer D. INS Surat — 1. Guided-missile destroyer 2. Diesel-electric attack submarine 3. Nuclear-powered ballistic missile submarine 4. Aircraft carrier","options":["A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Vikramaditya – aircraft carrier (ex-Admiral Gorshkov); Arighaat (2024) – second Arihant-class SSBN; Vagsheer (2025) – Kalvari (Scorpene) class submarine; Surat (2025) – Project 15B destroyer.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"नौसैनिक पोत का उसके प्रकार से मिलान कीजिए: A. INS विक्रमादित्य B. INS अरिघात C. INS वागशीर D. INS सूरत — 1. निर्देशित मिसाइल विध्वंसक पोत 2. डीज़ल-इलेक्ट्रिक आक्रमण पनडुब्बी 3. परमाणु-चालित बैलिस्टिक मिसाइल पनडुब्बी 4. विमानवाहक पोत","optionsHi":["A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"विक्रमादित्य – विमानवाहक पोत (पूर्व एडमिरल गोर्शकोव); अरिघात (2024) – अरिहंत श्रेणी की दूसरी SSBN; वागशीर (2025) – कलवरी (स्कॉर्पीन) श्रेणी की पनडुब्बी; सूरत (2025) – प्रोजेक्ट 15B विध्वंसक पोत।"},
  {"id":"gk-science-tech-72","question":"Assertion (A): Geostationary satellites give poor coverage of the polar regions. Reason (R): They stay above the equator, so from high latitudes they appear very low on the horizon or not at all.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: beyond about 81° latitude a geostationary satellite is below the horizon, which is why polar coverage needs other orbits.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): भूस्थिर उपग्रह ध्रुवीय क्षेत्रों को कमज़ोर कवरेज देते हैं। कारण (R): वे भूमध्य रेखा के ऊपर रहते हैं, इसलिए उच्च अक्षांशों से वे क्षितिज पर बहुत नीचे दिखते हैं या दिखते ही नहीं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है: लगभग 81° अक्षांश के आगे भूस्थिर उपग्रह क्षितिज के नीचे होता है, इसीलिए ध्रुवीय कवरेज के लिए अन्य कक्षाओं की आवश्यकता होती है।"},
  {"id":"gk-science-tech-73","question":"Assertion (A): A fast breeder reactor can produce more fissile material than it consumes. Reason (R): Fast neutrons in it convert fertile uranium-238 into fissile plutonium-239.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: breeding comes from the conversion of U-238 in the blanket into Pu-239, which is why breeders form India's second stage.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): तीव्र प्रजनक रिएक्टर जितनी विखंडनीय सामग्री खर्च करता है, उससे अधिक उत्पन्न कर सकता है। कारण (R): इसमें तीव्र न्यूट्रॉन उर्वर यूरेनियम-238 को विखंडनीय प्लूटोनियम-239 में बदल देते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है: प्रजनन ब्लैंकेट में U-238 के Pu-239 में रूपांतरण से होता है, इसीलिए ब्रीडर रिएक्टर भारत के दूसरे चरण का हिस्सा हैं।"},
  {"id":"gk-science-tech-74","question":"How many of these statements are correct? I. HTTPS secures web traffic using TLS encryption. II. RAM keeps its data when the power is switched off. III. ROM loses its contents when the power is switched off. IV. Linux is an open-source operating system.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and IV are correct. RAM is volatile (loses data without power) and ROM is non-volatile, the reverse of statements II and III.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. HTTPS, TLS एन्क्रिप्शन का उपयोग करके वेब ट्रैफ़िक को सुरक्षित करता है। II. बिजली बंद होने पर RAM अपना डेटा बनाए रखती है। III. बिजली बंद होने पर ROM अपनी सामग्री खो देती है। IV. Linux एक ओपन-सोर्स ऑपरेटिंग सिस्टम है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और IV सही हैं। RAM अस्थिर है (बिजली के बिना डेटा खो देती है) और ROM अस्थिर नहीं है, जो कथन II और III के ठीक विपरीत है।"},
  {"id":"gk-science-tech-75","question":"Match the term with its meaning: A. Li-Fi B. Edge computing C. Deepfake D. Quantum key distribution — 1. AI-generated fake audio or video of real people 2. Processing data near where it is produced rather than in a distant data centre 3. Sharing encryption keys using quantum states, so eavesdropping is detectable 4. Wireless data transfer using light","options":["A-4, B-2, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-4, B-1, C-2, D-3"],"answer":1,"explanation":"Li-Fi uses visible or infrared light; edge computing cuts delay by processing locally; deepfakes are synthetic media; QKD relies on the fact that measuring a quantum state disturbs it.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"शब्द का उसके अर्थ से मिलान कीजिए: A. Li-Fi B. एज कंप्यूटिंग C. डीपफ़ेक D. क्वांटम कुंजी वितरण — 1. वास्तविक लोगों के AI-निर्मित नकली ऑडियो या वीडियो 2. डेटा को दूर के डेटा सेंटर के बजाय उसके उत्पन्न होने के निकट संसाधित करना 3. क्वांटम अवस्थाओं का उपयोग करके एन्क्रिप्शन कुंजियाँ साझा करना, जिससे छिपकर सुनने का पता चल जाता है 4. प्रकाश का उपयोग करके वायरलेस डेटा स्थानांतरण","optionsHi":["A-4, B-2, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-4, B-1, C-2, D-3"],"explanationHi":"Li-Fi दृश्य या अवरक्त प्रकाश का उपयोग करता है; एज कंप्यूटिंग स्थानीय स्तर पर प्रसंस्करण करके विलंब घटाती है; डीपफ़ेक कृत्रिम मीडिया हैं; QKD इस तथ्य पर आधारित है कि क्वांटम अवस्था को मापने से वह प्रभावित हो जाती है।"},
  {"id":"gk-science-tech-76","question":"Which pair of mission and target is NOT correctly matched?","options":["Mangalyaan — Mars","Chandrayaan-3 — Moon","Aditya-L1 — Sun","XPoSat — Venus"],"answer":3,"explanation":"XPoSat (January 2024) is an X-ray polarimetry satellite in low Earth orbit studying cosmic X-ray sources such as black holes and pulsars. India's Venus mission is Shukrayaan.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मिशन और लक्ष्य का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["मंगलयान — मंगल","चंद्रयान-3 — चंद्रमा","आदित्य-L1 — सूर्य","XPoSat — शुक्र"],"explanationHi":"XPoSat (जनवरी 2024) निम्न पृथ्वी कक्षा में स्थित X-किरण ध्रुवणमापी उपग्रह है, जो ब्लैक होल और पल्सर जैसे ब्रह्मांडीय X-किरण स्रोतों का अध्ययन करता है। भारत का शुक्र मिशन शुक्रयान है।"},
  {"id":"gk-science-tech-77","question":"How many of these statements about Aditya-L1 are correct? I. It was launched by a PSLV. II. It carries seven payloads. III. One of its payloads, VELC, is a coronagraph. IV. It is India's first space-based solar observatory.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: launched on PSLV-C57 in September 2023, it carries seven instruments, including the Visible Emission Line Coronagraph, and is India's first solar mission.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"आदित्य-L1 के बारे में इनमें से कितने कथन सही हैं? I. इसे PSLV से प्रक्षेपित किया गया था। II. इसमें सात पेलोड हैं। III. इसका एक पेलोड VELC कोरोनाग्राफ है। IV. यह भारत की पहली अंतरिक्ष-आधारित सौर वेधशाला है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं: सितंबर 2023 में PSLV-C57 से प्रक्षेपित इस मिशन में सात उपकरण हैं, जिनमें दृश्य उत्सर्जन रेखा कोरोनाग्राफ भी शामिल है, और यह भारत का पहला सौर मिशन है।"},
  {"id":"gk-science-tech-78","question":"Arrange in chronological order: 1. Operation Shakti tests at Pokhran 2. Smiling Buddha test 3. Commissioning of INS Arihant 4. Mission Shakti anti-satellite test","options":["1-2-3-4","2-1-4-3","2-3-1-4","2-1-3-4"],"answer":3,"explanation":"Smiling Buddha May 1974; Operation Shakti May 1998; INS Arihant commissioned 2016; Mission Shakti ASAT test March 2019.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. पोखरण में ऑपरेशन शक्ति परीक्षण 2. स्माइलिंग बुद्धा परीक्षण 3. INS अरिहंत का सेवा में शामिल होना 4. मिशन शक्ति उपग्रह-रोधी परीक्षण","optionsHi":["1-2-3-4","2-1-4-3","2-3-1-4","2-1-3-4"],"explanationHi":"स्माइलिंग बुद्धा मई 1974; ऑपरेशन शक्ति मई 1998; INS अरिहंत 2016 में सेवा में शामिल; मिशन शक्ति ASAT परीक्षण मार्च 2019।"},
  {"id":"gk-science-tech-79","question":"How many of these statements are correct? I. DNA fingerprinting was developed by Alec Jeffreys. II. Dolly the sheep was cloned in the United States. III. Human growth hormone was the first recombinant-DNA drug approved for use (1982). IV. The first approved gene therapy trial (1990) treated ADA deficiency.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and IV are correct. Dolly was cloned at the Roslin Institute in Scotland, and the first recombinant-DNA drug approved (1982) was human insulin (Humulin); recombinant growth hormone followed in 1985.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"इनमें से कितने कथन सही हैं? I. DNA फ़िंगरप्रिंटिंग का विकास एलेक जेफ़्रीज़ ने किया। II. डॉली भेड़ का क्लोन संयुक्त राज्य अमेरिका में बनाया गया। III. मानव वृद्धि हार्मोन स्वीकृत पहली पुनर्योजी-DNA औषधि (1982) थी। IV. पहला स्वीकृत जीन थेरेपी परीक्षण (1990) ADA की कमी के उपचार के लिए था।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और IV सही हैं। डॉली का क्लोन स्कॉटलैंड के रोज़लिन इंस्टीट्यूट में बनाया गया था, और स्वीकृत पहली पुनर्योजी-DNA औषधि (1982) मानव इंसुलिन (ह्यूमुलिन) थी; पुनर्योजी वृद्धि हार्मोन 1985 में आया।"},
  {"id":"gk-science-tech-80","question":"Assertion (A): GPS satellites move in medium Earth orbit. Reason (R): Geostationary satellites orbit at about 36,000 km above the equator.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true (GPS satellites fly at about 20,200 km), but the height of geostationary satellites does not explain why GPS uses medium Earth orbit.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): GPS उपग्रह मध्यम पृथ्वी कक्षा में गति करते हैं। कारण (R): भूस्थिर उपग्रह भूमध्य रेखा से लगभग 36,000 km ऊपर परिक्रमा करते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं (GPS उपग्रह लगभग 20,200 km पर उड़ते हैं), परंतु भूस्थिर उपग्रहों की ऊँचाई यह नहीं समझाती कि GPS मध्यम पृथ्वी कक्षा का उपयोग क्यों करता है।"},
  {"id":"gk-science-tech-81","question":"Match the scientist with the role: A. Homi J. Bhabha B. Satish Dhawan C. Vikram Sarabhai D. A. P. J. Abdul Kalam — 1. Project director of SLV-3 2. Founder of TIFR and first chairman of the Atomic Energy Commission 3. Founder of the Physical Research Laboratory, Ahmedabad 4. Chairman of ISRO from 1972 to 1984","options":["A-2, B-4, C-3, D-1","A-3, B-4, C-2, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-1, D-3"],"answer":0,"explanation":"Bhabha set up TIFR (1945) and chaired the AEC (1948); Dhawan led ISRO 1972–84; Sarabhai founded PRL (1947); Kalam directed SLV-3, which orbited Rohini in 1980.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"वैज्ञानिक का उसकी भूमिका से मिलान कीजिए: A. होमी जे. भाभा B. सतीश धवन C. विक्रम साराभाई D. ए. पी. जे. अब्दुल कलाम — 1. SLV-3 के परियोजना निदेशक 2. TIFR के संस्थापक और परमाणु ऊर्जा आयोग के प्रथम अध्यक्ष 3. अहमदाबाद की भौतिक अनुसंधान प्रयोगशाला के संस्थापक 4. 1972 से 1984 तक ISRO के अध्यक्ष","optionsHi":["A-2, B-4, C-3, D-1","A-3, B-4, C-2, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-1, D-3"],"explanationHi":"भाभा ने TIFR (1945) की स्थापना की और AEC (1948) की अध्यक्षता की; धवन ने 1972–84 तक ISRO का नेतृत्व किया; साराभाई ने PRL (1947) की स्थापना की; कलाम ने SLV-3 का निर्देशन किया, जिसने 1980 में रोहिणी को कक्षा में पहुँचाया।"},
  {"id":"gk-science-tech-82","question":"How many of these statements are correct? I. CERT-In is India's national agency for responding to cyber security incidents. II. India's main law on electronic records and cyber crime is the Information Technology Act, 2000. III. The Digital Personal Data Protection Act was enacted in 2023. IV. The Supreme Court struck down Section 66A of the IT Act in 2015.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Section 66A was struck down in Shreya Singhal v. Union of India (2015) as violating free speech.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. CERT-In साइबर सुरक्षा घटनाओं पर कार्रवाई करने वाली भारत की राष्ट्रीय एजेंसी है। II. इलेक्ट्रॉनिक अभिलेखों और साइबर अपराध पर भारत का मुख्य कानून सूचना प्रौद्योगिकी अधिनियम, 2000 है। III. डिजिटल व्यक्तिगत डेटा संरक्षण अधिनियम 2023 में पारित हुआ। IV. सर्वोच्च न्यायालय ने 2015 में IT अधिनियम की धारा 66A को रद्द कर दिया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। श्रेया सिंघल बनाम भारत संघ (2015) में धारा 66A को अभिव्यक्ति की स्वतंत्रता का उल्लंघन मानते हुए रद्द किया गया।"},
  {"id":"gk-science-tech-83","question":"Which one of the following missiles was NOT developed by DRDO?","options":["Agni","Prithvi","Akash","Igla"],"answer":3,"explanation":"Igla is a Russian shoulder-fired surface-to-air missile used by Indian forces. Agni, Prithvi and Akash came from DRDO's guided missile programme.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"निम्नलिखित में से कौन-सी मिसाइल DRDO द्वारा विकसित नहीं की गई?","optionsHi":["अग्नि","पृथ्वी","आकाश","इग्ला"],"explanationHi":"इग्ला रूस की कंधे से दागी जाने वाली सतह से हवा में मार करने वाली मिसाइल है, जिसका उपयोग भारतीय सेनाएँ करती हैं। अग्नि, पृथ्वी और आकाश DRDO के निर्देशित मिसाइल कार्यक्रम से आईं।"},
  {"id":"gk-science-tech-84","question":"Match the satellite series with its main use: A. GSAT B. Cartosat C. RISAT D. Oceansat — 1. Radar imaging in all weather 2. Study of oceans and winds 3. Communication 4. High-resolution mapping","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"GSAT – communication; Cartosat – cartography and high-resolution imagery; RISAT – synthetic aperture radar imaging through clouds; Oceansat – ocean colour and winds.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"उपग्रह श्रृंखला का उसके मुख्य उपयोग से मिलान कीजिए: A. GSAT B. कार्टोसैट C. RISAT D. ओशनसैट — 1. सभी मौसम में रडार इमेजिंग 2. महासागरों और पवनों का अध्ययन 3. संचार 4. उच्च-विभेदन मानचित्रण","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"explanationHi":"GSAT – संचार; कार्टोसैट – मानचित्रकला और उच्च-विभेदन चित्र; RISAT – बादलों के आर-पार सिंथेटिक अपर्चर रडार इमेजिंग; ओशनसैट – सागरीय रंग और पवनें।"},
  {"id":"gk-science-tech-85","question":"Assertion (A): The fourth stage of the PSLV uses cryogenic propulsion. Reason (R): Cryogenic stages burn liquid hydrogen with liquid oxygen.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"A is false: PSLV's fourth stage (PS4) uses storable liquid propellants (MMH and mixed oxides of nitrogen); cryogenic stages are on GSLV and LVM3. R is true.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): PSLV का चौथा चरण क्रायोजेनिक प्रणोदन का उपयोग करता है। कारण (R): क्रायोजेनिक चरण द्रव हाइड्रोजन को द्रव ऑक्सीजन के साथ जलाते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"A असत्य है: PSLV का चौथा चरण (PS4) भंडारणीय द्रव प्रणोदकों (MMH और नाइट्रोजन के मिश्रित ऑक्साइड) का उपयोग करता है; क्रायोजेनिक चरण GSLV और LVM3 में होते हैं। R सत्य है।"},
  {"id":"gk-science-tech-86","question":"The World Wide Web was invented in 1989 by:","options":["Bill Gates","Tim Berners-Lee","Vint Cerf","Steve Jobs"],"answer":1,"explanation":"Tim Berners-Lee proposed the Web at CERN, creating HTML, HTTP and URLs. Vint Cerf co-designed the TCP/IP protocols of the internet, which the Web runs on.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"वर्ल्ड वाइड वेब का आविष्कार 1989 में किसने किया?","optionsHi":["बिल गेट्स","टिम बर्नर्स-ली","विंट सर्फ़","स्टीव जॉब्स"],"explanationHi":"टिम बर्नर्स-ली ने CERN में वेब का प्रस्ताव रखा और HTML, HTTP तथा URL की रचना की। विंट सर्फ़ ने इंटरनेट के TCP/IP प्रोटोकॉल का सह-डिज़ाइन किया, जिस पर वेब चलता है।"},
  {"id":"gk-science-tech-87","question":"In web addresses, URL stands for:","options":["Universal Routing Link","Unified Resource Line","Uniform Resource Locator","User Request Location"],"answer":2,"explanation":"A Uniform Resource Locator gives the address of a resource on the web, such as https://www.example.com/page.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"वेब पतों में URL का पूर्ण रूप क्या है?","optionsHi":["यूनिवर्सल रूटिंग लिंक (Universal Routing Link)","यूनिफाइड रिसोर्स लाइन (Unified Resource Line)","यूनिफॉर्म रिसोर्स लोकेटर (Uniform Resource Locator)","यूज़र रिक्वेस्ट लोकेशन (User Request Location)"],"explanationHi":"यूनिफॉर्म रिसोर्स लोकेटर वेब पर किसी संसाधन का पता बताता है, जैसे https://www.example.com/page।"},
  {"id":"gk-science-tech-88","question":"Which ISRO launch vehicle is often called its “workhorse” because of its long record of successful launches?","options":["SLV-3","ASLV","SSLV","PSLV"],"answer":3,"explanation":"The Polar Satellite Launch Vehicle has launched Chandrayaan-1, the Mars Orbiter Mission and many foreign satellites. SLV-3 and ASLV were early vehicles, and SSLV is for small satellites.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"ISRO का कौन-सा प्रक्षेपण यान सफल प्रक्षेपणों के लंबे रिकॉर्ड के कारण प्रायः उसका \"वर्कहॉर्स\" कहलाता है?","optionsHi":["SLV-3","ASLV","SSLV","PSLV"],"explanationHi":"ध्रुवीय उपग्रह प्रक्षेपण यान ने चंद्रयान-1, मंगल कक्षित्र मिशन और अनेक विदेशी उपग्रह प्रक्षेपित किए हैं। SLV-3 और ASLV आरंभिक यान थे, और SSLV छोटे उपग्रहों के लिए है।"},
  {"id":"gk-science-tech-89","question":"“Cloud computing” refers to:","options":["Delivering computing services such as storage and software over the internet on demand","Using satellites to forecast weather","Storing data only on a personal hard disk","Computers powered by solar energy"],"answer":0,"explanation":"In cloud computing, users rent servers, storage or applications from remote data centres instead of owning the hardware, paying for what they use.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"\"क्लाउड कंप्यूटिंग\" से तात्पर्य है:","optionsHi":["इंटरनेट पर माँग के अनुसार भंडारण और सॉफ़्टवेयर जैसी कंप्यूटिंग सेवाएँ उपलब्ध कराना","मौसम का पूर्वानुमान लगाने के लिए उपग्रहों का उपयोग","डेटा केवल निजी हार्ड डिस्क पर संग्रहीत करना","सौर ऊर्जा से चलने वाले कंप्यूटर"],"explanationHi":"क्लाउड कंप्यूटिंग में उपयोगकर्ता हार्डवेयर का स्वामी बनने के बजाय दूरस्थ डेटा सेंटरों से सर्वर, भंडारण या एप्लिकेशन किराये पर लेते हैं और जितना उपयोग करते हैं उतना ही भुगतान करते हैं।"},
  {"id":"gk-science-tech-90","question":"A blockchain is best described as:","options":["A chain of computers linked by cables","A central database controlled by a single bank","A distributed, tamper-resistant ledger in which records are linked cryptographically in blocks","A type of computer virus"],"answer":2,"explanation":"Each block carries a cryptographic hash of the previous one, and copies are held by many participants, so altering past records is very hard. Cryptocurrencies are one application.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"ब्लॉकचेन का सबसे उपयुक्त वर्णन कौन-सा है?","optionsHi":["केबलों से जुड़े कंप्यूटरों की श्रृंखला","एक ही बैंक द्वारा नियंत्रित केंद्रीय डेटाबेस","वितरित, छेड़छाड़-रोधी बही-खाता, जिसमें अभिलेख ब्लॉकों में क्रिप्टोग्राफ़िक रूप से जुड़े होते हैं","एक प्रकार का कंप्यूटर वायरस"],"explanationHi":"प्रत्येक ब्लॉक में पिछले ब्लॉक का क्रिप्टोग्राफ़िक हैश होता है और प्रतियाँ अनेक प्रतिभागियों के पास रहती हैं, इसलिए पुराने अभिलेखों को बदलना बहुत कठिन है। क्रिप्टोकरेंसी इसका एक अनुप्रयोग है।"},
  {"id":"gk-science-tech-91","question":"IPv6 was introduced mainly because IPv4 was running out of addresses. How long is an IPv6 address?","options":["32 bits","64 bits","48 bits","128 bits"],"answer":3,"explanation":"IPv4 uses 32-bit addresses (about 4.3 billion), while IPv6 uses 128-bit addresses, giving an almost unlimited number. 48 bits is the length of a MAC address.","difficulty":"hard","source":"IBPS PO · SSC CGL","questionHi":"IPv6 को मुख्यतः इसलिए लाया गया क्योंकि IPv4 के पते समाप्त हो रहे थे। IPv6 पता कितना लंबा होता है?","optionsHi":["32 बिट","64 बिट","48 बिट","128 बिट"],"explanationHi":"IPv4 में 32-बिट पते (लगभग 4.3 अरब) होते हैं, जबकि IPv6 में 128-बिट पते होते हैं, जिनकी संख्या लगभग असीमित है। 48 बिट MAC पते की लंबाई है।"},
  {"id":"gk-science-tech-92","question":"LiDAR, used in self-driving cars and terrain mapping, measures distances using:","options":["Pulses of laser light and the time they take to return","Radio waves reflected from objects","Sound waves in water","Gravity variations"],"answer":0,"explanation":"Light Detection and Ranging times the echoes of laser pulses to build detailed 3-D maps. Radar uses radio waves and sonar uses sound.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"स्वचालित कारों और भू-भाग के मानचित्रण में प्रयुक्त LiDAR दूरी का मापन किसके द्वारा करता है?","optionsHi":["लेज़र प्रकाश के स्पंदों और उनके लौटने में लगे समय से","वस्तुओं से परावर्तित रेडियो तरंगों से","जल में ध्वनि तरंगों से","गुरुत्वीय विचलनों से"],"explanationHi":"लाइट डिटेक्शन एंड रेंजिंग लेज़र स्पंदों की गूँज का समय मापकर विस्तृत 3-D मानचित्र बनाता है। रडार रेडियो तरंगों का और सोनार ध्वनि का उपयोग करता है।"},
  {"id":"gk-science-tech-93","question":"Which statement best describes the relation between artificial intelligence (AI) and machine learning (ML)?","options":["They are unrelated fields","ML is a branch of AI in which systems learn patterns from data instead of following only hand-written rules","AI is a branch of ML","ML deals only with robots' hardware"],"answer":1,"explanation":"AI is the broad goal of machines performing tasks that need intelligence; ML is one approach to it, and deep learning, using many-layered neural networks, is a subset of ML.","difficulty":"hard","source":"UPSC Prelims · IBPS PO","questionHi":"कृत्रिम बुद्धिमत्ता (AI) और मशीन लर्निंग (ML) के बीच संबंध का सबसे उपयुक्त वर्णन कौन-सा है?","optionsHi":["ये असंबंधित क्षेत्र हैं","ML, AI की एक शाखा है जिसमें प्रणालियाँ केवल हाथ से लिखे नियमों का पालन करने के बजाय डेटा से पैटर्न सीखती हैं","AI, ML की एक शाखा है","ML केवल रोबोट के हार्डवेयर से संबंधित है"],"explanationHi":"AI का व्यापक लक्ष्य मशीनों से बुद्धिमत्ता की आवश्यकता वाले कार्य करवाना है; ML उसका एक तरीका है, और अनेक परतों वाले तंत्रिका नेटवर्क का उपयोग करने वाली डीप लर्निंग ML का उपसमुच्चय है।"},
  {"id":"gk-science-tech-94","question":"A vehicle or missile is described as hypersonic when its speed exceeds about:","options":["Mach 1","Mach 2","Mach 5","Mach 25"],"answer":2,"explanation":"Speeds above about five times the speed of sound are called hypersonic. Between Mach 1 and Mach 5 the flight is supersonic; BrahMos, for instance, flies at around Mach 2.8.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"किसी यान या मिसाइल को अतिध्वनिक (हाइपरसोनिक) तब कहा जाता है जब उसकी गति लगभग कितने से अधिक हो?","optionsHi":["मैक 1","मैक 2","मैक 5","मैक 25"],"explanationHi":"ध्वनि की चाल के लगभग पाँच गुना से अधिक चाल को अतिध्वनिक कहा जाता है। मैक 1 और मैक 5 के बीच उड़ान सुपरसोनिक होती है; उदाहरण के लिए, ब्रह्मोस लगभग मैक 2.8 पर उड़ती है।"},
  {"id":"gk-science-tech-95","question":"Two-factor authentication improves account security by:","options":["Asking for the same password twice","Making the password longer","Encrypting the hard disk","Requiring two different kinds of proof, such as a password and a one-time code sent to the user's phone"],"answer":3,"explanation":"It combines something you know (password) with something you have (phone, token) or something you are (fingerprint), so a stolen password alone is not enough.","difficulty":"hard","source":"IBPS PO · SSC CGL","questionHi":"द्वि-कारक प्रमाणीकरण (टू-फ़ैक्टर ऑथेंटिकेशन) खाते की सुरक्षा कैसे बढ़ाता है?","optionsHi":["एक ही पासवर्ड दो बार पूछकर","पासवर्ड को लंबा बनाकर","हार्ड डिस्क को एन्क्रिप्ट करके","दो अलग-अलग प्रकार के प्रमाण माँगकर, जैसे पासवर्ड और उपयोगकर्ता के फ़ोन पर भेजा गया एक बार उपयोग होने वाला कोड"],"explanationHi":"यह कुछ ऐसा जो आप जानते हैं (पासवर्ड) को कुछ ऐसा जो आपके पास है (फ़ोन, टोकन) या जो आप हैं (फ़िंगरप्रिंट) के साथ जोड़ता है, इसलिए केवल चोरी हुआ पासवर्ड पर्याप्त नहीं होता।"},
  {"id":"gk-science-tech-96","question":"Match the orbit with a typical use. A. Low Earth orbit (a few hundred km)  B. Medium Earth orbit (about 20,000 km)  C. Geostationary orbit (about 36,000 km)  D. Sun-synchronous polar orbit; 1. Earth-observation satellites that pass over a place at the same local time  2. Communication and weather satellites fixed over one longitude  3. GPS navigation satellites  4. The International Space Station","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"The ISS circles at about 400 km; GPS satellites orbit at about 20,200 km; geostationary satellites at 35,786 km above the equator; remote-sensing satellites such as Cartosat use sun-synchronous polar orbits.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कक्षा का उसके सामान्य उपयोग से मिलान कीजिए। A. निम्न पृथ्वी कक्षा (कुछ सौ km)  B. मध्यम पृथ्वी कक्षा (लगभग 20,000 km)  C. भूस्थिर कक्षा (लगभग 36,000 km)  D. सूर्य-तुल्यकालिक ध्रुवीय कक्षा; 1. पृथ्वी-अवलोकन उपग्रह जो किसी स्थान के ऊपर से एक ही स्थानीय समय पर गुज़रते हैं  2. एक ही देशांतर के ऊपर स्थिर संचार और मौसम उपग्रह  3. GPS नौवहन उपग्रह  4. अंतरराष्ट्रीय अंतरिक्ष स्टेशन","optionsHi":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"ISS लगभग 400 km पर परिक्रमा करता है; GPS उपग्रह लगभग 20,200 km पर; भूस्थिर उपग्रह भूमध्य रेखा के ऊपर 35,786 km पर; और कार्टोसैट जैसे सुदूर संवेदन उपग्रह सूर्य-तुल्यकालिक ध्रुवीय कक्षाओं का उपयोग करते हैं।"},
  {"id":"gk-science-tech-97","question":"How many of these statements about missiles are correct? I. A ballistic missile is powered only in its early phase and then follows a largely free-falling arc. II. A cruise missile is powered for most of its flight and stays within the atmosphere. III. BrahMos is a cruise missile. IV. The Agni series consists of cruise missiles.","options":["Only one","Only three","Only two","All four"],"answer":1,"explanation":"I, II and III are correct. Agni missiles are ballistic missiles of increasing range, so IV is wrong; Nirbhay is India's subsonic cruise missile.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मिसाइलों के बारे में इनमें से कितने कथन सही हैं? I. बैलिस्टिक मिसाइल केवल आरंभिक चरण में संचालित होती है और फिर मुख्यतः मुक्त रूप से गिरते हुए चाप-पथ पर चलती है। II. क्रूज़ मिसाइल अपनी अधिकांश उड़ान में संचालित रहती है और वायुमंडल के भीतर ही रहती है। III. ब्रह्मोस एक क्रूज़ मिसाइल है। IV. अग्नि श्रृंखला क्रूज़ मिसाइलों की है।","optionsHi":["केवल एक","केवल तीन","केवल दो","सभी चार"],"explanationHi":"I, II और III सही हैं। अग्नि मिसाइलें बढ़ती मारक सीमा वाली बैलिस्टिक मिसाइलें हैं, इसलिए IV गलत है; निर्भय भारत की अवध्वनिक क्रूज़ मिसाइल है।"},
  {"id":"gk-science-tech-98","question":"Assertion (A): A cryogenic upper stage lets a rocket place heavier satellites in high orbits than a stage of the same mass using conventional propellants. Reason (R): Liquid hydrogen burnt with liquid oxygen gives a very high exhaust velocity (high specific impulse).","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Higher exhaust velocity means more thrust per kilogram of propellant, which matters most in the upper stage; that is why GSLV and LVM3 needed cryogenic stages to reach geostationary transfer orbit with heavy payloads.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): क्रायोजेनिक ऊपरी चरण रॉकेट को, पारंपरिक प्रणोदकों वाले समान द्रव्यमान के चरण की तुलना में, भारी उपग्रहों को ऊँची कक्षाओं में स्थापित करने में सक्षम बनाता है। कारण (R): द्रव हाइड्रोजन को द्रव ऑक्सीजन के साथ जलाने पर बहुत उच्च निष्कासन वेग (उच्च विशिष्ट आवेग) मिलता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"अधिक निष्कासन वेग का अर्थ है प्रति किलोग्राम प्रणोदक अधिक प्रणोद, जो ऊपरी चरण में सबसे अधिक महत्त्व रखता है; इसीलिए GSLV और LVM3 को भारी पेलोड के साथ भूस्थिर स्थानांतरण कक्षा तक पहुँचने के लिए क्रायोजेनिक चरणों की आवश्यकता पड़ी।"},
  {"id":"gk-science-tech-99","question":"How many of these statements about quantum computing are correct? I. A qubit can exist in a superposition of 0 and 1. II. Entanglement links the states of qubits so that they cannot be described independently. III. A large enough quantum computer running Shor's algorithm could break widely used RSA encryption. IV. Quantum computers are expected to replace classical computers for all everyday tasks.","options":["Only one","Only two","All four","Only three"],"answer":3,"explanation":"I, II and III are correct, which is why post-quantum cryptography is being developed. Quantum machines excel only at certain problems, such as factoring or simulating molecules, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"क्वांटम कंप्यूटिंग के बारे में इनमें से कितने कथन सही हैं? I. क्यूबिट 0 और 1 की अध्यारोपण (सुपरपोज़िशन) अवस्था में रह सकता है। II. उलझाव (एंटैंगलमेंट) क्यूबिटों की अवस्थाओं को इस प्रकार जोड़ता है कि उन्हें स्वतंत्र रूप से वर्णित नहीं किया जा सकता। III. पर्याप्त बड़ा क्वांटम कंप्यूटर, शोर एल्गोरिद्म चलाकर, व्यापक रूप से प्रयुक्त RSA एन्क्रिप्शन को तोड़ सकता है। IV. क्वांटम कंप्यूटरों से अपेक्षा है कि वे सभी रोज़मर्रा के कार्यों में पारंपरिक कंप्यूटरों का स्थान ले लेंगे।","optionsHi":["केवल एक","केवल दो","सभी चार","केवल तीन"],"explanationHi":"I, II और III सही हैं, इसीलिए क्वांटम-पश्चात क्रिप्टोग्राफ़ी विकसित की जा रही है। क्वांटम मशीनें केवल कुछ समस्याओं में श्रेष्ठ हैं, जैसे गुणनखंडन या अणुओं का अनुकरण, इसलिए IV गलत है।"},
  {"id":"gk-science-tech-100","question":"Assertion (A): A scramjet engine cannot start working from a standstill. Reason (R): It has no rotating compressor and depends on air entering at very high speed to compress it, with combustion taking place in supersonic airflow.","options":["A is true but R is false","A is false but R is true","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"Scramjets rely on ram compression, so a rocket or other engine must first accelerate the vehicle to high Mach numbers; ISRO tested a scramjet on a sounding rocket in 2016.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): स्क्रैमजेट इंजन स्थिर अवस्था से काम करना शुरू नहीं कर सकता। कारण (R): इसमें कोई घूमने वाला संपीडक नहीं होता और यह अत्यंत तीव्र गति से प्रवेश करने वाली वायु पर निर्भर करता है जो उसे संपीडित करती है, तथा दहन सुपरसोनिक वायु-प्रवाह में होता है।","optionsHi":["A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है"],"explanationHi":"स्क्रैमजेट रैम संपीडन पर निर्भर करते हैं, इसलिए पहले किसी रॉकेट या अन्य इंजन को यान को उच्च मैक संख्याओं तक त्वरित करना पड़ता है; ISRO ने 2016 में एक साउंडिंग रॉकेट पर स्क्रैमजेट का परीक्षण किया था।"},
  {"id":"gk-science-tech-101","question":"In computing, HTML stands for:","options":["HyperText Markup Language","High-Level Text Machine Language","Hyperlink and Text Management Language","Home Tool Markup Language"],"answer":0,"explanation":"HTML (HyperText Markup Language) describes the structure of web pages. It was created by Tim Berners-Lee along with HTTP and URLs.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"कंप्यूटिंग में HTML का पूर्ण रूप क्या है?","optionsHi":["हाइपरटेक्स्ट मार्कअप लैंग्वेज (HyperText Markup Language)","हाई-लेवल टेक्स्ट मशीन लैंग्वेज (High-Level Text Machine Language)","हाइपरलिंक एंड टेक्स्ट मैनेजमेंट लैंग्वेज (Hyperlink and Text Management Language)","होम टूल मार्कअप लैंग्वेज (Home Tool Markup Language)"],"explanationHi":"HTML (हाइपरटेक्स्ट मार्कअप लैंग्वेज) वेब पेजों की संरचना का वर्णन करती है। इसे टिम बर्नर्स-ली ने HTTP और URL के साथ बनाया था।"},
  {"id":"gk-science-tech-102","question":"APPLE, launched in 1981 on an Ariane rocket, was India's first:","options":["Remote-sensing satellite","Experimental geostationary communication satellite","Satellite launched by an Indian rocket","Weather satellite"],"answer":1,"explanation":"APPLE (Ariane Passenger PayLoad Experiment) was an experimental communication satellite placed in geostationary orbit. Rohini (1980) was the first launched by an Indian rocket and Bhaskara-I an early Earth-observation satellite.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"1981 में एरियन रॉकेट से प्रक्षेपित APPLE भारत का पहला क्या था?","optionsHi":["सुदूर संवेदन उपग्रह","प्रायोगिक भूस्थिर संचार उपग्रह","भारतीय रॉकेट से प्रक्षेपित उपग्रह","मौसम उपग्रह"],"explanationHi":"APPLE (एरियन पैसेंजर पेलोड एक्सपेरिमेंट) भूस्थिर कक्षा में स्थापित एक प्रायोगिक संचार उपग्रह था। रोहिणी (1980) भारतीय रॉकेट से प्रक्षेपित पहला उपग्रह था और भास्कर-I एक आरंभिक पृथ्वी-अवलोकन उपग्रह था।"},
  {"id":"gk-science-tech-103","question":"India's first sounding rocket was launched in November 1963 from:","options":["Balasore","Sriharikota","Thumba","Kourou"],"answer":2,"explanation":"A Nike-Apache rocket lifted off from the Thumba Equatorial Rocket Launching Station near Thiruvananthapuram, chosen because it lies close to the magnetic equator. Sriharikota came into use only in 1971.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"भारत का प्रथम साउंडिंग रॉकेट नवंबर 1963 में कहाँ से प्रक्षेपित किया गया था?","optionsHi":["बालासोर","श्रीहरिकोटा","थुंबा","कौरू"],"explanationHi":"तिरुवनंतपुरम के निकट थुंबा भूमध्यरेखीय रॉकेट प्रक्षेपण केंद्र से नाइकी-अपाचे रॉकेट ने उड़ान भरी; इसे चुनने का कारण यह था कि यह चुंबकीय भूमध्य रेखा के निकट है। श्रीहरिकोटा का उपयोग केवल 1971 में शुरू हुआ।"},
  {"id":"gk-science-tech-104","question":"Arrange in chronological order: 1. Rakesh Sharma's spaceflight  2. Launch of Sputnik 1  3. Apollo 11 Moon landing  4. Yuri Gagarin's orbital flight","options":["2-4-1-3","4-2-3-1","2-3-4-1","2-4-3-1"],"answer":3,"explanation":"Sputnik 1 was launched in 1957, Gagarin orbited Earth in 1961, Apollo 11 landed on the Moon in 1969 and Rakesh Sharma flew aboard Soyuz T-11 in 1984.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. राकेश शर्मा की अंतरिक्ष उड़ान  2. स्पुतनिक 1 का प्रक्षेपण  3. अपोलो 11 का चंद्रमा पर अवतरण  4. यूरी गगारिन की कक्षीय उड़ान","optionsHi":["2-4-1-3","4-2-3-1","2-3-4-1","2-4-3-1"],"explanationHi":"स्पुतनिक 1 का प्रक्षेपण 1957 में हुआ, गगारिन ने 1961 में पृथ्वी की परिक्रमा की, अपोलो 11 1969 में चंद्रमा पर उतरा और राकेश शर्मा ने 1984 में सोयूज़ T-11 से उड़ान भरी।"},
  {"id":"gk-science-tech-105","question":"GPS, used for satellite navigation, stands for:","options":["Global Positioning System","General Packet Service","Geographic Position Sensor","Global Path Satellite"],"answer":0,"explanation":"GPS, the Global Positioning System, is a US satellite navigation system. India's regional counterpart is NavIC.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"उपग्रह नौवहन के लिए प्रयुक्त GPS का पूर्ण रूप क्या है?","optionsHi":["ग्लोबल पोज़िशनिंग सिस्टम (Global Positioning System)","जनरल पैकेट सर्विस (General Packet Service)","जियोग्राफ़िक पोज़िशन सेंसर (Geographic Position Sensor)","ग्लोबल पाथ सैटेलाइट (Global Path Satellite)"],"explanationHi":"GPS, यानी ग्लोबल पोज़िशनिंग सिस्टम, अमेरिका की उपग्रह नौवहन प्रणाली है। भारत की क्षेत्रीय प्रणाली NavIC है।"},
  {"id":"gk-science-tech-106","question":"The Satellite Instructional Television Experiment (SITE) of 1975–76, which beamed educational programmes to Indian villages, used:","options":["India's Aryabhata satellite","NASA's ATS-6 satellite","INSAT-1A","A Soviet Molniya satellite"],"answer":1,"explanation":"SITE used the American ATS-6 satellite to reach about 2,400 villages. Aryabhata was a scientific satellite and INSAT-1A came only in 1982.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"1975–76 के सैटेलाइट इंस्ट्रक्शनल टेलीविज़न एक्सपेरिमेंट (SITE), जिसने भारतीय गाँवों तक शैक्षिक कार्यक्रम पहुँचाए, में किसका उपयोग हुआ?","optionsHi":["भारत का आर्यभट्ट उपग्रह","NASA का ATS-6 उपग्रह","INSAT-1A","सोवियत मोलनिया उपग्रह"],"explanationHi":"SITE में अमेरिकी ATS-6 उपग्रह का उपयोग हुआ, जिससे लगभग 2,400 गाँवों तक पहुँचा गया। आर्यभट्ट एक वैज्ञानिक उपग्रह था और INSAT-1A केवल 1982 में आया।"},
  {"id":"gk-science-tech-107","question":"Kalpana Chawla lost her life in 2003 when which space shuttle broke up on re-entry?","options":["Discovery","Challenger","Columbia","Atlantis"],"answer":2,"explanation":"Columbia (mission STS-107) disintegrated over Texas on 1 February 2003. Challenger exploded shortly after launch in 1986.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"कल्पना चावला की 2003 में मृत्यु तब हुई जब कौन-सा अंतरिक्ष शटल पुनःप्रवेश के समय टूट गया?","optionsHi":["डिस्कवरी","चैलेंजर","कोलंबिया","अटलांटिस"],"explanationHi":"कोलंबिया (मिशन STS-107) 1 फरवरी 2003 को टेक्सास के ऊपर बिखर गया। चैलेंजर 1986 में प्रक्षेपण के कुछ ही क्षण बाद फट गया था।"},
  {"id":"gk-science-tech-108","question":"Match the defence system with its type. A. Arjun  B. Pinaka  C. Dhanush  D. Netra; 1. Airborne early warning and control system  2. 155 mm towed artillery gun  3. Multi-barrel rocket launcher  4. Main battle tank","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"Arjun is DRDO's main battle tank, Pinaka a multi-barrel rocket launcher, Dhanush a 155 mm towed howitzer, and Netra an airborne early warning and control system mounted on an Embraer jet.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"रक्षा प्रणाली का उसके प्रकार से मिलान कीजिए। A. अर्जुन  B. पिनाका  C. धनुष  D. नेत्र; 1. हवाई पूर्व चेतावनी एवं नियंत्रण प्रणाली  2. 155 mm की खींची जाने वाली तोप  3. बहु-नलिका रॉकेट प्रक्षेपक  4. मुख्य युद्धक टैंक","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"explanationHi":"अर्जुन DRDO का मुख्य युद्धक टैंक है, पिनाका बहु-नलिका रॉकेट प्रक्षेपक, धनुष 155 mm की खींची जाने वाली हॉवित्ज़र तोप, और नेत्र एम्ब्रेयर जेट पर लगी हवाई पूर्व चेतावनी एवं नियंत्रण प्रणाली है।"},
  {"id":"gk-science-tech-109","question":"The Integrated Guided Missile Development Programme, which produced Prithvi, Agni, Akash, Trishul and Nag, was launched in:","options":["1983","1974","1990","1998"],"answer":0,"explanation":"DRDO launched the IGMDP in 1983 under A.P.J. Abdul Kalam. 1974 and 1998 were the years of the Pokhran nuclear tests.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"पृथ्वी, अग्नि, आकाश, त्रिशूल और नाग को जन्म देने वाला एकीकृत निर्देशित मिसाइल विकास कार्यक्रम किस वर्ष शुरू हुआ?","optionsHi":["1983","1974","1990","1998"],"explanationHi":"DRDO ने IGMDP की शुरुआत 1983 में ए.पी.जे. अब्दुल कलाम के नेतृत्व में की। 1974 और 1998 पोखरण परमाणु परीक्षणों के वर्ष थे।"},
  {"id":"gk-science-tech-110","question":"How many of these statements about India's nuclear programme are correct? I. APSARA at Trombay, which went critical in 1956, was the first research reactor in Asia. II. Kudankulam's reactors were built with Russian collaboration. III. The first two units at Tarapur are boiling water reactors supplied by the United States. IV. The CIRUS research reactor was supplied by France.","options":["Only two","Only three","Only one","All four"],"answer":1,"explanation":"I, II and III are correct; Tarapur's two General Electric BWRs began operating in 1969. CIRUS (Canada-India Reactor Utility Services) came from Canada, with heavy water supplied by the US, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"भारत के परमाणु कार्यक्रम के बारे में इनमें से कितने कथन सही हैं? I. ट्रॉम्बे का अप्सरा, जो 1956 में क्रांतिक अवस्था में पहुँचा, एशिया का पहला अनुसंधान रिएक्टर था। II. कुडनकुलम के रिएक्टर रूसी सहयोग से बनाए गए हैं। III. तारापुर की पहली दो इकाइयाँ संयुक्त राज्य अमेरिका द्वारा आपूर्ति किए गए उबलते जल रिएक्टर हैं। IV. CIRUS अनुसंधान रिएक्टर की आपूर्ति फ्रांस ने की थी।","optionsHi":["केवल दो","केवल तीन","केवल एक","सभी चार"],"explanationHi":"I, II और III सही हैं; तारापुर के दो जनरल इलेक्ट्रिक BWR ने 1969 में संचालन शुरू किया। CIRUS (कैनेडा-इंडिया रिएक्टर यूटिलिटी सर्विसेज़) कनाडा से आया था, जिसका भारी जल अमेरिका ने दिया, इसलिए IV गलत है।"},
  {"id":"gk-science-tech-111","question":"INSAT, the satellite system used for telecommunication, broadcasting and meteorology, stands for:","options":["Indian Navigation Satellite","International Network Satellite","Indian National Satellite System","Integrated National Space and Telecom"],"answer":2,"explanation":"INSAT is the Indian National Satellite System; its first satellite, INSAT-1A, went up in 1982. NavIC is India's navigation system.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"दूरसंचार, प्रसारण और मौसम-विज्ञान के लिए प्रयुक्त उपग्रह प्रणाली INSAT का पूर्ण रूप क्या है?","optionsHi":["इंडियन नेविगेशन सैटेलाइट (Indian Navigation Satellite)","इंटरनेशनल नेटवर्क सैटेलाइट (International Network Satellite)","इंडियन नेशनल सैटेलाइट सिस्टम (Indian National Satellite System)","इंटीग्रेटेड नेशनल स्पेस एंड टेलीकॉम (Integrated National Space and Telecom)"],"explanationHi":"INSAT भारतीय राष्ट्रीय उपग्रह प्रणाली है; इसका पहला उपग्रह INSAT-1A 1982 में प्रक्षेपित हुआ। NavIC भारत की नौवहन प्रणाली है।"},
  {"id":"gk-science-tech-112","question":"The Turing test, proposed in 1950, is meant to judge whether:","options":["A processor has enough memory for a task","A computer program will ever finish running","A code can be cracked within a fixed time","A machine can show behaviour indistinguishable from a human's in conversation"],"answer":3,"explanation":"Alan Turing proposed the ‘imitation game’ in his 1950 paper ‘Computing Machinery and Intelligence’. Whether a program halts is the separate halting problem, which he also studied.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"1950 में प्रस्तावित ट्यूरिंग परीक्षण का उद्देश्य यह आँकना है कि:","optionsHi":["किसी प्रोसेसर में किसी कार्य के लिए पर्याप्त मेमोरी है या नहीं","कोई कंप्यूटर प्रोग्राम कभी चलकर समाप्त होगा या नहीं","कोई कोड निश्चित समय में तोड़ा जा सकता है या नहीं","कोई मशीन बातचीत में मनुष्य से अभिन्न व्यवहार प्रदर्शित कर सकती है या नहीं"],"explanationHi":"एलन ट्यूरिंग ने अपने 1950 के शोधपत्र \"कंप्यूटिंग मशीनरी एंड इंटेलिजेंस\" में \"इमिटेशन गेम\" का प्रस्ताव रखा था। कोई प्रोग्राम रुकेगा या नहीं, यह अलग हॉल्टिंग समस्या है, जिसका अध्ययन उन्होंने भी किया।"},
  {"id":"gk-science-tech-113","question":"In a computer, CPU stands for:","options":["Central Processing Unit","Central Program Utility","Computer Peripheral Unit","Control Power Unit"],"answer":0,"explanation":"The Central Processing Unit carries out program instructions; it is often called the brain of the computer.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"कंप्यूटर में CPU का पूर्ण रूप क्या है?","optionsHi":["सेंट्रल प्रोसेसिंग यूनिट (Central Processing Unit)","सेंट्रल प्रोग्राम यूटिलिटी (Central Program Utility)","कंप्यूटर पेरिफेरल यूनिट (Computer Peripheral Unit)","कंट्रोल पावर यूनिट (Control Power Unit)"],"explanationHi":"केंद्रीय प्रसंस्करण इकाई प्रोग्राम के निर्देशों को निष्पादित करती है; इसे प्रायः कंप्यूटर का मस्तिष्क कहा जाता है।"},
  {"id":"gk-science-tech-114","question":"INS Kalvari, commissioned in 2017, is the first of India's:","options":["Indigenous nuclear-powered ballistic missile submarines","Scorpène-class submarines built under Project 75","Stealth guided-missile frigates","Kolkata-class destroyers"],"answer":1,"explanation":"Kalvari is the first of six Scorpène-class diesel-electric submarines built by Mazagon Dock with French help under Project 75. INS Arihant is the first indigenous SSBN.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"2017 में सेवा में शामिल INS कलवरी भारत की किन पनडुब्बियों में पहली है?","optionsHi":["स्वदेशी परमाणु-चालित बैलिस्टिक मिसाइल पनडुब्बियाँ","प्रोजेक्ट 75 के अंतर्गत निर्मित स्कॉर्पीन श्रेणी की पनडुब्बियाँ","स्टेल्थ निर्देशित मिसाइल फ्रिगेट","कोलकाता श्रेणी के विध्वंसक पोत"],"explanationHi":"कलवरी, फ्रांस की सहायता से मझगाँव डॉक द्वारा प्रोजेक्ट 75 के अंतर्गत निर्मित छह स्कॉर्पीन श्रेणी की डीज़ल-इलेक्ट्रिक पनडुब्बियों में पहली है। INS अरिहंत पहली स्वदेशी SSBN है।"},
  {"id":"gk-science-tech-115","question":"Assertion (A): Rockets are preferably launched towards the east from sites close to the equator. Reason (R): The Earth's eastward rotational speed is greatest at the equator and adds to the rocket's velocity.","options":["A is true but R is false","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"Surface speed due to rotation is about 465 m/s at the equator and falls towards the poles; an eastward launch near the equator gains this free boost, which is one reason Sriharikota and Kourou were chosen.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): रॉकेटों को भूमध्य रेखा के निकट के स्थलों से पूर्व की ओर प्रक्षेपित करना अधिक उपयुक्त होता है। कारण (R): पृथ्वी के पूर्व की ओर घूर्णन की चाल भूमध्य रेखा पर सबसे अधिक होती है और रॉकेट के वेग में जुड़ जाती है।","optionsHi":["A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A असत्य है परंतु R सत्य है"],"explanationHi":"घूर्णन के कारण सतह की चाल भूमध्य रेखा पर लगभग 465 m/s होती है और ध्रुवों की ओर घटती जाती है; भूमध्य रेखा के निकट पूर्व की ओर प्रक्षेपण से यह मुफ़्त बढ़ावा मिलता है, जो श्रीहरिकोटा और कौरू के चयन के कारणों में से एक है।"},
  {"id":"gk-science-tech-116","question":"Antrix Corporation, set up in 1992, is:","options":["A private satellite launch company","DRDO's missile production unit","India's space regulator","The commercial arm of ISRO"],"answer":3,"explanation":"Antrix markets ISRO's products and services abroad. IN-SPACe is the authorisation body set up in 2020, and DRDO has no link with Antrix.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"1992 में स्थापित एंट्रिक्स कॉरपोरेशन क्या है?","optionsHi":["निजी उपग्रह प्रक्षेपण कंपनी","DRDO की मिसाइल उत्पादन इकाई","भारत का अंतरिक्ष नियामक","ISRO की वाणिज्यिक शाखा"],"explanationHi":"एंट्रिक्स विदेशों में ISRO के उत्पादों और सेवाओं का विपणन करता है। IN-SPACe 2020 में स्थापित प्राधिकरण निकाय है, और DRDO का एंट्रिक्स से कोई संबंध नहीं है।"},
  {"id":"gk-science-tech-117","question":"Match the internet protocol with its job. A. SMTP  B. FTP  C. DNS  D. DHCP; 1. Assigning IP addresses to devices automatically  2. Translating domain names into IP addresses  3. Transferring files  4. Sending e-mail","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1"],"answer":0,"explanation":"SMTP sends e-mail, FTP transfers files, DNS turns names such as example.com into IP addresses, and DHCP hands out IP addresses on a network.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"इंटरनेट प्रोटोकॉल का उसके कार्य से मिलान कीजिए। A. SMTP  B. FTP  C. DNS  D. DHCP; 1. उपकरणों को स्वतः IP पते देना  2. डोमेन नामों को IP पतों में बदलना  3. फ़ाइलें स्थानांतरित करना  4. ई-मेल भेजना","optionsHi":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1"],"explanationHi":"SMTP ई-मेल भेजता है, FTP फ़ाइलें स्थानांतरित करता है, DNS example.com जैसे नामों को IP पतों में बदलता है, और DHCP नेटवर्क पर IP पते बाँटता है।"},
  {"id":"gk-science-tech-118","question":"How many of these statements about computing history are correct? I. Charles Babbage designed the Analytical Engine. II. Ada Lovelace is regarded as the first computer programmer. III. ENIAC, an early electronic computer, was built in Britain. IV. Moore's law says processor clock speed doubles every year.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. ENIAC was built at the University of Pennsylvania in the US (1945), and Moore's law concerns the number of transistors on a chip doubling roughly every two years, so III and IV are wrong.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"कंप्यूटिंग के इतिहास के बारे में इनमें से कितने कथन सही हैं? I. चार्ल्स बैबेज ने एनालिटिकल इंजन का डिज़ाइन तैयार किया। II. एडा लवलेस को प्रथम कंप्यूटर प्रोग्रामर माना जाता है। III. ENIAC, एक आरंभिक इलेक्ट्रॉनिक कंप्यूटर, ब्रिटेन में बनाया गया था। IV. मूर का नियम कहता है कि प्रोसेसर की क्लॉक गति हर वर्ष दोगुनी हो जाती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। ENIAC अमेरिका के पेंसिल्वेनिया विश्वविद्यालय में (1945) बना था, और मूर का नियम चिप पर ट्रांज़िस्टरों की संख्या के लगभग हर दो वर्ष में दोगुनी होने से संबंधित है, इसलिए III और IV गलत हैं।"},
  {"id":"gk-science-tech-119","question":"Lakshya, developed by DRDO, is a:","options":["Light combat helicopter","Main battle tank","Pilotless target aircraft","Anti-ship cruise missile"],"answer":2,"explanation":"Lakshya is a reusable pilotless target aircraft used for training gun and missile crews. Arjun is a tank and Prachand a light combat helicopter.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"DRDO द्वारा विकसित लक्ष्य (Lakshya) क्या है?","optionsHi":["हल्का लड़ाकू हेलीकॉप्टर","मुख्य युद्धक टैंक","चालक-रहित लक्ष्य विमान","पोत-रोधी क्रूज़ मिसाइल"],"explanationHi":"लक्ष्य पुनः उपयोग योग्य चालक-रहित लक्ष्य विमान है, जिसका उपयोग तोप और मिसाइल दलों के प्रशिक्षण में होता है। अर्जुन टैंक है और प्रचंड हल्का लड़ाकू हेलीकॉप्टर।"},
  {"id":"gk-science-tech-120","question":"ARPANET, the network regarded as the forerunner of the internet, was developed in the late 1960s by the:","options":["International Telecommunication Union","European Organization for Nuclear Research (CERN)","British Post Office","US Department of Defense"],"answer":3,"explanation":"ARPANET was funded by the US Defense Department's Advanced Research Projects Agency and first linked computers in 1969. CERN is where the World Wide Web was later invented.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"इंटरनेट का पूर्वगामी माना जाने वाला नेटवर्क ARPANET 1960 के दशक के अंत में किसने विकसित किया?","optionsHi":["अंतरराष्ट्रीय दूरसंचार संघ","यूरोपीय नाभिकीय अनुसंधान संगठन (CERN)","ब्रिटिश पोस्ट ऑफिस","अमेरिकी रक्षा विभाग"],"explanationHi":"ARPANET का वित्तपोषण अमेरिकी रक्षा विभाग की उन्नत अनुसंधान परियोजना एजेंसी ने किया और इसने 1969 में पहली बार कंप्यूटरों को जोड़ा। CERN वह स्थान है जहाँ बाद में वर्ल्ड वाइड वेब का आविष्कार हुआ।"},
  {"id":"gk-science-tech-121","question":"How many of these statements about orbits and spaceflight are correct? I. The Kármán line, often taken as the edge of space, is about 100 km above sea level. II. The International Space Station orbits at roughly 400 km. III. Escape velocity from Earth's surface is about 11.2 km/s. IV. A satellite in a lower orbit moves faster than one in a higher orbit.","options":["Only three","Only two","Only one","All four"],"answer":3,"explanation":"All four are correct. The Kármán line is at about 100 km, the ISS orbits near 400 km, escape velocity is about 11.2 km/s, and a lower orbit needs a higher speed because gravity pulls harder there.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"कक्षाओं और अंतरिक्ष उड़ान के बारे में इनमें से कितने कथन सही हैं? I. कार्मन रेखा, जिसे प्रायः अंतरिक्ष की सीमा माना जाता है, समुद्र तल से लगभग 100 km ऊपर है। II. अंतरराष्ट्रीय अंतरिक्ष स्टेशन लगभग 400 km पर परिक्रमा करता है। III. पृथ्वी की सतह से पलायन वेग लगभग 11.2 km/s है। IV. निचली कक्षा का उपग्रह ऊँची कक्षा के उपग्रह से अधिक तेज़ गति करता है।","optionsHi":["केवल तीन","केवल दो","केवल एक","सभी चार"],"explanationHi":"चारों कथन सही हैं। कार्मन रेखा लगभग 100 km पर है, ISS लगभग 400 km के निकट परिक्रमा करता है, पलायन वेग लगभग 11.2 km/s है, और निचली कक्षा में अधिक चाल चाहिए क्योंकि वहाँ गुरुत्वाकर्षण अधिक बल से खींचता है।"},
  {"id":"gk-science-tech-122","question":"INS Chakra, the nuclear-powered attack submarine operated by the Indian Navy, was obtained on lease from:","options":["France","Russia","The United States","The United Kingdom"],"answer":1,"explanation":"India leased a Soviet Charlie-class submarine as INS Chakra in 1988 and a Russian Akula-class boat under the same name in 2012. India's own Arihant-class boats are ballistic-missile submarines.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"भारतीय नौसेना द्वारा संचालित परमाणु-चालित आक्रमण पनडुब्बी INS चक्र किससे पट्टे (लीज़) पर ली गई थी?","optionsHi":["फ्रांस","रूस","संयुक्त राज्य अमेरिका","यूनाइटेड किंगडम"],"explanationHi":"भारत ने 1988 में सोवियत चार्ली श्रेणी की पनडुब्बी INS चक्र के नाम से और 2012 में रूसी अकूला श्रेणी की पनडुब्बी उसी नाम से पट्टे पर ली। भारत की अपनी अरिहंत श्रेणी की पनडुब्बियाँ बैलिस्टिक-मिसाइल पनडुब्बियाँ हैं।"},
  {"id":"gk-science-tech-123","question":"Assertion (A): India's pressurised heavy water reactors can run on natural uranium. Reason (R): Heavy water slows neutrons down while absorbing very few of them.","options":["A is true but R is false","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"Because heavy water absorbs so few neutrons, enough remain to sustain a chain reaction in natural uranium (about 0.7% U-235). Light-water reactors absorb more and need enriched fuel.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): भारत के दाबित भारी जल रिएक्टर प्राकृतिक यूरेनियम पर चल सकते हैं। कारण (R): भारी जल न्यूट्रॉनों की गति धीमी करता है और उनमें से बहुत कम को अवशोषित करता है।","optionsHi":["A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A असत्य है परंतु R सत्य है"],"explanationHi":"भारी जल बहुत कम न्यूट्रॉन अवशोषित करता है, इसलिए प्राकृतिक यूरेनियम (लगभग 0.7% U-235) में शृंखला अभिक्रिया बनाए रखने के लिए पर्याप्त न्यूट्रॉन बचे रहते हैं। हल्के जल रिएक्टर अधिक अवशोषण करते हैं और समृद्ध ईंधन माँगते हैं।"},
  {"id":"gk-science-tech-124","question":"Bhaskara-I (1979), India's experimental Earth-observation satellite, was launched from:","options":["The United States","Sriharikota","French Guiana","The Soviet Union"],"answer":3,"explanation":"Like Aryabhata, Bhaskara-I went up on a Soviet Intercosmos rocket, from Kapustin Yar. The first launch from Sriharikota to reach orbit was Rohini in 1980.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"भारत के प्रायोगिक पृथ्वी-अवलोकन उपग्रह भास्कर-I (1979) का प्रक्षेपण कहाँ से किया गया?","optionsHi":["संयुक्त राज्य अमेरिका","श्रीहरिकोटा","फ्रेंच गयाना","सोवियत संघ"],"explanationHi":"आर्यभट्ट की तरह भास्कर-I भी कपुस्तिन यार से सोवियत इंटरकॉसमॉस रॉकेट द्वारा भेजा गया। श्रीहरिकोटा से कक्षा तक पहुँचने वाला पहला प्रक्षेपण 1980 में रोहिणी का था।"},
  {"id":"gk-science-tech-125","question":"Match the space telescope with the band of light it was mainly built to observe. A. Hubble  B. Chandra  C. Spitzer  D. Fermi; 1. Gamma rays  2. Infrared  3. X-rays  4. Visible and ultraviolet","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Hubble works mainly in visible and ultraviolet light, Chandra observes X-rays, Spitzer was an infrared telescope, and Fermi studies gamma rays. All four are NASA missions.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"अंतरिक्ष दूरबीन का उस प्रकाश-बैंड से मिलान कीजिए जिसके अवलोकन के लिए वह मुख्यतः बनी थी। A. हबल  B. चंद्रा  C. स्पिट्ज़र  D. फ़र्मी; 1. गामा किरणें  2. अवरक्त  3. X-किरणें  4. दृश्य और पराबैंगनी","optionsHi":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"हबल मुख्यतः दृश्य और पराबैंगनी प्रकाश में कार्य करती है, चंद्रा X-किरणों का अवलोकन करती है, स्पिट्ज़र अवरक्त दूरबीन थी, और फ़र्मी गामा किरणों का अध्ययन करती है। चारों NASA के मिशन हैं।"},
  {"id":"gk-science-tech-126","question":"Before ISRO was formed in 1969, India's space research was guided by the Indian National Committee for Space Research (INCOSPAR), set up in 1962 under the:","options":["Department of Space","Department of Atomic Energy","Council of Scientific and Industrial Research","Ministry of Defence"],"answer":1,"explanation":"INCOSPAR was formed under the DAE with Vikram Sarabhai as chairman. The Department of Space and the Space Commission came only in 1972.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"1969 में ISRO के गठन से पहले भारत के अंतरिक्ष अनुसंधान का मार्गदर्शन भारतीय राष्ट्रीय अंतरिक्ष अनुसंधान समिति (INCOSPAR) करती थी, जिसकी स्थापना 1962 में किसके अधीन हुई?","optionsHi":["अंतरिक्ष विभाग","परमाणु ऊर्जा विभाग","वैज्ञानिक एवं औद्योगिक अनुसंधान परिषद","रक्षा मंत्रालय"],"explanationHi":"INCOSPAR का गठन DAE के अधीन विक्रम साराभाई की अध्यक्षता में हुआ। अंतरिक्ष विभाग और अंतरिक्ष आयोग केवल 1972 में आए।"},
  {"id":"gk-science-tech-127","question":"Arrange in chronological order: 1. Department of Space set up  2. INCOSPAR formed  3. ISRO formed  4. First sounding rocket launched from Thumba","options":["2-3-4-1","2-4-3-1","4-2-3-1","2-4-1-3"],"answer":1,"explanation":"INCOSPAR (1962), first Thumba launch (November 1963), ISRO (August 1969) and the Department of Space (1972), which took ISRO under it.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. अंतरिक्ष विभाग की स्थापना  2. INCOSPAR का गठन  3. ISRO का गठन  4. थुंबा से पहले साउंडिंग रॉकेट का प्रक्षेपण","optionsHi":["2-3-4-1","2-4-3-1","4-2-3-1","2-4-1-3"],"explanationHi":"INCOSPAR (1962), थुंबा से पहला प्रक्षेपण (नवंबर 1963), ISRO (अगस्त 1969) और अंतरिक्ष विभाग (1972), जिसने ISRO को अपने अधीन लिया।"},
  {"id":"gk-science-tech-128","question":"The first sounding rocket launched from Thumba, on 21 November 1963, was:","options":["A Rohini RH-75 sounding rocket built entirely in India","A Centaure rocket supplied by France","An M-100 rocket supplied by the Soviet Union","A Nike-Apache rocket supplied by the United States"],"answer":3,"explanation":"The first launch was an American Nike-Apache. French Centaure rockets were later made under licence, and the first fully Indian sounding rocket, the RH-75, flew in 1967.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"21 नवंबर 1963 को थुंबा से प्रक्षेपित पहला साउंडिंग रॉकेट कौन-सा था?","optionsHi":["पूर्णतः भारत में निर्मित रोहिणी RH-75 साउंडिंग रॉकेट","फ्रांस द्वारा आपूर्ति किया गया सेंटॉर रॉकेट","सोवियत संघ द्वारा आपूर्ति किया गया M-100 रॉकेट","अमेरिका द्वारा आपूर्ति किया गया नाइकी-अपाचे रॉकेट"],"explanationHi":"पहला प्रक्षेपण अमेरिकी नाइकी-अपाचे का था। फ्रांसीसी सेंटॉर रॉकेट बाद में लाइसेंस के अंतर्गत बनाए गए, और पहला पूर्णतः भारतीय साउंडिंग रॉकेट RH-75 1967 में उड़ा।"},
  {"id":"gk-science-tech-129","question":"Thumba, near Thiruvananthapuram, was chosen for India's first rocket launching station mainly because it lies:","options":["On the east coast, so rockets could fall safely into the Bay of Bengal","Very close to the magnetic equator, ideal for studying the equatorial electrojet","At India's southern tip, giving the largest possible boost from the Earth's rotation","Far from any settlement, so no villagers had to be moved from the site"],"answer":1,"explanation":"Thumba sits almost on the Earth's magnetic equator, valuable for upper-atmosphere and ionosphere research. It is on the west coast, and a fishing village and church had to be relocated.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"तिरुवनंतपुरम के निकट थुंबा को भारत के पहले रॉकेट प्रक्षेपण केंद्र के लिए मुख्यतः इसलिए चुना गया क्योंकि यह स्थित है:","optionsHi":["पूर्वी तट पर, ताकि रॉकेट सुरक्षित रूप से बंगाल की खाड़ी में गिर सकें","चुंबकीय भूमध्य रेखा के बहुत निकट, जो भूमध्यरेखीय इलेक्ट्रोजेट के अध्ययन के लिए आदर्श है","भारत के दक्षिणी छोर पर, जिससे पृथ्वी के घूर्णन का अधिकतम बढ़ावा मिलता है","किसी भी बस्ती से दूर, ताकि स्थल से किसी ग्रामीण को हटाना न पड़े"],"explanationHi":"थुंबा लगभग पृथ्वी की चुंबकीय भूमध्य रेखा पर स्थित है, जो ऊपरी वायुमंडल और आयनमंडल के अनुसंधान के लिए मूल्यवान है। यह पश्चिमी तट पर है, और एक मछुआरा गाँव तथा चर्च को वहाँ से हटाना पड़ा था।"},
  {"id":"gk-science-tech-130","question":"SLV-3, which placed Rohini in orbit in July 1980, was a:","options":["Three-stage vehicle with liquid-fuelled second and third stages","Four-stage vehicle with all four stages using solid propellant","Two-stage vehicle with a small cryogenic upper stage","Four-stage vehicle alternating solid and liquid stages"],"answer":1,"explanation":"SLV-3 was an all-solid, four-stage rocket able to put about 40 kg into low orbit. Alternating solid and liquid stages is the PSLV's design.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जुलाई 1980 में रोहिणी को कक्षा में स्थापित करने वाला SLV-3 क्या था?","optionsHi":["तीन चरणों वाला यान, जिसके दूसरे और तीसरे चरण द्रव-ईंधन वाले थे","चार चरणों वाला यान, जिसके सभी चार चरण ठोस प्रणोदक का उपयोग करते थे","दो चरणों वाला यान, जिसमें एक छोटा क्रायोजेनिक ऊपरी चरण था","चार चरणों वाला यान, जिसमें ठोस और द्रव चरण बारी-बारी से थे"],"explanationHi":"SLV-3 पूरी तरह ठोस ईंधन वाला चार चरणों का रॉकेट था, जो लगभग 40 kg को निम्न कक्षा में पहुँचा सकता था। ठोस और द्रव चरणों का बारी-बारी से आना PSLV का डिज़ाइन है।"},
  {"id":"gk-science-tech-131","question":"The Augmented Satellite Launch Vehicle (ASLV), flown four times between 1987 and 1994, was mainly meant to prove:","options":["Strap-on booster technology and closed-loop guidance","Cryogenic propulsion needed for geostationary launches","Winged reusable launch vehicle technology for landing","The liquid Vikas engine in a large liquid core stage"],"answer":0,"explanation":"ASLV added two strap-on boosters to an SLV-3-type core to test strap-on and closed-loop guidance technology; its last two flights put SROSS satellites in orbit.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संवर्धित उपग्रह प्रक्षेपण यान (ASLV), जिसने 1987 से 1994 के बीच चार उड़ानें भरीं, का मुख्य उद्देश्य किसे सिद्ध करना था?","optionsHi":["स्ट्रैप-ऑन बूस्टर प्रौद्योगिकी और बंद-लूप मार्गदर्शन","भूस्थिर प्रक्षेपणों के लिए आवश्यक क्रायोजेनिक प्रणोदन","लैंडिंग के लिए पंखयुक्त पुनः उपयोग योग्य प्रक्षेपण यान प्रौद्योगिकी","बड़े द्रव कोर चरण में द्रव विकास इंजन"],"explanationHi":"ASLV में SLV-3 जैसे कोर के साथ दो स्ट्रैप-ऑन बूस्टर जोड़े गए ताकि स्ट्रैप-ऑन और बंद-लूप मार्गदर्शन प्रौद्योगिकी का परीक्षण हो सके; इसकी अंतिम दो उड़ानों ने SROSS उपग्रहों को कक्षा में पहुँचाया।"},
  {"id":"gk-science-tech-132","question":"Match the PSLV variant with its configuration. A. PSLV-CA  B. PSLV-DL  C. PSLV-QL  D. PSLV-XL; 1. Six extended strap-on boosters  2. No strap-on boosters  3. Four strap-on boosters  4. Two strap-on boosters","options":["A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1","A-1, B-4, C-3, D-2","A-4, B-2, C-3, D-1"],"answer":0,"explanation":"CA is 'core alone' with no strap-ons, DL has two, QL four and XL six extended strap-ons for the heaviest payloads.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"PSLV के संस्करण का उसकी संरचना से मिलान कीजिए। A. PSLV-CA  B. PSLV-DL  C. PSLV-QL  D. PSLV-XL; 1. छह विस्तारित स्ट्रैप-ऑन बूस्टर  2. कोई स्ट्रैप-ऑन बूस्टर नहीं  3. चार स्ट्रैप-ऑन बूस्टर  4. दो स्ट्रैप-ऑन बूस्टर","optionsHi":["A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1","A-1, B-4, C-3, D-2","A-4, B-2, C-3, D-1"],"explanationHi":"CA \"कोर अलोन\" है जिसमें कोई स्ट्रैप-ऑन नहीं होता, DL में दो, QL में चार और XL में सबसे भारी पेलोड के लिए छह विस्तारित स्ट्रैप-ऑन होते हैं।"},
  {"id":"gk-science-tech-133","question":"Which PSLV variant launched both Chandrayaan-1 (2008) and the Mars Orbiter Mission (2013)?","options":["PSLV-CA","PSLV-DL","PSLV-XL","PSLV-QL"],"answer":2,"explanation":"Both missions needed the extra thrust of the XL version with six extended strap-on boosters (PSLV-C11 and PSLV-C25).","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"चंद्रयान-1 (2008) और मंगल कक्षित्र मिशन (2013), दोनों का प्रक्षेपण PSLV के किस संस्करण ने किया?","optionsHi":["PSLV-CA","PSLV-DL","PSLV-XL","PSLV-QL"],"explanationHi":"दोनों मिशनों को छह विस्तारित स्ट्रैप-ऑन बूस्टर वाले XL संस्करण के अतिरिक्त प्रणोद की आवश्यकता थी (PSLV-C11 और PSLV-C25)।"},
  {"id":"gk-science-tech-134","question":"The Vikas liquid engine, used in the PSLV, GSLV and LVM3, was developed from which foreign engine under a technology arrangement with France?","options":["Vulcain","Viking","RD-180","HM7"],"answer":1,"explanation":"Vikas is derived from the Viking engine of the Ariane rockets. Vulcain and HM7 are Ariane's cryogenic engines and the RD-180 is Russian.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"PSLV, GSLV और LVM3 में प्रयुक्त विकास द्रव इंजन फ्रांस के साथ प्रौद्योगिकी समझौते के अंतर्गत किस विदेशी इंजन से विकसित किया गया था?","optionsHi":["वुल्केन","वाइकिंग","RD-180","HM7"],"explanationHi":"विकास एरियन रॉकेटों के वाइकिंग इंजन से व्युत्पन्न है। वुल्केन और HM7 एरियन के क्रायोजेनिक इंजन हैं और RD-180 रूसी है।"},
  {"id":"gk-science-tech-135","question":"India first flew its own cryogenic upper stage successfully in January 2014 on:","options":["GSLV-D3, which carried GSAT-4","LVM3-X, which carried the CARE module","GSLV-F01, which carried EDUSAT","GSLV-D5, which carried GSAT-14"],"answer":3,"explanation":"GSLV-D5 succeeded with the indigenous cryogenic upper stage. The first attempt, GSLV-D3 in 2010, failed; early GSLVs such as the one for EDUSAT used Russian cryogenic stages, and LVM3-X flew a passive cryogenic stage.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत ने अपना स्वयं का क्रायोजेनिक ऊपरी चरण पहली बार जनवरी 2014 में किस उड़ान पर सफलतापूर्वक उड़ाया?","optionsHi":["GSLV-D3, जिसने GSAT-4 को ले जाया","LVM3-X, जिसने CARE मॉड्यूल को ले जाया","GSLV-F01, जिसने EDUSAT को ले जाया","GSLV-D5, जिसने GSAT-14 को ले जाया"],"explanationHi":"GSLV-D5 स्वदेशी क्रायोजेनिक ऊपरी चरण के साथ सफल रहा। पहला प्रयास, 2010 में GSLV-D3, विफल रहा; EDUSAT वाले जैसे आरंभिक GSLV में रूसी क्रायोजेनिक चरण थे, और LVM3-X में निष्क्रिय क्रायोजेनिक चरण उड़ा।"},
  {"id":"gk-science-tech-136","question":"In the early 1990s, the transfer of cryogenic engine technology to ISRO from Russia's Glavkosmos was blocked mainly because of:","options":["US objections and sanctions citing the Missile Technology Control Regime","A UN Security Council embargo imposed after India's nuclear tests","Cuts in the Russian space budget after the Soviet Union broke up","A licensing dispute with France over the Ariane cryogenic engine"],"answer":0,"explanation":"The US sanctioned ISRO and Glavkosmos in 1992 under MTCR rules, so Russia supplied ready-made stages but not the technology, and ISRO developed its own cryogenic stage. The Pokhran-II sanctions came only in 1998.","difficulty":"hard","source":"UPSC Prelims","questionHi":"1990 के दशक के आरंभ में रूस की ग्लावकॉसमॉस से ISRO को क्रायोजेनिक इंजन प्रौद्योगिकी का हस्तांतरण मुख्यतः किस कारण रोका गया?","optionsHi":["मिसाइल प्रौद्योगिकी नियंत्रण व्यवस्था (MTCR) का हवाला देते हुए अमेरिकी आपत्तियाँ और प्रतिबंध","भारत के परमाणु परीक्षणों के बाद संयुक्त राष्ट्र सुरक्षा परिषद द्वारा लगाया गया प्रतिबंध","सोवियत संघ के विघटन के बाद रूसी अंतरिक्ष बजट में कटौती","एरियन क्रायोजेनिक इंजन को लेकर फ्रांस के साथ लाइसेंस विवाद"],"explanationHi":"अमेरिका ने 1992 में MTCR नियमों के तहत ISRO और ग्लावकॉसमॉस पर प्रतिबंध लगाए, इसलिए रूस ने बने-बनाए चरण दिए पर प्रौद्योगिकी नहीं, और ISRO ने अपना क्रायोजेनिक चरण स्वयं विकसित किया। पोखरण-II के प्रतिबंध केवल 1998 में आए।"},
  {"id":"gk-science-tech-137","question":"The cryogenic engines CE-7.5 and CE-20 power the upper stages of, respectively:","options":["LVM3 and GSLV Mk II","PSLV and GSLV Mk II","GSLV Mk II and LVM3","SSLV and LVM3"],"answer":2,"explanation":"The CE-7.5 (about 7.5 tonnes of thrust) drives the GSLV Mk II's upper stage; the more powerful CE-20 drives LVM3's C25 stage. PSLV and SSLV have no cryogenic stage.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"क्रायोजेनिक इंजन CE-7.5 और CE-20 क्रमशः किनके ऊपरी चरणों को शक्ति देते हैं?","optionsHi":["LVM3 और GSLV Mk II","PSLV और GSLV Mk II","GSLV Mk II और LVM3","SSLV और LVM3"],"explanationHi":"CE-7.5 (लगभग 7.5 टन प्रणोद) GSLV Mk II के ऊपरी चरण को चलाता है; अधिक शक्तिशाली CE-20 LVM3 के C25 चरण को चलाता है। PSLV और SSLV में कोई क्रायोजेनिक चरण नहीं होता।"},
  {"id":"gk-science-tech-138","question":"LVM3 uses two S200 solid boosters, a liquid core stage and a cryogenic upper stage. Its liquid core stage is called:","options":["L40","PS2","S139","L110"],"answer":3,"explanation":"The L110 stage carries about 110 tonnes of propellant and is powered by two Vikas engines. L40 strap-ons belong to the GSLV Mk II and S139/PS2 to the PSLV.","difficulty":"hard","source":"UPSC Prelims","questionHi":"LVM3 में दो S200 ठोस बूस्टर, एक द्रव कोर चरण और एक क्रायोजेनिक ऊपरी चरण होता है। इसके द्रव कोर चरण का नाम क्या है?","optionsHi":["L40","PS2","S139","L110"],"explanationHi":"L110 चरण में लगभग 110 टन प्रणोदक होता है और यह दो विकास इंजनों से चलता है। L40 स्ट्रैप-ऑन GSLV Mk II के हैं और S139/PS2 PSLV के।"},
  {"id":"gk-science-tech-139","question":"The first, suborbital experimental flight of LVM3 in December 2014 (LVM3-X) carried:","options":["The GSAT-19 communication satellite","CARE, a crew module re-entry experiment","The Chandrayaan-2 orbiter on a test run","A batch of 36 OneWeb broadband satellites"],"answer":1,"explanation":"LVM3-X tested the vehicle's atmospheric flight and carried the Crew module Atmospheric Re-entry Experiment, recovered from the Bay of Bengal. GSAT-19 (2017) was its first orbital mission.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"दिसंबर 2014 में LVM3 की पहली उप-कक्षीय प्रायोगिक उड़ान (LVM3-X) में क्या ले जाया गया?","optionsHi":["GSAT-19 संचार उपग्रह","CARE, एक क्रू मॉड्यूल पुनःप्रवेश प्रयोग","परीक्षण उड़ान पर चंद्रयान-2 का कक्षित्र","36 वनवेब ब्रॉडबैंड उपग्रहों का एक समूह"],"explanationHi":"LVM3-X ने यान की वायुमंडलीय उड़ान का परीक्षण किया और क्रू मॉड्यूल एटमॉस्फेरिक री-एंट्री एक्सपेरिमेंट को ले गया, जिसे बंगाल की खाड़ी से बरामद किया गया। GSAT-19 (2017) इसका पहला कक्षीय मिशन था।"},
  {"id":"gk-science-tech-140","question":"In 2022–23, LVM3 flew its first commercial missions, launching satellites for:","options":["SpaceX Starlink","Amazon Kuiper","OneWeb","Iridium"],"answer":2,"explanation":"Two LVM3 flights in October 2022 and March 2023, arranged through NewSpace India Limited, placed 72 OneWeb satellites in low Earth orbit.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"2022–23 में LVM3 ने अपने पहले वाणिज्यिक मिशन उड़ाए, जिनमें किसके उपग्रह प्रक्षेपित किए गए?","optionsHi":["स्पेसएक्स स्टारलिंक","अमेज़न क्यूपर","वनवेब","इरिडियम"],"explanationHi":"अक्टूबर 2022 और मार्च 2023 की दो LVM3 उड़ानों ने, न्यूस्पेस इंडिया लिमिटेड के माध्यम से व्यवस्थित होकर, 72 वनवेब उपग्रहों को निम्न पृथ्वी कक्षा में स्थापित किया।"},
  {"id":"gk-science-tech-141","question":"The Small Satellite Launch Vehicle (SSLV) has three solid stages topped by a liquid-fuelled:","options":["Cryogenic upper kick stage","PS4 fourth stage","Velocity Trimming Module","Crew escape tower"],"answer":2,"explanation":"The Velocity Trimming Module fine-tunes the satellite's velocity before injection. The PS4 is the PSLV's fourth stage.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"लघु उपग्रह प्रक्षेपण यान (SSLV) में तीन ठोस चरण होते हैं, जिनके ऊपर एक द्रव-ईंधन वाला क्या लगा होता है?","optionsHi":["क्रायोजेनिक ऊपरी किक चरण","PS4 चौथा चरण","वेग समायोजन मॉड्यूल (Velocity Trimming Module)","चालक दल निकास टावर"],"explanationHi":"वेग समायोजन मॉड्यूल उपग्रह के कक्षा में छोड़े जाने से पहले उसके वेग को सूक्ष्म रूप से समायोजित करता है। PS4 PSLV का चौथा चरण है।"},
  {"id":"gk-science-tech-142","question":"The Satish Dhawan Space Centre at Sriharikota lies on a barrier island between the Bay of Bengal and:","options":["Chilika Lake","Kolleru Lake","Vembanad Lake","Pulicat Lake"],"answer":3,"explanation":"Sriharikota separates Pulicat Lake, a brackish lagoon on the Andhra Pradesh–Tamil Nadu border, from the sea. Chilika is in Odisha and Vembanad in Kerala.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"श्रीहरिकोटा स्थित सतीश धवन अंतरिक्ष केंद्र बंगाल की खाड़ी और किसके बीच एक अवरोधक द्वीप पर स्थित है?","optionsHi":["चिल्का झील","कोल्लेरू झील","वेम्बनाड झील","पुलिकट झील"],"explanationHi":"श्रीहरिकोटा आंध्र प्रदेश–तमिलनाडु सीमा पर स्थित खारे पानी की लैगून पुलिकट झील को समुद्र से अलग करता है। चिल्का ओडिशा में और वेम्बनाड केरल में है।"},
  {"id":"gk-science-tech-143","question":"ISRO's Space Capsule Recovery Experiment (SRE-1), launched on a PSLV in January 2007, was significant because the capsule:","options":["Was brought back from orbit and recovered from the Bay of Bengal","Docked with an Indian satellite already in low Earth orbit","Carried the first living organisms sent into space by India","Landed on the Moon by parachute as a test for Chandrayaan-1"],"answer":0,"explanation":"SRE-1 orbited for about 12 days and was de-orbited to a splashdown in the Bay of Bengal, proving re-entry and recovery technology needed for crewed flight.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जनवरी 2007 में PSLV से प्रक्षेपित ISRO का अंतरिक्ष कैप्सूल पुनर्प्राप्ति प्रयोग (SRE-1) इसलिए महत्त्वपूर्ण था क्योंकि कैप्सूल:","optionsHi":["कक्षा से वापस लाया गया और बंगाल की खाड़ी से बरामद किया गया","निम्न पृथ्वी कक्षा में पहले से मौजूद भारतीय उपग्रह से जुड़ा (डॉक हुआ)","भारत द्वारा अंतरिक्ष में भेजे गए पहले जीवित जीवों को ले गया","चंद्रयान-1 के परीक्षण के रूप में पैराशूट द्वारा चंद्रमा पर उतरा"],"explanationHi":"SRE-1 लगभग 12 दिन कक्षा में रहा और फिर उसे कक्षा से हटाकर बंगाल की खाड़ी में उतारा गया, जिससे मानव उड़ान के लिए आवश्यक पुनःप्रवेश और पुनर्प्राप्ति प्रौद्योगिकी सिद्ध हुई।"},
  {"id":"gk-science-tech-144","question":"ISRO's RLV-TD, flown from Sriharikota in May 2016 (the HEX mission), was a:","options":["Scramjet engine test carried on a modified sounding rocket","Pad abort test of the crew escape system for Gaganyaan","Winged technology demonstrator for a reusable launch vehicle","First-stage recovery test with a landing on a sea barge"],"answer":2,"explanation":"The Hypersonic Flight Experiment flew a scaled winged vehicle to test re-entry and control for a future reusable launcher; the scramjet test followed in August 2016.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मई 2016 में श्रीहरिकोटा से उड़ाया गया ISRO का RLV-TD (HEX मिशन) क्या था?","optionsHi":["संशोधित साउंडिंग रॉकेट पर ले जाया गया स्क्रैमजेट इंजन परीक्षण","गगनयान के चालक दल निकास प्रणाली का पैड एबॉर्ट परीक्षण","पुनः उपयोग योग्य प्रक्षेपण यान का पंखयुक्त प्रौद्योगिकी प्रदर्शक","समुद्री बजरे पर उतरने वाला प्रथम चरण पुनर्प्राप्ति परीक्षण"],"explanationHi":"अतिध्वनिक उड़ान प्रयोग (HEX) में भावी पुनः उपयोग योग्य प्रक्षेपक के लिए पुनःप्रवेश और नियंत्रण का परीक्षण करने हेतु एक छोटे पैमाने का पंखयुक्त यान उड़ाया गया; स्क्रैमजेट परीक्षण अगस्त 2016 में हुआ।"},
  {"id":"gk-science-tech-145","question":"The 'Vikas' rocket engine takes its name from:","options":["Vikram Ambalal Sarabhai","Satish Dhawan","Homi Jehangir Bhabha","Udupi Ramachandra Rao"],"answer":0,"explanation":"VIKAS is an acronym of VIKram Ambalal Sarabhai, honouring the founder of India's space programme.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"\"विकास\" रॉकेट इंजन को यह नाम किसके नाम से मिला है?","optionsHi":["विक्रम अंबालाल साराभाई","सतीश धवन","होमी जहाँगीर भाभा","उडुपी रामचंद्र राव"],"explanationHi":"VIKAS, VIKram Ambalal Sarabhai का संक्षिप्त रूप है, जो भारत के अंतरिक्ष कार्यक्रम के संस्थापक को सम्मान देता है।"},
  {"id":"gk-science-tech-146","question":"IRS-1A, India's first operational remote-sensing satellite (1988), was launched by:","options":["An ASLV launched from Sriharikota","A Soviet Vostok rocket from Baikonur","A PSLV launched from Sriharikota","An Ariane rocket launched from Kourou"],"answer":1,"explanation":"IRS-1A went up on a Soviet Vostok from Baikonur in March 1988; the first IRS satellite on an Indian rocket was IRS-P2 on a PSLV in 1994.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत के पहले परिचालन सुदूर संवेदन उपग्रह IRS-1A (1988) का प्रक्षेपण किसने किया?","optionsHi":["श्रीहरिकोटा से प्रक्षेपित ASLV","बैकोनूर से सोवियत वोस्तोक रॉकेट","श्रीहरिकोटा से प्रक्षेपित PSLV","कौरू से प्रक्षेपित एरियन रॉकेट"],"explanationHi":"IRS-1A मार्च 1988 में बैकोनूर से सोवियत वोस्तोक पर गया; भारतीय रॉकेट पर पहला IRS उपग्रह 1994 में PSLV से IRS-P2 था।"},
  {"id":"gk-science-tech-147","question":"INSAT-1B, launched in 1983, was carried into space by:","options":["A US Delta rocket from Cape Canaveral","An Ariane rocket from French Guiana","A Soviet Proton rocket from Baikonur","The US Space Shuttle Challenger"],"answer":3,"explanation":"INSAT-1B was deployed from Challenger in August 1983. INSAT-1A had gone up on a Delta rocket in 1982.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"1983 में प्रक्षेपित INSAT-1B को अंतरिक्ष में किसने पहुँचाया?","optionsHi":["केप कैनावेरल से अमेरिकी डेल्टा रॉकेट","फ्रेंच गयाना से एरियन रॉकेट","बैकोनूर से सोवियत प्रोटॉन रॉकेट","अमेरिकी स्पेस शटल चैलेंजर"],"explanationHi":"INSAT-1B को अगस्त 1983 में चैलेंजर से तैनात किया गया। INSAT-1A 1982 में डेल्टा रॉकेट से गया था।"},
  {"id":"gk-science-tech-148","question":"EDUSAT (GSAT-3), launched in 2004, was India's first satellite built exclusively for:","options":["Weather forecasting","Military communication","Education","Navigation"],"answer":2,"explanation":"EDUSAT was dedicated to distance education and tele-education, building on the earlier SITE experiment.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"2004 में प्रक्षेपित EDUSAT (GSAT-3) भारत का पहला उपग्रह था जो विशेष रूप से किसके लिए बनाया गया?","optionsHi":["मौसम पूर्वानुमान","सैन्य संचार","शिक्षा","नौवहन"],"explanationHi":"EDUSAT दूरस्थ शिक्षा और टेली-शिक्षा के लिए समर्पित था, जो पहले के SITE प्रयोग पर आधारित था।"},
  {"id":"gk-science-tech-149","question":"MetSat-1, India's first dedicated meteorological satellite (2002), later renamed Kalpana-1, was launched by:","options":["A PSLV, in that rocket's first launch into a geosynchronous transfer orbit","A GSLV, in its first flight with an upper cryogenic stage that was built in India","An Ariane 5, from the Guiana Space Centre in South America","A Soviet-era Vostok rocket, from the Baikonur launch site"],"answer":0,"explanation":"PSLV-C4 placed MetSat-1 in a geosynchronous transfer orbit, the first such PSLV launch; the satellite was renamed after Kalpana Chawla died on Columbia in 2003.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत का पहला समर्पित मौसम-विज्ञान उपग्रह MetSat-1 (2002), जिसका बाद में नाम कल्पना-1 रखा गया, किसके द्वारा प्रक्षेपित किया गया?","optionsHi":["PSLV द्वारा, जो उस रॉकेट का भूतुल्यकालिक स्थानांतरण कक्षा में पहला प्रक्षेपण था","GSLV द्वारा, भारत में निर्मित क्रायोजेनिक ऊपरी चरण के साथ उसकी पहली उड़ान में","एरियन 5 द्वारा, दक्षिण अमेरिका के गुयाना अंतरिक्ष केंद्र से","सोवियत-युग के वोस्तोक रॉकेट द्वारा, बैकोनूर प्रक्षेपण स्थल से"],"explanationHi":"PSLV-C4 ने MetSat-1 को भूतुल्यकालिक स्थानांतरण कक्षा में स्थापित किया, जो PSLV का ऐसा पहला प्रक्षेपण था; 2003 में कोलंबिया हादसे में कल्पना चावला की मृत्यु के बाद उपग्रह का नाम उनके नाम पर रखा गया।"},
  {"id":"gk-science-tech-150","question":"GSAT-7, launched in 2013 and nicknamed 'Rukmini', is India's first dedicated military communication satellite. It serves the:","options":["Indian Air Force","Indian Army","Indian Navy","Indian Coast Guard"],"answer":2,"explanation":"GSAT-7 links the Navy's ships, submarines and aircraft over the Indian Ocean; GSAT-7A (2018) serves mainly the Air Force.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"2013 में प्रक्षेपित और \"रुक्मिणी\" उपनाम वाला GSAT-7 भारत का पहला समर्पित सैन्य संचार उपग्रह है। यह किसकी सेवा करता है?","optionsHi":["भारतीय वायुसेना","भारतीय थलसेना","भारतीय नौसेना","भारतीय तटरक्षक बल"],"explanationHi":"GSAT-7 हिंद महासागर क्षेत्र में नौसेना के पोतों, पनडुब्बियों और विमानों को जोड़ता है; GSAT-7A (2018) मुख्यतः वायुसेना की सेवा करता है।"},
  {"id":"gk-science-tech-151","question":"Which of these statements about Chandrayaan-1 are correct? I. It was launched in October 2008 by PSLV-C11. II. Its Moon Impact Probe was deliberately crashed near the lunar south pole. III. NASA's Moon Mineralogy Mapper on board helped detect water and hydroxyl on the lunar surface. IV. It completed its full planned two-year mission life.","options":["I and III only","I, II and III only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"I, II and III are correct. Contact was lost in August 2009, after about ten months, well short of the planned two years, though most objectives had been met.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"चंद्रयान-1 के बारे में इनमें से कौन-से कथन सही हैं? I. इसे अक्टूबर 2008 में PSLV-C11 द्वारा प्रक्षेपित किया गया था। II. इसके मून इम्पैक्ट प्रोब को जानबूझकर चंद्र दक्षिणी ध्रुव के निकट टकराया गया। III. इस पर लगे NASA के मून मिनरलॉजी मैपर ने चंद्र सतह पर जल और हाइड्रॉक्सिल का पता लगाने में सहायता की। IV. इसने अपना पूरा नियोजित दो वर्ष का मिशन-जीवन पूरा किया।","optionsHi":["केवल I और III","केवल I, II और III","केवल II, III और IV","I, II, III और IV"],"explanationHi":"I, II और III सही हैं। अगस्त 2009 में, लगभग दस महीने बाद, संपर्क टूट गया, जो नियोजित दो वर्ष से काफ़ी पहले था, हालाँकि अधिकांश उद्देश्य पूरे हो चुके थे।"},
  {"id":"gk-science-tech-152","question":"Match the name given by India with the lunar spot it marks. A. Jawahar Point  B. Tiranga Point  C. Shiv Shakti Point; 1. Landing site of Chandrayaan-3's Vikram lander  2. Impact site of Chandrayaan-1's Moon Impact Probe  3. Spot where Chandrayaan-2's Vikram lander crashed","options":["A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2","A-2, B-3, C-1"],"answer":3,"explanation":"Jawahar Point marks the MIP impact of 14 November 2008 (Nehru's birthday); Tiranga Point marks Chandrayaan-2's crash in 2019; Shiv Shakti Point is Chandrayaan-3's landing site of 23 August 2023.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भारत द्वारा दिए गए नाम का उस चंद्र स्थल से मिलान कीजिए जिसे वह चिह्नित करता है। A. जवाहर पॉइंट  B. तिरंगा पॉइंट  C. शिव शक्ति पॉइंट; 1. चंद्रयान-3 के विक्रम लैंडर का अवतरण स्थल  2. चंद्रयान-1 के मून इम्पैक्ट प्रोब का टकराव स्थल  3. वह स्थान जहाँ चंद्रयान-2 का विक्रम लैंडर दुर्घटनाग्रस्त हुआ","optionsHi":["A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2","A-2, B-3, C-1"],"explanationHi":"जवाहर पॉइंट 14 नवंबर 2008 (नेहरू के जन्मदिन) को MIP के टकराव स्थल को चिह्नित करता है; तिरंगा पॉइंट 2019 में चंद्रयान-2 के दुर्घटनाग्रस्त होने का स्थान है; शिव शक्ति पॉइंट 23 अगस्त 2023 को चंद्रयान-3 का अवतरण स्थल है।"},
  {"id":"gk-science-tech-153","question":"Chandrayaan-2, with its orbiter, Vikram lander and Pragyan rover, was launched in July 2019 by:","options":["GSLV Mk III (now LVM3)","GSLV Mk II with Russian cryogenic stage","PSLV-XL with six strap-ons","PSLV-QL with four strap-ons"],"answer":0,"explanation":"GSLV Mk III-M1 launched Chandrayaan-2 on 22 July 2019; the 3.8-tonne spacecraft was too heavy for the PSLV.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"अपने कक्षित्र, विक्रम लैंडर और प्रज्ञान रोवर वाले चंद्रयान-2 का प्रक्षेपण जुलाई 2019 में किसके द्वारा किया गया?","optionsHi":["GSLV Mk III (अब LVM3)","रूसी क्रायोजेनिक चरण वाला GSLV Mk II","छह स्ट्रैप-ऑन वाला PSLV-XL","चार स्ट्रैप-ऑन वाला PSLV-QL"],"explanationHi":"GSLV Mk III-M1 ने 22 जुलाई 2019 को चंद्रयान-2 का प्रक्षेपण किया; 3.8 टन का यह अंतरिक्ष यान PSLV के लिए बहुत भारी था।"},
  {"id":"gk-science-tech-154","question":"The LIBS instrument on Chandrayaan-3's Pragyan rover made the first in-situ confirmation, near the lunar south pole, of the presence of:","options":["Water ice","Helium-3","Sulphur","Hydrogen"],"answer":2,"explanation":"Laser-Induced Breakdown Spectroscopy confirmed sulphur in August 2023, along with elements such as aluminium, calcium, iron, titanium and oxygen; the search for hydrogen was ongoing.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"चंद्रयान-3 के प्रज्ञान रोवर के LIBS उपकरण ने चंद्र दक्षिणी ध्रुव के निकट किसकी उपस्थिति की पहली यथास्थान (in-situ) पुष्टि की?","optionsHi":["जल बर्फ़","हीलियम-3","सल्फ़र (गंधक)","हाइड्रोजन"],"explanationHi":"लेज़र-प्रेरित ब्रेकडाउन स्पेक्ट्रोस्कोपी ने अगस्त 2023 में सल्फ़र की पुष्टि की, साथ ही एल्युमिनियम, कैल्शियम, लोहा, टाइटेनियम और ऑक्सीजन जैसे तत्वों की भी; हाइड्रोजन की खोज जारी थी।"},
  {"id":"gk-science-tech-155","question":"ChaSTE, an instrument on Chandrayaan-3's Vikram lander, measured:","options":["Moonquakes and other ground vibrations near the landing site","The temperature profile of the lunar topsoil to about 10 cm","Density of the plasma just above the lunar surface","The precise Earth–Moon distance using laser reflections"],"answer":1,"explanation":"Chandra's Surface Thermophysical Experiment pushed a probe into the regolith to record temperature with depth. ILSA recorded vibrations, RAMBHA-LP plasma, and NASA's retroreflector serves laser ranging.","difficulty":"hard","source":"UPSC Prelims","questionHi":"चंद्रयान-3 के विक्रम लैंडर पर लगे उपकरण ChaSTE ने क्या मापा?","optionsHi":["अवतरण स्थल के निकट चंद्रकंप और अन्य भूमि कंपन","चंद्रमा की ऊपरी मिट्टी का लगभग 10 cm तक का तापमान-प्रोफ़ाइल","चंद्र सतह के ठीक ऊपर प्लाज़्मा का घनत्व","लेज़र परावर्तनों से पृथ्वी–चंद्रमा की सटीक दूरी"],"explanationHi":"चंद्रा सरफेस थर्मोफिज़िकल एक्सपेरिमेंट ने रेगोलिथ में एक प्रोब डाला ताकि गहराई के साथ तापमान दर्ज हो सके। ILSA ने कंपन, RAMBHA-LP ने प्लाज़्मा दर्ज किया, और NASA का रेट्रोरिफ्लेक्टर लेज़र दूरी मापन के काम आता है।"},
  {"id":"gk-science-tech-156","question":"SHAPE, the experimental payload on Chandrayaan-3's propulsion module, was designed to:","options":["Map water ice in permanently shadowed craters at the poles","Record solar X-ray flares from a vantage point in lunar orbit","Relay radio signals between the Vikram lander and Earth","Observe Earth from lunar orbit as a model for habitable exoplanets"],"answer":3,"explanation":"Spectro-polarimetry of HAbitable Planet Earth studied Earth's reflected light to learn how habitable exoplanets might look. The propulsion module was later moved back into Earth orbit in November 2023.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"चंद्रयान-3 के प्रणोदन मॉड्यूल पर लगे प्रायोगिक पेलोड SHAPE को किस उद्देश्य से बनाया गया था?","optionsHi":["ध्रुवों पर स्थायी रूप से छाया वाले क्रेटरों में जल बर्फ़ का मानचित्रण","चंद्र कक्षा के अवलोकन-बिंदु से सौर X-किरण ज्वालाओं को दर्ज करना","विक्रम लैंडर और पृथ्वी के बीच रेडियो संकेतों को प्रसारित करना","रहने योग्य बाह्यग्रहों के मॉडल के रूप में चंद्र कक्षा से पृथ्वी का अवलोकन"],"explanationHi":"स्पेक्ट्रो-पोलैरिमेट्री ऑफ़ हैबिटेबल प्लैनेट अर्थ ने पृथ्वी के परावर्तित प्रकाश का अध्ययन किया ताकि यह जाना जा सके कि रहने योग्य बाह्यग्रह कैसे दिख सकते हैं। प्रणोदन मॉड्यूल को बाद में नवंबर 2023 में वापस पृथ्वी की कक्षा में लाया गया।"},
  {"id":"gk-science-tech-157","question":"In September 2023, Chandrayaan-3's Vikram lander carried out a 'hop experiment', in which it:","options":["Released Pragyan a second time after the rover had returned to it","Fired its engines, rose about 40 cm and landed 30–40 cm away","Rolled on wheels about 100 m to a new spot nearer the pole","Lifted off fully and returned its propulsion module to Earth orbit"],"answer":1,"explanation":"The hop showed the lander could restart its engines on the Moon, a step towards future sample-return and crewed missions; it later went into sleep mode for the lunar night.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"सितंबर 2023 में चंद्रयान-3 के विक्रम लैंडर ने एक \"हॉप प्रयोग\" किया, जिसमें उसने:","optionsHi":["रोवर के वापस लौटने के बाद प्रज्ञान को दूसरी बार छोड़ा","अपने इंजन चलाए, लगभग 40 cm ऊपर उठा और 30–40 cm दूर उतरा","पहियों पर लगभग 100 m लुढ़ककर ध्रुव के निकट नए स्थान पर पहुँचा","पूरी तरह उड़ान भरी और अपने प्रणोदन मॉड्यूल को पृथ्वी की कक्षा में वापस भेजा"],"explanationHi":"हॉप ने दिखाया कि लैंडर चंद्रमा पर अपने इंजन पुनः चालू कर सकता है, जो भावी नमूना-वापसी और मानव मिशनों की दिशा में एक कदम है; बाद में वह चंद्र रात के लिए स्लीप मोड में चला गया।"},
  {"id":"gk-science-tech-158","question":"When the Mars Orbiter Mission entered orbit around Mars on 24 September 2014, India became:","options":["The first Asian country to land a probe on the surface of Mars","The second country, after the United States, to orbit Mars","The first country to reach Mars orbit in its first attempt","The first country to put a probe in orbit around Phobos"],"answer":2,"explanation":"India was the first nation to succeed on its maiden Mars attempt and the first in Asia to reach Mars orbit; the US, the USSR and Europe had reached Mars before, and MOM did not land.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"24 सितंबर 2014 को जब मंगल कक्षित्र मिशन मंगल की कक्षा में पहुँचा, तब भारत बना:","optionsHi":["मंगल की सतह पर यान उतारने वाला पहला एशियाई देश","अमेरिका के बाद मंगल की परिक्रमा करने वाला दूसरा देश","अपने पहले ही प्रयास में मंगल की कक्षा तक पहुँचने वाला पहला देश","फोबोस की परिक्रमा में यान स्थापित करने वाला पहला देश"],"explanationHi":"भारत मंगल पर अपने पहले प्रयास में सफल होने वाला पहला राष्ट्र और मंगल की कक्षा तक पहुँचने वाला एशिया का पहला देश था; अमेरिका, सोवियत संघ और यूरोप पहले मंगल तक पहुँच चुके थे, और MOM सतह पर नहीं उतरा।"},
  {"id":"gk-science-tech-159","question":"Which of these instruments flew on India's Mars Orbiter Mission?","options":["Moon Mineralogy Mapper","Methane Sensor for Mars","Solar Ultraviolet Imaging Telescope","Alpha Particle X-ray Spectrometer"],"answer":1,"explanation":"MOM carried five payloads, including the Methane Sensor for Mars and the Mars Colour Camera. The M3 flew on Chandrayaan-1, SUIT on Aditya-L1 and APXS on the Pragyan rover.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कौन-सा उपकरण भारत के मंगल कक्षित्र मिशन पर उड़ा?","optionsHi":["मून मिनरलॉजी मैपर","मीथेन सेंसर फ़ॉर मार्स","सोलर अल्ट्रावायलेट इमेजिंग टेलीस्कोप","अल्फ़ा पार्टिकल X-रे स्पेक्ट्रोमीटर"],"explanationHi":"MOM में पाँच पेलोड थे, जिनमें मीथेन सेंसर फ़ॉर मार्स और मार्स कलर कैमरा शामिल थे। M3 चंद्रयान-1 पर, SUIT आदित्य-L1 पर और APXS प्रज्ञान रोवर पर उड़ा।"},
  {"id":"gk-science-tech-160","question":"NavIC satellites broadcast navigation signals in the L5 band and in the:","options":["Ku band","C band","S band","X band"],"answer":2,"explanation":"The first-generation IRNSS satellites transmit in L5 and S bands; the second-generation NVS series adds the L1 band used by most phones.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"NavIC उपग्रह L5 बैंड और किस बैंड में नौवहन संकेत प्रसारित करते हैं?","optionsHi":["Ku बैंड","C बैंड","S बैंड","X बैंड"],"explanationHi":"पहली पीढ़ी के IRNSS उपग्रह L5 और S बैंड में प्रसारण करते हैं; दूसरी पीढ़ी की NVS श्रृंखला में L1 बैंड भी जुड़ता है, जिसका उपयोग अधिकांश फ़ोन करते हैं।"},
  {"id":"gk-science-tech-161","question":"NVS-01, launched by a GSLV in May 2023 as the first of NavIC's second-generation satellites, was notable for carrying:","options":["An optical laser link to the other NavIC satellites","A hydrogen maser clock imported from Russia","An electric propulsion system for orbit raising","An indigenously developed rubidium atomic clock"],"answer":3,"explanation":"NVS-01 flew an atomic clock developed by ISRO's Space Applications Centre, reducing dependence on imported clocks, whose failures had hit earlier IRNSS satellites.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मई 2023 में GSLV से प्रक्षेपित NVS-01, जो NavIC की दूसरी पीढ़ी का पहला उपग्रह था, किस कारण उल्लेखनीय था?","optionsHi":["अन्य NavIC उपग्रहों से ऑप्टिकल लेज़र लिंक रखना","रूस से आयातित हाइड्रोजन मेज़र घड़ी रखना","कक्षा उठाने के लिए इलेक्ट्रिक प्रणोदन प्रणाली रखना","स्वदेशी रूप से विकसित रुबिडियम परमाणु घड़ी रखना"],"explanationHi":"NVS-01 में ISRO के अंतरिक्ष अनुप्रयोग केंद्र द्वारा विकसित परमाणु घड़ी लगी थी, जिससे आयातित घड़ियों पर निर्भरता घटी, जिनकी विफलता ने पहले के IRNSS उपग्रहों को प्रभावित किया था।"},
  {"id":"gk-science-tech-162","question":"IRNSS-1H, meant to replace a NavIC satellite whose atomic clocks had failed, was lost in August 2017 because:","options":["The PSLV's heat shield did not separate after launch","Its solar panels failed to unfold once it was in orbit","The cryogenic upper stage of its GSLV shut down early","It collided with debris while raising its own orbit"],"answer":0,"explanation":"On PSLV-C39 the payload fairing failed to separate, so the satellite stayed enclosed and could not reach its orbit; the PSLV has no cryogenic stage.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"IRNSS-1H, जिसे उस NavIC उपग्रह की जगह लेना था जिसकी परमाणु घड़ियाँ विफल हो गई थीं, अगस्त 2017 में किस कारण खो गया?","optionsHi":["प्रक्षेपण के बाद PSLV का ऊष्मा कवच अलग नहीं हुआ","कक्षा में पहुँचने के बाद इसके सौर पैनल नहीं खुले","इसके GSLV का क्रायोजेनिक ऊपरी चरण समय से पहले बंद हो गया","अपनी कक्षा ऊँची करते समय यह मलबे से टकरा गया"],"explanationHi":"PSLV-C39 में पेलोड फ़ेयरिंग अलग नहीं हुई, इसलिए उपग्रह उसी के भीतर बंद रहा और अपनी कक्षा तक नहीं पहुँच सका; PSLV में कोई क्रायोजेनिक चरण नहीं होता।"},
  {"id":"gk-science-tech-163","question":"GAGAN, developed jointly by ISRO and the Airports Authority of India, is a:","options":["Regional navigation constellation independent of GPS","Satellite-based augmentation system that improves GPS accuracy","Ground radar network for civil air traffic control","Weather satellite that forecasts conditions on flight routes"],"answer":1,"explanation":"GPS Aided GEO Augmented Navigation sends corrections through geostationary satellites so aircraft can use GPS for precise approaches. The independent regional constellation is NavIC.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"ISRO और भारतीय विमानपत्तन प्राधिकरण द्वारा संयुक्त रूप से विकसित GAGAN क्या है?","optionsHi":["GPS से स्वतंत्र क्षेत्रीय नौवहन तारामंडल","उपग्रह-आधारित संवर्धन प्रणाली जो GPS की सटीकता बढ़ाती है","नागरिक हवाई यातायात नियंत्रण के लिए भू-रडार नेटवर्क","मौसम उपग्रह जो उड़ान मार्गों की परिस्थितियों का पूर्वानुमान देता है"],"explanationHi":"GPS एडेड जियो ऑगमेंटेड नेविगेशन भूस्थिर उपग्रहों के माध्यम से सुधार संकेत भेजता है ताकि विमान सटीक अवतरण के लिए GPS का उपयोग कर सकें। स्वतंत्र क्षेत्रीय तारामंडल NavIC है।"},
  {"id":"gk-science-tech-164","question":"In Mission Shakti (27 March 2019), India destroyed one of its own satellites with a missile. Which of these statements are correct? I. The interceptor was a ballistic missile defence interceptor (PDV Mk-II). II. The target, Microsat-R, was in low Earth orbit at about 300 km. III. The low altitude was chosen partly so that debris would decay quickly. IV. India became the third country to carry out such a test.","options":["I and II only","II, III and IV only","I, II and III only","I, II, III and IV"],"answer":2,"explanation":"I, II and III are correct. India was the fourth country, after the United States, Russia and China, to demonstrate a direct-ascent anti-satellite capability.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मिशन शक्ति (27 मार्च 2019) में भारत ने अपने ही एक उपग्रह को मिसाइल से नष्ट किया। इनमें से कौन-से कथन सही हैं? I. अवरोधक एक बैलिस्टिक मिसाइल रक्षा अवरोधक (PDV Mk-II) था। II. लक्ष्य, माइक्रोसैट-R, लगभग 300 km पर निम्न पृथ्वी कक्षा में था। III. कम ऊँचाई आंशिक रूप से इसलिए चुनी गई ताकि मलबा शीघ्र नष्ट हो जाए। IV. ऐसा परीक्षण करने वाला भारत तीसरा देश बना।","optionsHi":["केवल I और II","केवल II, III और IV","केवल I, II और III","I, II, III और IV"],"explanationHi":"I, II और III सही हैं। अमेरिका, रूस और चीन के बाद भारत प्रत्यक्ष-आरोहण उपग्रह-रोधी क्षमता प्रदर्शित करने वाला चौथा देश था।"},
  {"id":"gk-science-tech-165","question":"Rakesh Sharma, the first Indian in space, flew in April 1984 aboard:","options":["Soyuz T-11, visiting the Salyut 7 space station","The US Space Shuttle Challenger on mission STS-41","Soyuz TM-2, visiting the Mir space station","Vostok 6, on a solo orbital flight"],"answer":0,"explanation":"Sharma flew on Soyuz T-11 under the Interkosmos programme and spent about eight days on Salyut 7; Mir was launched only in 1986.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"पहले भारतीय अंतरिक्ष यात्री राकेश शर्मा ने अप्रैल 1984 में किस यान से उड़ान भरी?","optionsHi":["सोयूज़ T-11, सैल्यूट 7 अंतरिक्ष स्टेशन की यात्रा के लिए","अमेरिकी स्पेस शटल चैलेंजर, मिशन STS-41 पर","सोयूज़ TM-2, मीर अंतरिक्ष स्टेशन की यात्रा के लिए","वोस्तोक 6, एकल कक्षीय उड़ान पर"],"explanationHi":"शर्मा ने इंटरकॉसमॉस कार्यक्रम के तहत सोयूज़ T-11 से उड़ान भरी और सैल्यूट 7 पर लगभग आठ दिन बिताए; मीर का प्रक्षेपण केवल 1986 में हुआ।"},
  {"id":"gk-science-tech-166","question":"The South Asia Satellite (GSAT-9), launched by India in 2017 for its neighbours, did NOT include which SAARC country, which chose to stay out?","options":["Afghanistan","Sri Lanka","Bangladesh","Pakistan"],"answer":3,"explanation":"Pakistan opted out, so the satellite serves the other SAARC members; it was launched on a GSLV in May 2017.","difficulty":"moderate","source":"SSC CGL Tier 2 · State PCS","questionHi":"भारत द्वारा 2017 में अपने पड़ोसियों के लिए प्रक्षेपित दक्षिण एशिया उपग्रह (GSAT-9) में किस SAARC देश को शामिल नहीं किया गया, जिसने बाहर रहना चुना?","optionsHi":["अफ़गानिस्तान","श्रीलंका","बांग्लादेश","पाकिस्तान"],"explanationHi":"पाकिस्तान ने बाहर रहना चुना, इसलिए यह उपग्रह अन्य SAARC सदस्यों की सेवा करता है; इसे मई 2017 में GSLV से प्रक्षेपित किया गया।"},
  {"id":"gk-science-tech-167","question":"Megha-Tropiques (2011), for studying the tropical water cycle, and SARAL (2013), for ocean altimetry, were joint missions of ISRO with:","options":["JAXA of Japan","CNES of France","NASA of the United States","Roscosmos of Russia"],"answer":1,"explanation":"Both were Indo-French missions with CNES; SARAL carries the French AltiKa altimeter. ISRO's major joint mission with NASA is NISAR.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उष्णकटिबंधीय जलचक्र के अध्ययन के लिए मेघा-ट्रॉपिक्स (2011) और समुद्री उन्नयनमिति के लिए सरल (SARAL, 2013) ISRO के किसके साथ संयुक्त मिशन थे?","optionsHi":["जापान की JAXA","फ्रांस की CNES","अमेरिका की NASA","रूस की रॉसकॉसमॉस"],"explanationHi":"दोनों CNES के साथ भारत-फ्रांस के मिशन थे; सरल में फ्रांस का AltiKa अल्टीमीटर लगा है। NASA के साथ ISRO का प्रमुख संयुक्त मिशन NISAR है।"},
  {"id":"gk-science-tech-168","question":"RISAT-2, India's first radar imaging satellite to reach orbit (2009), was built with the help of:","options":["France","Russia","Israel","The United States"],"answer":2,"explanation":"RISAT-2 used an X-band radar from Israel Aerospace Industries and was rushed into service after 2008; the indigenous RISAT-1 followed in 2012.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत के कक्षा में पहुँचने वाले पहले रडार इमेजिंग उपग्रह RISAT-2 (2009) के निर्माण में किसकी सहायता ली गई?","optionsHi":["फ्रांस","रूस","इज़राइल","संयुक्त राज्य अमेरिका"],"explanationHi":"RISAT-2 में इज़राइल एयरोस्पेस इंडस्ट्रीज़ का X-बैंड रडार लगा था और 2008 के बाद इसे तेज़ी से सेवा में लाया गया; स्वदेशी RISAT-1 2012 में आया।"},
  {"id":"gk-science-tech-169","question":"HySIS, launched by ISRO in 2018, is an Earth-observation satellite built to use:","options":["Synthetic aperture radar","Laser altimetry","Hyperspectral imaging","Gravity field mapping"],"answer":2,"explanation":"The Hyperspectral Imaging Satellite records the Earth in many narrow, contiguous wavelength bands, useful for farming, forestry, minerals and coastal studies.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"ISRO द्वारा 2018 में प्रक्षेपित HySIS एक पृथ्वी-अवलोकन उपग्रह है, जिसे किसका उपयोग करने के लिए बनाया गया?","optionsHi":["सिंथेटिक अपर्चर रडार","लेज़र उन्नयनमिति","हाइपरस्पेक्ट्रल इमेजिंग","गुरुत्व क्षेत्र मानचित्रण"],"explanationHi":"हाइपरस्पेक्ट्रल इमेजिंग सैटेलाइट पृथ्वी को अनेक संकरे, सतत तरंगदैर्घ्य बैंडों में दर्ज करता है, जो कृषि, वानिकी, खनिज और तटीय अध्ययनों में उपयोगी है।"},
  {"id":"gk-science-tech-170","question":"EMISAT, launched on PSLV-C45 in April 2019, was built mainly to:","options":["Gather electronic intelligence by picking up radar signals for DRDO","Relay secure communications among Indian Navy ships at sea","Map soil moisture across India's farmland using microwaves","Monitor ocean colour and chlorophyll levels for the fishing industry"],"answer":0,"explanation":"EMISAT carries DRDO's Kautilya electronic-intelligence package to locate enemy radars; naval communication is GSAT-7's role.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अप्रैल 2019 में PSLV-C45 से प्रक्षेपित EMISAT को मुख्यतः किसलिए बनाया गया था?","optionsHi":["DRDO के लिए रडार संकेतों को पकड़कर इलेक्ट्रॉनिक खुफ़िया जानकारी जुटाना","समुद्र में भारतीय नौसेना के पोतों के बीच सुरक्षित संचार प्रसारित करना","माइक्रोवेव से भारत के कृषि क्षेत्रों में मृदा आर्द्रता का मानचित्रण करना","मत्स्य उद्योग के लिए सागरीय रंग और क्लोरोफ़िल स्तरों की निगरानी करना"],"explanationHi":"EMISAT में DRDO का कौटिल्य इलेक्ट्रॉनिक-खुफ़िया पैकेज है, जो शत्रु के रडारों का स्थान पता करता है; नौसैनिक संचार GSAT-7 की भूमिका है।"},
  {"id":"gk-science-tech-171","question":"GSAT-11, India's heaviest satellite when launched in December 2018 (about 5,850 kg), was put in orbit by:","options":["An Ariane 5 from French Guiana","An LVM3 from Sriharikota","A GSLV Mk II from Sriharikota","A Falcon 9 from Florida"],"answer":0,"explanation":"At that time GSAT-11 was too heavy for LVM3's capacity to geosynchronous transfer orbit (about 4 tonnes), so it went on an Ariane 5.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"दिसंबर 2018 में प्रक्षेपित होते समय भारत के सबसे भारी उपग्रह GSAT-11 (लगभग 5,850 kg) को कक्षा में किसने स्थापित किया?","optionsHi":["फ्रेंच गयाना से एरियन 5","श्रीहरिकोटा से LVM3","श्रीहरिकोटा से GSLV Mk II","फ़्लोरिडा से फाल्कन 9"],"explanationHi":"उस समय GSAT-11, भूतुल्यकालिक स्थानांतरण कक्षा तक LVM3 की क्षमता (लगभग 4 टन) के लिए बहुत भारी था, इसलिए इसे एरियन 5 से भेजा गया।"},
  {"id":"gk-science-tech-172","question":"The Indian Deep Space Network, which tracked Chandrayaan-1 and the Mars Orbiter Mission, is located at:","options":["Hassan, Karnataka","Sriharikota, Andhra Pradesh","Byalalu, near Bengaluru","Thumba, Kerala"],"answer":2,"explanation":"IDSN's large antennas are at Byalalu near Bengaluru, run by ISTRAC. Hassan hosts the Master Control Facility for geostationary satellites.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"चंद्रयान-1 और मंगल कक्षित्र मिशन को ट्रैक करने वाला भारतीय गहन अंतरिक्ष नेटवर्क कहाँ स्थित है?","optionsHi":["हासन, कर्नाटक","श्रीहरिकोटा, आंध्र प्रदेश","बेंगलुरु के निकट ब्यालालू","थुंबा, केरल"],"explanationHi":"IDSN के विशाल एंटेना बेंगलुरु के निकट ब्यालालू में हैं, जिनका संचालन ISTRAC करता है। हासन में भूस्थिर उपग्रहों की मास्टर कंट्रोल सुविधा है।"},
  {"id":"gk-science-tech-173","question":"The Sun–Earth L1 point was chosen for Aditya-L1 mainly because a spacecraft there:","options":["Lies inside Earth's magnetic field, which shields it from radiation","Sits about 384,000 km away, at the same distance as the Moon","Feels no gravity at all, so it never needs fuel to stay there","Can watch the Sun continuously without being eclipsed"],"answer":3,"explanation":"L1, about 1.5 million km sunward of Earth, gives an uninterrupted view of the Sun; it lies outside the magnetosphere and the craft still needs small station-keeping burns in its halo orbit.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"आदित्य-L1 के लिए सूर्य–पृथ्वी L1 बिंदु मुख्यतः इसलिए चुना गया क्योंकि वहाँ स्थित अंतरिक्ष यान:","optionsHi":["पृथ्वी के चुंबकीय क्षेत्र के भीतर रहता है, जो उसे विकिरण से बचाता है","लगभग 384,000 km दूर, यानी चंद्रमा की दूरी पर, स्थित होता है","किसी भी गुरुत्व का अनुभव नहीं करता, इसलिए वहाँ टिके रहने के लिए उसे कभी ईंधन नहीं चाहिए","ग्रहण से बाधित हुए बिना सूर्य को लगातार देख सकता है"],"explanationHi":"L1, पृथ्वी से सूर्य की ओर लगभग 1.5 मिलियन km पर, सूर्य का निर्बाध दृश्य देता है; यह चुंबकमंडल के बाहर है और यान को अपनी हेलो कक्षा में बने रहने के लिए छोटे स्थिति-रखरखाव दहन करने पड़ते हैं।"},
  {"id":"gk-science-tech-174","question":"Assertion (A): Chandrayaan-3's Vikram lander and Pragyan rover were designed to work for about one lunar day. Reason (R): A lunar day lasts about 14 Earth days, and their systems were not built to survive the extreme cold of the lunar night.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Being solar-powered without heaters for the night, which falls below about −120°C, the two were planned for one lunar daylight period, and they did not wake after the first night.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): चंद्रयान-3 के विक्रम लैंडर और प्रज्ञान रोवर को लगभग एक चंद्र दिवस तक कार्य करने के लिए डिज़ाइन किया गया था। कारण (R): एक चंद्र दिवस लगभग 14 पृथ्वी दिवसों का होता है, और उनकी प्रणालियाँ चंद्र रात की अत्यधिक ठंड को सहने के लिए नहीं बनाई गई थीं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"सौर ऊर्जा से चलने वाले और रात के लिए हीटर रहित ये दोनों, जब रात में तापमान लगभग −120°C से नीचे चला जाता है, एक चंद्र दिन के प्रकाश-काल के लिए नियोजित थे, और पहली रात के बाद ये पुनः सक्रिय नहीं हुए।"},
  {"id":"gk-science-tech-175","question":"Dr A. P. J. Abdul Kalam Island, from where long-range Agni missiles are test-fired, was earlier known as:","options":["Rameswaram Island, Tamil Nadu","Wheeler Island, Odisha","Sriharikota Island, Andhra Pradesh","Havelock Island, Andaman and Nicobar"],"answer":1,"explanation":"Wheeler Island off the Odisha coast was renamed in 2015; Chandipur on the mainland houses the Integrated Test Range. Havelock is now Swaraj Dweep.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"डॉ. ए. पी. जे. अब्दुल कलाम द्वीप, जहाँ से लंबी दूरी की अग्नि मिसाइलों का परीक्षण किया जाता है, पहले किस नाम से जाना जाता था?","optionsHi":["रामेश्वरम द्वीप, तमिलनाडु","व्हीलर द्वीप, ओडिशा","श्रीहरिकोटा द्वीप, आंध्र प्रदेश","हैवलॉक द्वीप, अंडमान और निकोबार"],"explanationHi":"ओडिशा तट के निकट स्थित व्हीलर द्वीप का नाम 2015 में बदला गया; मुख्य भूमि पर चांदीपुर में एकीकृत परीक्षण रेंज है। हैवलॉक अब स्वराज द्वीप है।"},
  {"id":"gk-science-tech-176","question":"Arrange these missiles in increasing order of their approximate range: 1. Agni-III  2. Agni-I  3. Agni-V  4. Agni-II","options":["2-4-1-3","2-1-4-3","4-2-1-3","2-4-3-1"],"answer":0,"explanation":"Agni-I is about 700 km, Agni-II about 2,000 km, Agni-III about 3,000 km and Agni-V over 5,000 km.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"इन मिसाइलों को उनकी अनुमानित मारक सीमा के बढ़ते क्रम में व्यवस्थित कीजिए: 1. अग्नि-III  2. अग्नि-I  3. अग्नि-V  4. अग्नि-II","optionsHi":["2-4-1-3","2-1-4-3","4-2-1-3","2-4-3-1"],"explanationHi":"अग्नि-I लगभग 700 km, अग्नि-II लगभग 2,000 km, अग्नि-III लगभग 3,000 km और अग्नि-V 5,000 km से अधिक की मारक सीमा वाली है।"},
  {"id":"gk-science-tech-177","question":"Agni-V, India's longest-range ballistic missile, was first flight-tested in:","options":["2008","2016","2018","2012"],"answer":3,"explanation":"Agni-V's first test from Wheeler Island was on 19 April 2012; its MIRV version was tested under Mission Divyastra in 2024.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"भारत की सबसे लंबी दूरी की बैलिस्टिक मिसाइल अग्नि-V का पहला उड़ान परीक्षण किस वर्ष हुआ?","optionsHi":["2008","2016","2018","2012"],"explanationHi":"अग्नि-V का व्हीलर द्वीप से पहला परीक्षण 19 अप्रैल 2012 को हुआ; इसके MIRV संस्करण का परीक्षण 2024 में मिशन दिव्यास्त्र के अंतर्गत हुआ।"},
  {"id":"gk-science-tech-178","question":"The name of the BrahMos missile is formed from:","options":["The god Brahma and the city of Moscow","The Brahmastra weapon and the Moskit missile","The Brahmaputra and Moskva rivers","The Brahmaputra and the Moscow Aviation Institute"],"answer":2,"explanation":"BrahMos joins the names of India's Brahmaputra and Russia's Moskva rivers, reflecting the Indo-Russian joint venture.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"ब्रह्मोस मिसाइल का नाम किससे मिलकर बना है?","optionsHi":["देवता ब्रह्मा और मास्को शहर","ब्रह्मास्त्र शस्त्र और मोस्किट मिसाइल","ब्रह्मपुत्र और मोस्कवा नदियाँ","ब्रह्मपुत्र और मास्को एविएशन इंस्टीट्यूट"],"explanationHi":"ब्रह्मोस भारत की ब्रह्मपुत्र और रूस की मोस्कवा नदियों के नामों को जोड़ता है, जो भारत-रूस संयुक्त उद्यम को दर्शाता है।"},
  {"id":"gk-science-tech-179","question":"BrahMos is a two-stage missile with a solid-propellant booster followed by a:","options":["Scramjet that sustains hypersonic cruise","Liquid-fuelled ramjet that sustains supersonic cruise","Small turbofan that sustains subsonic cruise","Solid-fuel ducted ramjet that sustains hypersonic cruise"],"answer":1,"explanation":"After the booster burns out, a liquid-fuel ramjet drives BrahMos at about Mach 2.8. Nirbhay uses a turbofan, and the solid-fuel ducted ramjet is a separate DRDO technology for air-to-air missiles.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ब्रह्मोस दो चरणों वाली मिसाइल है, जिसमें ठोस-प्रणोदक बूस्टर के बाद क्या होता है?","optionsHi":["अतिध्वनिक क्रूज़ को बनाए रखने वाला स्क्रैमजेट","सुपरसोनिक क्रूज़ को बनाए रखने वाला द्रव-ईंधन रैमजेट","अवध्वनिक क्रूज़ को बनाए रखने वाला छोटा टर्बोफ़ैन","अतिध्वनिक क्रूज़ को बनाए रखने वाला ठोस-ईंधन डक्टेड रैमजेट"],"explanationHi":"बूस्टर जल जाने के बाद द्रव-ईंधन रैमजेट ब्रह्मोस को लगभग मैक 2.8 पर चलाता है। निर्भय में टर्बोफ़ैन होता है, और ठोस-ईंधन डक्टेड रैमजेट हवा से हवा में मार करने वाली मिसाइलों के लिए DRDO की अलग प्रौद्योगिकी है।"},
  {"id":"gk-science-tech-180","question":"The first export order for the BrahMos missile, signed in January 2022, came from:","options":["Vietnam","Indonesia","The Philippines","The United Arab Emirates"],"answer":2,"explanation":"The Philippines signed for shore-based anti-ship BrahMos batteries in January 2022; the first deliveries reached it in 2024.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"जनवरी 2022 में हस्ताक्षरित ब्रह्मोस मिसाइल का पहला निर्यात आदेश किससे आया?","optionsHi":["वियतनाम","इंडोनेशिया","फिलीपींस","संयुक्त अरब अमीरात"],"explanationHi":"फिलीपींस ने जनवरी 2022 में तट-आधारित पोत-रोधी ब्रह्मोस बैटरियों के लिए अनुबंध किया; पहली खेप उसे 2024 में मिली।"},
  {"id":"gk-science-tech-181","question":"India's Ballistic Missile Defence programme has two layers. Which pairing is correct?","options":["Prithvi Air Defence for interception inside the atmosphere; Advanced Air Defence outside it","Prithvi Air Defence for interception outside the atmosphere; Advanced Air Defence inside it","Akash for interception outside the atmosphere; Prithvi Air Defence inside it","Advanced Air Defence for both layers; Prithvi Air Defence only for cruise missiles"],"answer":1,"explanation":"PAD (Pradyumna) engages missiles at high, exo-atmospheric altitudes, while AAD (Ashwin) intercepts at lower, endo-atmospheric altitudes; Akash is an air-defence SAM, not part of the BMD layers.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत के बैलिस्टिक मिसाइल रक्षा कार्यक्रम की दो परतें हैं। कौन-सा युग्म सही है?","optionsHi":["वायुमंडल के भीतर अवरोधन के लिए पृथ्वी एयर डिफ़ेंस; उसके बाहर के लिए एडवांस्ड एयर डिफ़ेंस","वायुमंडल के बाहर अवरोधन के लिए पृथ्वी एयर डिफ़ेंस; उसके भीतर के लिए एडवांस्ड एयर डिफ़ेंस","वायुमंडल के बाहर अवरोधन के लिए आकाश; उसके भीतर के लिए पृथ्वी एयर डिफ़ेंस","दोनों परतों के लिए एडवांस्ड एयर डिफ़ेंस; पृथ्वी एयर डिफ़ेंस केवल क्रूज़ मिसाइलों के लिए"],"explanationHi":"PAD (प्रद्युम्न) ऊँचाई पर, वायुमंडल के बाहर, मिसाइलों को भेदता है, जबकि AAD (अश्विन) कम ऊँचाई पर, वायुमंडल के भीतर, अवरोधन करता है; आकाश वायु-रक्षा की सतह से हवा में मार करने वाली मिसाइल है, BMD की परतों का भाग नहीं।"},
  {"id":"gk-science-tech-182","question":"India declared its nuclear triad operational in November 2018 when:","options":["Agni-V was handed over to the Strategic Forces Command","Rafale jets were certified to carry nuclear weapons","The K-4 missile was first fired from a submarine","INS Arihant completed its first deterrence patrol"],"answer":3,"explanation":"Arihant's first deterrence patrol added an operational sea-based leg to India's land- and air-based nuclear delivery systems. Rafales arrived only in 2020.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत ने नवंबर 2018 में अपनी परमाणु त्रयी को परिचालन में घोषित किया, जब:","optionsHi":["अग्नि-V को सामरिक बल कमान को सौंपा गया","राफेल विमानों को परमाणु हथियार ले जाने के लिए प्रमाणित किया गया","K-4 मिसाइल को पहली बार पनडुब्बी से दागा गया","INS अरिहंत ने अपना पहला निवारक गश्ती पूरा किया"],"explanationHi":"अरिहंत की पहली निवारक गश्ती ने भारत की भूमि- और वायु-आधारित परमाणु प्रक्षेपण प्रणालियों में परिचालन समुद्र-आधारित कड़ी जोड़ दी। राफेल केवल 2020 में आए।"},
  {"id":"gk-science-tech-183","question":"The 'K' in India's K-series submarine-launched ballistic missiles, such as K-15 Sagarika and K-4, stands for:","options":["K. Kasturirangan","Kalpana Chawla","K. Sivan","A. P. J. Abdul Kalam"],"answer":3,"explanation":"The series is named in honour of Dr Kalam, who led India's missile programme.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"भारत की K-श्रृंखला की पनडुब्बी से दागी जाने वाली बैलिस्टिक मिसाइलों, जैसे K-15 सागरिका और K-4, में \"K\" का अर्थ क्या है?","optionsHi":["के. कस्तूरीरंगन","कल्पना चावला","के. सिवन","ए. पी. जे. अब्दुल कलाम"],"explanationHi":"यह श्रृंखला डॉ. कलाम के सम्मान में नामित है, जिन्होंने भारत के मिसाइल कार्यक्रम का नेतृत्व किया।"},
  {"id":"gk-science-tech-184","question":"Match the DRDO system with its description. A. Rudram  B. Helina  C. SMART  D. Shaurya; 1. Missile-assisted release of a lightweight anti-submarine torpedo  2. Helicopter-launched anti-tank guided missile  3. Air-launched anti-radiation missile  4. Canister-launched hypersonic surface-to-surface missile","options":["A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-4, B-2, C-1, D-3"],"answer":0,"explanation":"Rudram homes on enemy radar emissions; Helina is the helicopter version of Nag; SMART carries a torpedo far beyond its own range; Shaurya is a land variant related to the K-15.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"DRDO प्रणाली का उसके विवरण से मिलान कीजिए। A. रुद्रम  B. हेलिना  C. SMART  D. शौर्य; 1. हल्के पनडुब्बी-रोधी टॉरपीडो का मिसाइल-सहायता से प्रक्षेपण  2. हेलीकॉप्टर से दागी जाने वाली टैंक-रोधी निर्देशित मिसाइल  3. हवा से दागी जाने वाली विकिरण-रोधी मिसाइल  4. कैनिस्टर से दागी जाने वाली अतिध्वनिक सतह से सतह पर मार करने वाली मिसाइल","optionsHi":["A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-4, B-2, C-1, D-3"],"explanationHi":"रुद्रम शत्रु के रडार उत्सर्जनों की ओर बढ़ती है; हेलिना नाग का हेलीकॉप्टर संस्करण है; SMART टॉरपीडो को उसकी अपनी सीमा से कहीं दूर तक पहुँचाती है; शौर्य K-15 से संबंधित भूमि संस्करण है।"},
  {"id":"gk-science-tech-185","question":"The Hypersonic Technology Demonstrator Vehicle (HSTDV), flight-tested by DRDO in September 2020, was powered in its cruise phase by a:","options":["Turbojet engine","Liquid-fuel rocket engine","Ramjet engine","Scramjet engine"],"answer":3,"explanation":"HSTDV used an air-breathing scramjet after an Agni-I booster took it to hypersonic speed; a ramjet works only up to about Mach 3–4.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"सितंबर 2020 में DRDO द्वारा उड़ान-परीक्षित अतिध्वनिक प्रौद्योगिकी प्रदर्शक यान (HSTDV) अपने क्रूज़ चरण में किससे संचालित था?","optionsHi":["टर्बोजेट इंजन","द्रव-ईंधन रॉकेट इंजन","रैमजेट इंजन","स्क्रैमजेट इंजन"],"explanationHi":"अग्नि-I बूस्टर द्वारा अतिध्वनिक गति तक पहुँचाने के बाद HSTDV ने वायु-श्वसन स्क्रैमजेट का उपयोग किया; रैमजेट केवल लगभग मैक 3–4 तक ही काम करता है।"},
  {"id":"gk-science-tech-186","question":"The Medium-Range Surface-to-Air Missile (MRSAM), also known as Barak-8, was developed by DRDO jointly with:","options":["Russia","Israel","France","The United States"],"answer":1,"explanation":"MRSAM was co-developed by DRDO and Israel Aerospace Industries and serves the Navy, Air Force and Army.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"मध्यम दूरी की सतह से हवा में मार करने वाली मिसाइल (MRSAM), जिसे बराक-8 भी कहते हैं, DRDO ने किसके साथ मिलकर विकसित की?","optionsHi":["रूस","इज़राइल","फ्रांस","संयुक्त राज्य अमेरिका"],"explanationHi":"MRSAM को DRDO और इज़राइल एयरोस्पेस इंडस्ट्रीज़ ने मिलकर विकसित किया और यह नौसेना, वायुसेना तथा थलसेना की सेवा करती है।"},
  {"id":"gk-science-tech-187","question":"The Tejas Mk1 light combat aircraft is powered by:","options":["The indigenous Kaveri turbofan from GTRE","The American General Electric F404 turbofan","The Russian Saturn AL-31FP turbofan","The French Safran M88 turbofan"],"answer":1,"explanation":"The Kaveri engine, meant for Tejas, fell short of requirements, so Tejas flies on the GE F404. The AL-31FP powers the Su-30MKI and the M88 the Rafale.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"तेजस Mk1 हल्का लड़ाकू विमान किससे संचालित होता है?","optionsHi":["GTRE का स्वदेशी कावेरी टर्बोफ़ैन","अमेरिकी जनरल इलेक्ट्रिक F404 टर्बोफ़ैन","रूसी सैटर्न AL-31FP टर्बोफ़ैन","फ्रांसीसी सफ़रान M88 टर्बोफ़ैन"],"explanationHi":"तेजस के लिए बनाया गया कावेरी इंजन आवश्यकताओं पर खरा नहीं उतरा, इसलिए तेजस GE F404 पर उड़ता है। AL-31FP Su-30MKI को और M88 राफेल को शक्ति देता है।"},
  {"id":"gk-science-tech-188","question":"The Light Combat Aircraft, first flown in January 2001, was named 'Tejas' in 2003 by:","options":["A. P. J. Abdul Kalam","Atal Bihari Vajpayee","Manmohan Singh","George Fernandes"],"answer":1,"explanation":"Prime Minister Atal Bihari Vajpayee named the aircraft Tejas, Sanskrit for radiance, in May 2003.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"जनवरी 2001 में पहली बार उड़ने वाले हल्के लड़ाकू विमान का नाम 2003 में \"तेजस\" किसने रखा?","optionsHi":["ए. पी. जे. अब्दुल कलाम","अटल बिहारी वाजपेयी","मनमोहन सिंह","जॉर्ज फ़र्नांडिस"],"explanationHi":"प्रधानमंत्री अटल बिहारी वाजपेयी ने मई 2003 में विमान का नाम तेजस (संस्कृत में आभा) रखा।"},
  {"id":"gk-science-tech-189","question":"Match the DRDO laboratory with its location and field. A. DRDL  B. GTRE  C. CVRDE  D. NSTL; 1. Hyderabad, missiles  2. Avadi, combat vehicles  3. Visakhapatnam, underwater weapons  4. Bengaluru, gas turbine engines","options":["A-1, B-2, C-4, D-3","A-3, B-4, C-2, D-1","A-1, B-4, C-2, D-3","A-1, B-4, C-3, D-2"],"answer":2,"explanation":"The Defence Research and Development Laboratory (Hyderabad) leads missile work; GTRE (Bengaluru) built the Kaveri engine; CVRDE (Avadi) developed Arjun; NSTL (Visakhapatnam) develops torpedoes.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"DRDO प्रयोगशाला का उसके स्थान और क्षेत्र से मिलान कीजिए। A. DRDL  B. GTRE  C. CVRDE  D. NSTL; 1. हैदराबाद, मिसाइलें  2. अवडी, युद्धक वाहन  3. विशाखापत्तनम, जल-अंतर्गत हथियार  4. बेंगलुरु, गैस टर्बाइन इंजन","optionsHi":["A-1, B-2, C-4, D-3","A-3, B-4, C-2, D-1","A-1, B-4, C-2, D-3","A-1, B-4, C-3, D-2"],"explanationHi":"रक्षा अनुसंधान एवं विकास प्रयोगशाला (हैदराबाद) मिसाइल कार्य का नेतृत्व करती है; GTRE (बेंगलुरु) ने कावेरी इंजन बनाया; CVRDE (अवडी) ने अर्जुन विकसित किया; NSTL (विशाखापत्तनम) टॉरपीडो विकसित करती है।"},
  {"id":"gk-science-tech-190","question":"DRDO's Defence Research and Development Establishment (DRDE) at Gwalior specialises in:","options":["Protection against chemical and biological agents","High-altitude food and agriculture for troops","Armour plates and explosives for tanks","Sonar and underwater surveillance systems"],"answer":0,"explanation":"DRDE Gwalior develops detection, protection and decontamination for chemical and biological threats. High-altitude agriculture is DIHAR's work at Leh, and sonar NPOL's at Kochi.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"ग्वालियर स्थित DRDO की रक्षा अनुसंधान एवं विकास स्थापना (DRDE) किसमें विशेषज्ञता रखती है?","optionsHi":["रासायनिक और जैविक कारकों से सुरक्षा","सैनिकों के लिए उच्च-तुंगता खाद्य और कृषि","टैंकों के लिए कवच प्लेट और विस्फोटक","सोनार और जल-अंतर्गत निगरानी प्रणालियाँ"],"explanationHi":"DRDE ग्वालियर रासायनिक और जैविक खतरों के लिए संसूचन, सुरक्षा और विसंदूषण विकसित करती है। उच्च-तुंगता कृषि लेह में DIHAR का और सोनार कोच्चि में NPOL का कार्य है।"},
  {"id":"gk-science-tech-191","question":"Match the Indian Navy shipbuilding project with its class. A. Project 15B  B. Project 17A  C. Project 75  D. Project 28; 1. Nilgiri-class stealth frigates  2. Visakhapatnam-class destroyers  3. Kamorta-class anti-submarine corvettes  4. Kalvari-class submarines","options":["A-2, B-1, C-4, D-3","A-1, B-2, C-4, D-3","A-2, B-1, C-3, D-4","A-2, B-4, C-1, D-3"],"answer":0,"explanation":"Project 15B produced the Visakhapatnam-class destroyers, 17A the Nilgiri-class frigates, 75 the Scorpène-based Kalvari submarines and 28 the Kamorta-class ASW corvettes.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारतीय नौसेना की पोत-निर्माण परियोजना का उसकी श्रेणी से मिलान कीजिए। A. प्रोजेक्ट 15B  B. प्रोजेक्ट 17A  C. प्रोजेक्ट 75  D. प्रोजेक्ट 28; 1. नीलगिरि श्रेणी के स्टेल्थ फ्रिगेट  2. विशाखापत्तनम श्रेणी के विध्वंसक पोत  3. कामोर्ता श्रेणी के पनडुब्बी-रोधी कॉर्वेट  4. कलवरी श्रेणी की पनडुब्बियाँ","optionsHi":["A-2, B-1, C-4, D-3","A-1, B-2, C-4, D-3","A-2, B-1, C-3, D-4","A-2, B-4, C-1, D-3"],"explanationHi":"प्रोजेक्ट 15B से विशाखापत्तनम श्रेणी के विध्वंसक पोत बने, 17A से नीलगिरि श्रेणी के फ्रिगेट, 75 से स्कॉर्पीन-आधारित कलवरी पनडुब्बियाँ और 28 से कामोर्ता श्रेणी के ASW कॉर्वेट।"},
  {"id":"gk-science-tech-192","question":"INS Vikrant, India's first indigenously built aircraft carrier, commissioned in 2022, was built by:","options":["Mazagon Dock Shipbuilders, Mumbai","Garden Reach Shipbuilders, Kolkata","Cochin Shipyard Limited, Kochi","Hindustan Shipyard Limited, Visakhapatnam"],"answer":2,"explanation":"Cochin Shipyard built Vikrant to a design by the Navy's Warship Design Bureau; Mazagon Dock builds the Navy's destroyers and Kalvari submarines.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"2022 में सेवा में शामिल भारत के पहले स्वदेशी रूप से निर्मित विमानवाहक पोत INS विक्रांत का निर्माण किसने किया?","optionsHi":["मझगाँव डॉक शिपबिल्डर्स, मुंबई","गार्डन रीच शिपबिल्डर्स, कोलकाता","कोचीन शिपयार्ड लिमिटेड, कोच्चि","हिंदुस्तान शिपयार्ड लिमिटेड, विशाखापत्तनम"],"explanationHi":"कोचीन शिपयार्ड ने नौसेना के युद्धपोत डिज़ाइन ब्यूरो के डिज़ाइन पर विक्रांत बनाया; मझगाँव डॉक नौसेना के विध्वंसक पोत और कलवरी पनडुब्बियाँ बनाता है।"},
  {"id":"gk-science-tech-193","question":"The Su-30MKI fighters of the Indian Air Force are licence-built by Hindustan Aeronautics Limited at:","options":["Bengaluru","Koraput","Kanpur","Nashik"],"answer":3,"explanation":"HAL's Nashik division assembles the Su-30MKI; its Koraput division makes the AL-31FP engines and Bengaluru builds Tejas.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"भारतीय वायुसेना के Su-30MKI लड़ाकू विमान हिंदुस्तान एयरोनॉटिक्स लिमिटेड द्वारा कहाँ लाइसेंस के अंतर्गत बनाए जाते हैं?","optionsHi":["बेंगलुरु","कोरापुट","कानपुर","नासिक"],"explanationHi":"HAL का नासिक प्रभाग Su-30MKI को असेंबल करता है; इसका कोरापुट प्रभाग AL-31FP इंजन बनाता है और बेंगलुरु में तेजस बनता है।"},
  {"id":"gk-science-tech-194","question":"K9 Vajra-T, a 155 mm self-propelled howitzer made by Larsen & Toubro for the Indian Army, is based on a design from:","options":["Sweden","The United States","France","South Korea"],"answer":3,"explanation":"It is adapted from Hanwha's K9 Thunder of South Korea. Sweden's Bofors supplied the FH-77B towed gun of the 1980s.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"भारतीय थलसेना के लिए लार्सन एंड टुब्रो द्वारा बनाई गई 155 mm की स्व-चालित हॉवित्ज़र K9 वज्र-T किस देश के डिज़ाइन पर आधारित है?","optionsHi":["स्वीडन","संयुक्त राज्य अमेरिका","फ्रांस","दक्षिण कोरिया"],"explanationHi":"इसे दक्षिण कोरिया की हान्वा के K9 थंडर से अनुकूलित किया गया है। स्वीडन की बोफ़ोर्स ने 1980 के दशक की FH-77B खींची जाने वाली तोप दी थी।"},
  {"id":"gk-science-tech-195","question":"TAPAS (earlier called Rustom-II), developed by DRDO's Aeronautical Development Establishment, is a:","options":["Medium-altitude long-endurance unmanned aerial vehicle","Airborne early warning and control aircraft","Light utility helicopter for high-altitude posts","Intermediate jet trainer aircraft for pilots"],"answer":0,"explanation":"TAPAS-BH-201 is a MALE drone for surveillance; Netra is the airborne early warning system and the HJT-36 Sitara an intermediate jet trainer.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"DRDO की वैमानिकी विकास स्थापना द्वारा विकसित TAPAS (पूर्व नाम रुस्तम-II) क्या है?","optionsHi":["मध्यम ऊँचाई पर दीर्घ-सहनशक्ति वाला मानवरहित हवाई वाहन","हवाई पूर्व चेतावनी एवं नियंत्रण विमान","ऊँचाई की चौकियों के लिए हल्का उपयोगिता हेलीकॉप्टर","पायलटों के लिए मध्यवर्ती जेट प्रशिक्षक विमान"],"explanationHi":"TAPAS-BH-201 निगरानी के लिए MALE ड्रोन है; नेत्र हवाई पूर्व चेतावनी प्रणाली है और HJT-36 सितारा मध्यवर्ती जेट प्रशिक्षक विमान।"},
  {"id":"gk-science-tech-196","question":"National Technology Day is observed in India on 11 May to mark:","options":["The Smiling Buddha nuclear test at Pokhran in 1974","The first of the Pokhran-II nuclear tests in 1998","The first launch of an Indian rocket into orbit","The founding of the DRDO by merging defence labs"],"answer":1,"explanation":"The first three Pokhran-II tests took place on 11 May 1998, the day the Hansa-3 aircraft and the Trishul missile were also tested. Smiling Buddha was on 18 May 1974.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"भारत में राष्ट्रीय प्रौद्योगिकी दिवस 11 मई को किसकी स्मृति में मनाया जाता है?","optionsHi":["1974 में पोखरण में स्माइलिंग बुद्धा परमाणु परीक्षण","1998 में पोखरण-II के पहले परमाणु परीक्षण","किसी भारतीय रॉकेट का कक्षा में पहला प्रक्षेपण","रक्षा प्रयोगशालाओं को मिलाकर DRDO की स्थापना"],"explanationHi":"पोखरण-II के पहले तीन परीक्षण 11 मई 1998 को हुए, जिस दिन हंस-3 विमान और त्रिशूल मिसाइल का भी परीक्षण हुआ। स्माइलिंग बुद्धा 18 मई 1974 को हुआ था।"},
  {"id":"gk-science-tech-197","question":"Assertion (A): After the Pokhran-II tests of 1998, India declared a voluntary moratorium on further nuclear explosive testing. Reason (R): India signed the Comprehensive Nuclear-Test-Ban Treaty in September 1998.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"India announced a unilateral moratorium in 1998 but has never signed the CTBT, which it views as discriminatory.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): 1998 के पोखरण-II परीक्षणों के बाद भारत ने आगे के परमाणु विस्फोटक परीक्षण पर स्वैच्छिक स्थगन घोषित किया। कारण (R): भारत ने सितंबर 1998 में व्यापक परमाणु परीक्षण प्रतिबंध संधि पर हस्ताक्षर किए।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"भारत ने 1998 में एकपक्षीय स्थगन की घोषणा की, पर उसने CTBT पर कभी हस्ताक्षर नहीं किए, जिसे वह भेदभावपूर्ण मानता है।"},
  {"id":"gk-science-tech-198","question":"Under India's Nuclear Command Authority (2003), the Political Council, the only body that can authorise the use of nuclear weapons, is chaired by the:","options":["President of India","Defence Minister","National Security Adviser","Prime Minister"],"answer":3,"explanation":"The Political Council is chaired by the Prime Minister; the Executive Council, which advises it and carries out its directives, is chaired by the National Security Adviser.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत के परमाणु कमान प्राधिकरण (2003) के अंतर्गत राजनीतिक परिषद, जो परमाणु हथियारों के प्रयोग को अधिकृत करने वाली एकमात्र संस्था है, की अध्यक्षता कौन करता है?","optionsHi":["भारत के राष्ट्रपति","रक्षा मंत्री","राष्ट्रीय सुरक्षा सलाहकार","प्रधानमंत्री"],"explanationHi":"राजनीतिक परिषद की अध्यक्षता प्रधानमंत्री करते हैं; कार्यकारी परिषद, जो उसे परामर्श देती है और उसके निर्देशों को लागू करती है, की अध्यक्षता राष्ट्रीय सुरक्षा सलाहकार करते हैं।"},
  {"id":"gk-science-tech-199","question":"The Defence Research and Development Organisation (DRDO) was formed in:","options":["1958","1948","1962","1969"],"answer":0,"explanation":"DRDO was set up in 1958 by merging the Army's Technical Development Establishments with the Defence Science Organisation.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"रक्षा अनुसंधान एवं विकास संगठन (DRDO) का गठन कब हुआ?","optionsHi":["1958","1948","1962","1969"],"explanationHi":"DRDO की स्थापना 1958 में थलसेना के तकनीकी विकास प्रतिष्ठानों को रक्षा विज्ञान संगठन के साथ मिलाकर की गई।"},
  {"id":"gk-science-tech-200","question":"KAMINI, the small research reactor at Kalpakkam, is notable as the only operating reactor in the world that:","options":["Uses thorium–plutonium fuel and is cooled by liquid lead","Runs on natural uranium moderated by ordinary water","Uses uranium-233 as its fuel","Breeds tritium for fusion research"],"answer":2,"explanation":"KAMINI (Kalpakkam Mini reactor, 1996) uses U-233 bred from thorium, a step towards the third stage of India's nuclear programme.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कलपक्कम का छोटा अनुसंधान रिएक्टर कामिनी (KAMINI) किस कारण उल्लेखनीय है कि वह विश्व का एकमात्र परिचालित रिएक्टर है जो:","optionsHi":["थोरियम–प्लूटोनियम ईंधन का उपयोग करता है और द्रव सीसे से ठंडा किया जाता है","साधारण जल द्वारा मंदित प्राकृतिक यूरेनियम पर चलता है","ईंधन के रूप में यूरेनियम-233 का उपयोग करता है","संलयन अनुसंधान के लिए ट्राइटियम का प्रजनन करता है"],"explanationHi":"कामिनी (कलपक्कम मिनी रिएक्टर, 1996) थोरियम से बने U-233 का उपयोग करता है, जो भारत के परमाणु कार्यक्रम के तीसरे चरण की ओर एक कदम है।"},
  {"id":"gk-science-tech-201","question":"The Fast Breeder Test Reactor at Kalpakkam, which went critical in 1985, is known for using a fuel first developed in India:","options":["Plutonium–uranium mixed oxide","Plutonium–uranium mixed carbide","Metallic thorium rods","Enriched uranium dioxide"],"answer":1,"explanation":"FBTR runs on a plutonium-rich mixed carbide fuel; the larger Prototype Fast Breeder Reactor uses mixed oxide (MOX) fuel.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"1985 में क्रांतिक अवस्था में पहुँचा कलपक्कम का तीव्र प्रजनक परीक्षण रिएक्टर भारत में पहली बार विकसित किस ईंधन के उपयोग के लिए जाना जाता है?","optionsHi":["प्लूटोनियम–यूरेनियम मिश्रित ऑक्साइड","प्लूटोनियम–यूरेनियम मिश्रित कार्बाइड","धात्विक थोरियम छड़ें","समृद्ध यूरेनियम डाइऑक्साइड"],"explanationHi":"FBTR प्लूटोनियम-समृद्ध मिश्रित कार्बाइड ईंधन पर चलता है; बड़ा प्रोटोटाइप फास्ट ब्रीडर रिएक्टर मिश्रित ऑक्साइड (MOX) ईंधन का उपयोग करता है।"},
  {"id":"gk-science-tech-202","question":"CIRUS, the research reactor at Trombay whose plutonium was used for the 1974 nuclear test, was built with help from:","options":["The Soviet Union","France","Canada","The United Kingdom"],"answer":2,"explanation":"CIRUS (Canada-India Reactor, US) was supplied by Canada, with heavy water from the United States; it went critical in 1960.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"ट्रॉम्बे का अनुसंधान रिएक्टर CIRUS, जिसके प्लूटोनियम का उपयोग 1974 के परमाणु परीक्षण में हुआ, किसकी सहायता से बनाया गया था?","optionsHi":["सोवियत संघ","फ्रांस","कनाडा","यूनाइटेड किंगडम"],"explanationHi":"CIRUS (कैनेडा-इंडिया रिएक्टर, यूएस) की आपूर्ति कनाडा ने की, जिसका भारी जल अमेरिका से आया; यह 1960 में क्रांतिक अवस्था में पहुँचा।"},
  {"id":"gk-science-tech-203","question":"Match the nuclear power station with its reactor type. A. Tarapur (units 1 and 2)  B. Rawatbhata (RAPS-1)  C. Kudankulam  D. Prototype Fast Breeder Reactor, Kalpakkam; 1. Russian VVER pressurised water reactor  2. US-supplied boiling water reactor  3. Sodium-cooled fast breeder reactor  4. Canadian CANDU-type heavy water reactor","options":["A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3"],"answer":3,"explanation":"Tarapur's first two units (1969) are General Electric BWRs, RAPS-1 is a CANDU-type PHWR built with Canada, Kudankulam uses Russian VVERs, and the PFBR is sodium-cooled.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"परमाणु विद्युत केंद्र का उसके रिएक्टर प्रकार से मिलान कीजिए। A. तारापुर (इकाई 1 और 2)  B. रावतभाटा (RAPS-1)  C. कुडनकुलम  D. प्रोटोटाइप फास्ट ब्रीडर रिएक्टर, कलपक्कम; 1. रूसी VVER दाबित जल रिएक्टर  2. अमेरिका-आपूर्ति उबलता जल रिएक्टर  3. सोडियम-शीतित तीव्र प्रजनक रिएक्टर  4. कनाडाई CANDU-प्रकार का भारी जल रिएक्टर","optionsHi":["A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3"],"explanationHi":"तारापुर की पहली दो इकाइयाँ (1969) जनरल इलेक्ट्रिक BWR हैं, RAPS-1 कनाडा के सहयोग से बना CANDU-प्रकार का PHWR है, कुडनकुलम रूसी VVER का उपयोग करता है, और PFBR सोडियम-शीतित है।"},
  {"id":"gk-science-tech-204","question":"India's first indigenously designed 700 MWe pressurised heavy water reactor to reach criticality, in 2020, is located at:","options":["Kakrapar, Gujarat","Rawatbhata, Rajasthan","Kaiga, Karnataka","Gorakhpur, Haryana"],"answer":0,"explanation":"Kakrapar unit 3 (KAPP-3) went critical in July 2020, the first of the 700 MWe PHWR fleet; earlier indigenous PHWRs were 220 MWe or 540 MWe.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2020 में क्रांतिकता प्राप्त करने वाला भारत का पहला स्वदेशी रूप से डिज़ाइन किया गया 700 MWe दाबित भारी जल रिएक्टर कहाँ स्थित है?","optionsHi":["काकरापार, गुजरात","रावतभाटा, राजस्थान","कैगा, कर्नाटक","गोरखपुर, हरियाणा"],"explanationHi":"काकरापार इकाई 3 (KAPP-3) ने जुलाई 2020 में क्रांतिकता प्राप्त की, जो 700 MWe PHWR बेड़े की पहली इकाई है; इससे पहले के स्वदेशी PHWR 220 MWe या 540 MWe के थे।"},
  {"id":"gk-science-tech-205","question":"Arrange in chronological order: 1. Department of Atomic Energy set up  2. Atomic Energy Commission set up  3. Tata Institute of Fundamental Research founded  4. APSARA reactor goes critical","options":["2-3-1-4","3-2-4-1","3-2-1-4","3-1-2-4"],"answer":2,"explanation":"TIFR (1945), Atomic Energy Commission (1948), DAE (1954) and APSARA, Asia's first research reactor (1956).","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. परमाणु ऊर्जा विभाग की स्थापना  2. परमाणु ऊर्जा आयोग की स्थापना  3. टाटा मूलभूत अनुसंधान संस्थान की स्थापना  4. अप्सरा रिएक्टर का क्रांतिक अवस्था में पहुँचना","optionsHi":["2-3-1-4","3-2-4-1","3-2-1-4","3-1-2-4"],"explanationHi":"TIFR (1945), परमाणु ऊर्जा आयोग (1948), DAE (1954) और अप्सरा, एशिया का पहला अनुसंधान रिएक्टर (1956)।"},
  {"id":"gk-science-tech-206","question":"The Tata Institute of Fundamental Research was founded in 1945, with the support of the Sir Dorabji Tata Trust, by:","options":["C. V. Raman","Vikram Sarabhai","Meghnad Saha","Homi J. Bhabha"],"answer":3,"explanation":"Homi Bhabha founded TIFR in Bombay; it became the cradle of India's atomic energy programme. Sarabhai founded the Physical Research Laboratory (1947).","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"टाटा मूलभूत अनुसंधान संस्थान की स्थापना 1945 में सर दोराबजी टाटा ट्रस्ट के सहयोग से किसने की?","optionsHi":["सी. वी. रमन","विक्रम साराभाई","मेघनाद साहा","होमी जे. भाभा"],"explanationHi":"होमी भाभा ने बंबई में TIFR की स्थापना की; यह भारत के परमाणु ऊर्जा कार्यक्रम का पालना बना। साराभाई ने भौतिक अनुसंधान प्रयोगशाला (1947) की स्थापना की।"},
  {"id":"gk-science-tech-207","question":"India's first uranium mine, worked by the Uranium Corporation of India since 1967, is at:","options":["Tummalapalle, Andhra Pradesh","Domiasiat, Meghalaya","Jaduguda, Jharkhand","Rawatbhata, Rajasthan"],"answer":2,"explanation":"Jaduguda in East Singhbhum was India's first uranium mine. Tummalapalle is a newer, large low-grade deposit and Domiasiat an unmined deposit in Meghalaya.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"1967 से यूरेनियम कॉरपोरेशन ऑफ़ इंडिया द्वारा संचालित भारत की पहली यूरेनियम खदान कहाँ है?","optionsHi":["तुम्मलपल्ले, आंध्र प्रदेश","डोमियासियात, मेघालय","जादूगोड़ा, झारखंड","रावतभाटा, राजस्थान"],"explanationHi":"पूर्वी सिंहभूम का जादूगोड़ा भारत की पहली यूरेनियम खदान थी। तुम्मलपल्ले एक नया, बड़ा निम्न-श्रेणी का भंडार है और डोमियासियात मेघालय में एक अखनित भंडार है।"},
  {"id":"gk-science-tech-208","question":"DNA fingerprinting in India was pioneered in the late 1980s by Lalji Singh at the:","options":["National Chemical Laboratory, Pune","Centre for Cellular and Molecular Biology, Hyderabad","National Institute of Immunology, New Delhi","Indian Institute of Science, Bengaluru"],"answer":1,"explanation":"Lalji Singh developed the technique at CCMB Hyderabad and later founded the Centre for DNA Fingerprinting and Diagnostics there; it was first used in an Indian paternity case in 1988.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"भारत में DNA फ़िंगरप्रिंटिंग की अग्रणी शुरुआत 1980 के दशक के अंत में लालजी सिंह ने किस संस्थान में की?","optionsHi":["राष्ट्रीय रासायनिक प्रयोगशाला, पुणे","कोशिकीय एवं आणविक जीव विज्ञान केंद्र, हैदराबाद","राष्ट्रीय प्रतिरक्षा विज्ञान संस्थान, नई दिल्ली","भारतीय विज्ञान संस्थान, बेंगलुरु"],"explanationHi":"लालजी सिंह ने यह तकनीक CCMB हैदराबाद में विकसित की और बाद में वहीं DNA फ़िंगरप्रिंटिंग एवं निदान केंद्र की स्थापना की; इसका पहला प्रयोग 1988 में एक भारतीय पितृत्व मामले में हुआ।"},
  {"id":"gk-science-tech-209","question":"Cervavac, approved in 2022 and developed by the Serum Institute of India with the Department of Biotechnology, is India's first indigenous vaccine against:","options":["Rotavirus","Human papillomavirus","Dengue virus","Japanese encephalitis"],"answer":1,"explanation":"Cervavac is a quadrivalent HPV vaccine to prevent cervical cancer. Rotavac, the indigenous rotavirus vaccine, came earlier from Bharat Biotech.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"2022 में स्वीकृत सर्ववैक (Cervavac), जिसे सीरम इंस्टीट्यूट ऑफ़ इंडिया ने जैव प्रौद्योगिकी विभाग के साथ विकसित किया, किसके विरुद्ध भारत का पहला स्वदेशी टीका है?","optionsHi":["रोटावायरस","ह्यूमन पैपिलोमावायरस","डेंगू वायरस","जापानी एन्सेफलाइटिस"],"explanationHi":"सर्ववैक चतुःसंयोजी HPV टीका है जो गर्भाशय-ग्रीवा कैंसर को रोकता है। स्वदेशी रोटावायरस टीका रोटावैक भारत बायोटेक से पहले आ चुका था।"},
  {"id":"gk-science-tech-210","question":"Match the COVID-19 vaccine used in India with its platform. A. Covaxin  B. Covishield  C. Corbevax  D. ZyCoV-D; 1. Protein subunit  2. Plasmid DNA  3. Inactivated whole virus  4. Chimpanzee adenovirus vector","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2"],"answer":0,"explanation":"Covaxin (Bharat Biotech) is an inactivated vaccine; Covishield is the ChAdOx1 vector vaccine; Corbevax (Biological E) is a protein subunit vaccine; ZyCoV-D (Zydus) was the world's first DNA vaccine approved for humans.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत में प्रयुक्त COVID-19 टीके का उसके प्लेटफ़ॉर्म से मिलान कीजिए। A. कोवैक्सिन  B. कोविशील्ड  C. कॉर्बेवैक्स  D. ZyCoV-D; 1. प्रोटीन सबयूनिट  2. प्लाज़्मिड DNA  3. निष्क्रिय संपूर्ण वायरस  4. चिंपैंज़ी एडेनोवायरस वाहक","optionsHi":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2"],"explanationHi":"कोवैक्सिन (भारत बायोटेक) निष्क्रिय टीका है; कोविशील्ड ChAdOx1 वाहक टीका है; कॉर्बेवैक्स (बायोलॉजिकल E) प्रोटीन सबयूनिट टीका है; ZyCoV-D (ज़ायडस) मनुष्यों के लिए स्वीकृत विश्व का पहला DNA टीका था।"},
  {"id":"gk-science-tech-211","question":"DMH-11, the genetically modified mustard hybrid cleared for environmental release by GEAC in 2022, uses the barnase–barstar gene system in order to:","options":["Make the plant resistant to sap-sucking pests such as aphids","Raise oil content and lower erucic acid in the seed","Create male sterility and then restore fertility for hybrid seed","Let the crop survive drought and salty soils in dry regions"],"answer":2,"explanation":"Barnase makes one parent line male-sterile and barstar restores fertility in the hybrid, allowing large-scale hybrid seed production; the genes come from the bacterium Bacillus amyloliquefaciens.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"2022 में GEAC द्वारा पर्यावरणीय विमोचन के लिए स्वीकृत आनुवंशिक रूप से संशोधित सरसों संकर DMH-11 बार्नेज़–बार्स्टार जीन प्रणाली का उपयोग किसलिए करता है?","optionsHi":["पौधे को एफ़िड जैसे रस चूसने वाले कीटों के प्रति प्रतिरोधी बनाने के लिए","बीज में तेल की मात्रा बढ़ाने और इरुसिक अम्ल घटाने के लिए","नर-बंध्यता उत्पन्न करने और फिर संकर बीज के लिए उर्वरता बहाल करने के लिए","शुष्क क्षेत्रों में फसल को सूखे और लवणीय मृदा में जीवित रखने के लिए"],"explanationHi":"बार्नेज़ एक जनक वंश को नर-बंध्य बनाता है और बार्स्टार संकर में उर्वरता बहाल करता है, जिससे बड़े पैमाने पर संकर बीज उत्पादन संभव होता है; ये जीन जीवाणु बैसिलस एमाइलोलिक्वेफ़ेशियंस से आते हैं।"},
  {"id":"gk-science-tech-212","question":"India set up a separate Department of Biotechnology, under the Ministry of Science and Technology, in:","options":["1972","1991","2001","1986"],"answer":3,"explanation":"The DBT was created in 1986 out of the National Biotechnology Board formed in 1982.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"भारत ने विज्ञान और प्रौद्योगिकी मंत्रालय के अंतर्गत पृथक जैव प्रौद्योगिकी विभाग की स्थापना किस वर्ष की?","optionsHi":["1972","1991","2001","1986"],"explanationHi":"DBT का गठन 1986 में 1982 में बने राष्ट्रीय जैव प्रौद्योगिकी बोर्ड से हुआ।"},
  {"id":"gk-science-tech-213","question":"The Genome India Project, launched by the Department of Biotechnology in 2020, aims to:","options":["Sequence the genomes of about 10,000 Indians to map the country's genetic variation","Create genetically modified versions of major Indian food crops for drought tolerance","Sequence the genome of every new-born child in India to screen for inherited disease","Build a national DNA database of convicted criminals for use by the police forces"],"answer":0,"explanation":"The project sequenced whole genomes of about 10,000 people from many communities to build a reference database for research and medicine.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जैव प्रौद्योगिकी विभाग द्वारा 2020 में शुरू की गई जीनोम इंडिया परियोजना का उद्देश्य है:","optionsHi":["देश की आनुवंशिक विविधता का मानचित्रण करने के लिए लगभग 10,000 भारतीयों के जीनोम का अनुक्रमण करना","सूखा सहनशीलता के लिए प्रमुख भारतीय खाद्य फसलों के आनुवंशिक रूप से संशोधित संस्करण बनाना","आनुवंशिक रोगों की जाँच के लिए भारत में प्रत्येक नवजात शिशु के जीनोम का अनुक्रमण करना","पुलिस बलों के उपयोग के लिए दोषसिद्ध अपराधियों का राष्ट्रीय DNA डेटाबेस बनाना"],"explanationHi":"इस परियोजना ने अनुसंधान और चिकित्सा के लिए संदर्भ डेटाबेस बनाने हेतु अनेक समुदायों के लगभग 10,000 लोगों के संपूर्ण जीनोम का अनुक्रमण किया।"},
  {"id":"gk-science-tech-214","question":"The polymerase chain reaction (PCR), the basis of RT-PCR tests, is a technique to:","options":["Separate DNA fragments by size in a gel","Make millions of copies of a chosen DNA segment","Cut DNA at specific recognition sequences","Join DNA fragments into a bacterial plasmid"],"answer":1,"explanation":"PCR, devised by Kary Mullis in 1983, amplifies a target DNA sequence through repeated heating and cooling cycles. Gel electrophoresis separates fragments; restriction enzymes cut and ligase joins DNA.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"RT-PCR परीक्षणों का आधार पॉलीमरेज़ शृंखला अभिक्रिया (PCR) किस हेतु तकनीक है?","optionsHi":["जेल में DNA खंडों को आकार के अनुसार अलग करना","चुने हुए DNA खंड की लाखों प्रतियाँ बनाना","विशिष्ट पहचान अनुक्रमों पर DNA को काटना","DNA खंडों को जीवाणु प्लाज़्मिड में जोड़ना"],"explanationHi":"PCR, जिसे 1983 में कैरी मुलिस ने तैयार किया, बार-बार गर्म और ठंडा करने के चक्रों से लक्षित DNA अनुक्रम का प्रवर्धन करती है। जेल वैद्युतकण-संचलन खंडों को अलग करता है; प्रतिबंधन एंज़ाइम DNA को काटते हैं और लाइगेज़ जोड़ता है।"},
  {"id":"gk-science-tech-215","question":"Assertion (A): RT-PCR tests can detect RNA viruses such as SARS-CoV-2. Reason (R): The enzyme reverse transcriptase first converts the viral RNA into DNA, which PCR then amplifies.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"PCR copies only DNA, so the RNA genome must first be reverse-transcribed into complementary DNA; that is why the test is called reverse transcription PCR.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): RT-PCR परीक्षण SARS-CoV-2 जैसे RNA वायरसों का पता लगा सकते हैं। कारण (R): एंज़ाइम रिवर्स ट्रांसक्रिप्टेज़ पहले वायरल RNA को DNA में बदलता है, जिसका PCR फिर प्रवर्धन करती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"PCR केवल DNA की प्रतियाँ बनाती है, इसलिए RNA जीनोम का पहले पूरक DNA में प्रतिलेखन किया जाना चाहिए; इसीलिए परीक्षण को रिवर्स ट्रांसक्रिप्शन PCR कहा जाता है।"},
  {"id":"gk-science-tech-216","question":"The 2020 Nobel Prize in Chemistry for developing the CRISPR-Cas9 genome-editing method was awarded to:","options":["Jennifer Doudna and Feng Zhang","Emmanuelle Charpentier and Jennifer Doudna","Emmanuelle Charpentier and George Church","Feng Zhang and George Church"],"answer":1,"explanation":"Charpentier and Doudna shared the prize, the first science Nobel won by two women alone; Zhang and Church also did major CRISPR work but were not awarded.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"CRISPR-Cas9 जीनोम-संपादन विधि के विकास के लिए 2020 का रसायन विज्ञान का नोबेल पुरस्कार किन्हें दिया गया?","optionsHi":["जेनिफ़र डूडना और फ़ेंग झांग","इमैनुएल शार्पेंटियर और जेनिफ़र डूडना","इमैनुएल शार्पेंटियर और जॉर्ज चर्च","फ़ेंग झांग और जॉर्ज चर्च"],"explanationHi":"शार्पेंटियर और डूडना ने यह पुरस्कार साझा किया, जो केवल दो महिलाओं द्वारा जीता गया पहला विज्ञान नोबेल था; झांग और चर्च ने भी CRISPR पर महत्त्वपूर्ण कार्य किया, पर उन्हें पुरस्कार नहीं मिला।"},
  {"id":"gk-science-tech-217","question":"Which of these statements about Nobel Prizes in science linked to India are correct? I. C. V. Raman won the 1930 Physics prize for his work on the scattering of light. II. Har Gobind Khorana shared the 1968 Medicine prize for work on interpreting the genetic code. III. S. Chandrasekhar shared the 1983 Physics prize for work on the structure and evolution of stars. IV. Venkatraman Ramakrishnan shared the 2009 Chemistry prize for studies of the ribosome.","options":["I and III only","I, II and III only","I, III and IV only","I, II, III and IV"],"answer":3,"explanation":"All four are correct; Raman remains the only one who did his prize-winning work in India.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"भारत से जुड़े विज्ञान के नोबेल पुरस्कारों के बारे में इनमें से कौन-से कथन सही हैं? I. सी. वी. रमन ने प्रकाश के प्रकीर्णन पर कार्य के लिए 1930 का भौतिकी पुरस्कार जीता। II. हरगोबिंद खुराना ने आनुवंशिक कूट की व्याख्या पर कार्य के लिए 1968 का चिकित्सा पुरस्कार साझा किया। III. एस. चंद्रशेखर ने तारों की संरचना और विकास पर कार्य के लिए 1983 का भौतिकी पुरस्कार साझा किया। IV. वेंकटरमन रामकृष्णन ने राइबोसोम के अध्ययन के लिए 2009 का रसायन विज्ञान पुरस्कार साझा किया।","optionsHi":["केवल I और III","केवल I, II और III","केवल I, III और IV","I, II, III और IV"],"explanationHi":"चारों कथन सही हैं; रमन एकमात्र ऐसे हैं जिन्होंने अपना पुरस्कार-विजेता कार्य भारत में किया।"},
  {"id":"gk-science-tech-218","question":"National Science Day is celebrated on 28 February because on that day in 1928:","options":["C. V. Raman announced the discovery of the Raman effect","Jagadish Chandra Bose demonstrated the crescograph","The Indian Institute of Science was opened in Bangalore","Satyendra Nath Bose sent his paper on photon statistics to Einstein"],"answer":0,"explanation":"Raman announced the effect on 28 February 1928; it won him the 1930 Physics Nobel. IISc was founded in 1909.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"राष्ट्रीय विज्ञान दिवस 28 फरवरी को इसलिए मनाया जाता है क्योंकि इसी दिन 1928 में:","optionsHi":["सी. वी. रमन ने रमन प्रभाव की खोज की घोषणा की","जगदीश चंद्र बोस ने क्रेस्कोग्राफ़ का प्रदर्शन किया","बेंगलुरु में भारतीय विज्ञान संस्थान का उद्घाटन हुआ","सत्येंद्र नाथ बोस ने फोटॉन सांख्यिकी पर अपना शोधपत्र आइंस्टीन को भेजा"],"explanationHi":"रमन ने 28 फरवरी 1928 को इस प्रभाव की घोषणा की; इसके लिए उन्हें 1930 का भौतिकी नोबेल मिला। IISc की स्थापना 1909 में हुई थी।"},
  {"id":"gk-science-tech-219","question":"Particles called 'bosons' are named after:","options":["Jagadish Chandra Bose","Ananda Mohan Bose","Debendra Mohan Bose","Satyendra Nath Bose"],"answer":3,"explanation":"S. N. Bose's 1924 work on photon statistics, extended by Einstein, gave Bose–Einstein statistics; particles obeying it, such as photons and the Higgs, are bosons.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"\"बोसॉन\" नामक कणों का नाम किसके नाम पर रखा गया है?","optionsHi":["जगदीश चंद्र बोस","आनंद मोहन बोस","देवेंद्र मोहन बोस","सत्येंद्र नाथ बोस"],"explanationHi":"S. N. बोस के 1924 के फोटॉन सांख्यिकी पर कार्य को आइंस्टीन ने आगे बढ़ाया, जिससे बोस–आइंस्टीन सांख्यिकी बनी; इसका पालन करने वाले कण, जैसे फोटॉन और हिग्स, बोसॉन कहलाते हैं।"},
  {"id":"gk-science-tech-220","question":"The thermal ionisation equation, which helped explain the spectra and temperatures of stars, was given in 1920 by:","options":["Meghnad Saha","S. Chandrasekhar","C. V. Raman","Satyendra Nath Bose"],"answer":0,"explanation":"The Saha ionisation equation links a gas's ionisation to its temperature and pressure, letting astronomers classify stars by temperature.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"तारों के स्पेक्ट्रम और तापमान को समझाने में सहायक ऊष्मीय आयनन समीकरण 1920 में किसने दिया?","optionsHi":["मेघनाद साहा","एस. चंद्रशेखर","सी. वी. रमन","सत्येंद्र नाथ बोस"],"explanationHi":"साहा आयनन समीकरण किसी गैस के आयनन को उसके तापमान और दाब से जोड़ता है, जिससे खगोलविद तारों को तापमान के अनुसार वर्गीकृत कर पाते हैं।"},
  {"id":"gk-science-tech-221","question":"The Chandrasekhar limit is the maximum mass of a stable:","options":["Neutron star, about 1.4 times the Sun's mass","White dwarf, about 3 times the Sun's mass","White dwarf, about 1.4 times the Sun's mass","Black hole, about 1.4 times the Sun's mass"],"answer":2,"explanation":"Above about 1.4 solar masses electron degeneracy pressure cannot support a white dwarf, so it collapses further. Black holes have no upper mass limit of this kind.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"चंद्रशेखर सीमा किसके स्थायी रहने का अधिकतम द्रव्यमान है?","optionsHi":["न्यूट्रॉन तारा, सूर्य के द्रव्यमान का लगभग 1.4 गुना","श्वेत वामन, सूर्य के द्रव्यमान का लगभग 3 गुना","श्वेत वामन, सूर्य के द्रव्यमान का लगभग 1.4 गुना","ब्लैक होल, सूर्य के द्रव्यमान का लगभग 1.4 गुना"],"explanationHi":"लगभग 1.4 सौर द्रव्यमान से ऊपर इलेक्ट्रॉन अपभ्रष्ट दाब श्वेत वामन को सहारा नहीं दे पाता, इसलिए वह और अधिक सिकुड़ जाता है। ब्लैक होल के लिए इस प्रकार की कोई ऊपरी द्रव्यमान सीमा नहीं होती।"},
  {"id":"gk-science-tech-222","question":"Match the astronomical facility with its location. A. Giant Metrewave Radio Telescope  B. 3.6 m Devasthal Optical Telescope  C. Indian Astronomical Observatory  D. Mount Abu Infrared Observatory; 1. Hanle, Ladakh  2. Narayangaon, near Pune  3. Rajasthan, run by PRL  4. Nainital district, run by ARIES","options":["A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1"],"answer":0,"explanation":"GMRT is near Narayangaon (Pune district), Devasthal near Nainital (ARIES), the Indian Astronomical Observatory at Hanle (IIA) and the Mount Abu observatory is run by the Physical Research Laboratory.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"खगोलीय सुविधा का उसके स्थान से मिलान कीजिए। A. विशाल मीटरतरंग रेडियो दूरबीन  B. 3.6 m देवस्थल प्रकाशीय दूरबीन  C. भारतीय खगोलीय वेधशाला  D. माउंट आबू अवरक्त वेधशाला; 1. हानले, लद्दाख  2. नारायणगाँव, पुणे के निकट  3. राजस्थान, PRL द्वारा संचालित  4. नैनीताल ज़िला, ARIES द्वारा संचालित","optionsHi":["A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1"],"explanationHi":"GMRT नारायणगाँव (पुणे ज़िला) के निकट है, देवस्थल नैनीताल के निकट (ARIES), भारतीय खगोलीय वेधशाला हानले में (IIA) है और माउंट आबू वेधशाला का संचालन भौतिक अनुसंधान प्रयोगशाला करती है।"},
  {"id":"gk-science-tech-223","question":"LIGO-India, the gravitational-wave observatory approved by the Union Cabinet in 2023, is to be built in:","options":["Theni district, Tamil Nadu","Hanle, Ladakh","Chitradurga district, Karnataka","Hingoli district, Maharashtra"],"answer":3,"explanation":"The site is in Hingoli district, Maharashtra. Theni is the proposed site of the India-based Neutrino Observatory and Hanle hosts optical telescopes.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2023 में केंद्रीय मंत्रिमंडल द्वारा स्वीकृत गुरुत्वीय तरंग वेधशाला LIGO-इंडिया कहाँ बनाई जानी है?","optionsHi":["थेनी ज़िला, तमिलनाडु","हानले, लद्दाख","चित्रदुर्ग ज़िला, कर्नाटक","हिंगोली ज़िला, महाराष्ट्र"],"explanationHi":"स्थल महाराष्ट्र के हिंगोली ज़िले में है। थेनी भारत-आधारित न्यूट्रिनो वेधशाला का प्रस्तावित स्थल है और हानले में प्रकाशीय दूरबीनें हैं।"},
  {"id":"gk-science-tech-224","question":"India is a full member of ITER, the international experimental fusion reactor being built at:","options":["Geneva, Switzerland","Cadarache, France","Garching, Germany","Culham, United Kingdom"],"answer":1,"explanation":"ITER, a tokamak meant to show fusion's feasibility, is at Cadarache in southern France; India joined in 2005. Geneva hosts CERN, the particle physics laboratory.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत ITER, अंतरराष्ट्रीय प्रायोगिक संलयन रिएक्टर, का पूर्ण सदस्य है, जो कहाँ बनाया जा रहा है?","optionsHi":["जिनेवा, स्विट्ज़रलैंड","कैडाराश, फ्रांस","गार्चिंग, जर्मनी","कल्हम, यूनाइटेड किंगडम"],"explanationHi":"ITER, संलयन की व्यावहारिकता सिद्ध करने के लिए बनाया जा रहा टोकामक, दक्षिणी फ्रांस के कैडाराश में है; भारत 2005 में इससे जुड़ा। जिनेवा में कण भौतिकी की प्रयोगशाला CERN है।"},
  {"id":"gk-science-tech-225","question":"Arrange India's Antarctic research bases in the order they were set up: 1. Maitri  2. Bharati  3. Dakshin Gangotri","options":["1-3-2","3-2-1","3-1-2","1-2-3"],"answer":2,"explanation":"Dakshin Gangotri (1983–84) was buried by ice and decommissioned; Maitri followed in 1989 and Bharati in 2012.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"भारत के अंटार्कटिक अनुसंधान केंद्रों को उनकी स्थापना के क्रम में व्यवस्थित कीजिए: 1. मैत्री  2. भारती  3. दक्षिण गंगोत्री","optionsHi":["1-3-2","3-2-1","3-1-2","1-2-3"],"explanationHi":"दक्षिण गंगोत्री (1983–84) बर्फ़ में दब गया और सेवामुक्त कर दिया गया; मैत्री 1989 में और भारती 2012 में आए।"},
  {"id":"gk-science-tech-226","question":"In the seven-layer OSI model, at which layers do TCP and IP respectively operate?","options":["Network layer and data link layer","Transport layer and network layer","Session layer and transport layer","Transport layer and data link layer"],"answer":1,"explanation":"TCP provides reliable end-to-end delivery at the transport layer (layer 4); IP handles addressing and routing at the network layer (layer 3).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"सात-परत वाले OSI मॉडल में TCP और IP क्रमशः किन परतों पर कार्य करते हैं?","optionsHi":["नेटवर्क परत और डेटा लिंक परत","परिवहन परत और नेटवर्क परत","सत्र परत और परिवहन परत","परिवहन परत और डेटा लिंक परत"],"explanationHi":"TCP परिवहन परत (परत 4) पर विश्वसनीय अंत-से-अंत वितरण प्रदान करता है; IP नेटवर्क परत (परत 3) पर पता-निर्धारण और मार्ग-निर्धारण संभालता है।"},
  {"id":"gk-science-tech-227","question":"By default, secure web traffic using HTTPS runs over TCP port:","options":["80","8080","25","443"],"answer":3,"explanation":"HTTPS uses port 443; plain HTTP uses 80, FTP control uses 21 and SMTP mail uses 25.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO","questionHi":"डिफ़ॉल्ट रूप से HTTPS का उपयोग करने वाला सुरक्षित वेब ट्रैफ़िक किस TCP पोर्ट पर चलता है?","optionsHi":["80","8080","25","443"],"explanationHi":"HTTPS पोर्ट 443 का उपयोग करता है; सामान्य HTTP 80 का, FTP नियंत्रण 21 का और SMTP मेल 25 का उपयोग करता है।"},
  {"id":"gk-science-tech-228","question":"An IPv4 address is 32 bits long. Roughly how many distinct addresses can the IPv4 scheme provide?","options":["About 6.5 × 10^4 (2^16)","About 4.2 × 10^6 (2^22)","About 4.3 × 10^9 (2^32)","About 1.8 × 10^19 (2^64)"],"answer":2,"explanation":"2^32 = 4,294,967,296, about 4.3 × 10^9 (4.3 billion), too few for today's devices, which is why 128-bit IPv6 was introduced.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO","questionHi":"IPv4 पता 32 बिट लंबा होता है। IPv4 योजना लगभग कितने भिन्न पते उपलब्ध करा सकती है?","optionsHi":["लगभग 6.5 × 10^4 (2^16)","लगभग 4.2 × 10^6 (2^22)","लगभग 4.3 × 10^9 (2^32)","लगभग 1.8 × 10^19 (2^64)"],"explanationHi":"2^32 = 4,294,967,296, यानी लगभग 4.3 × 10^9 (लगभग 430 करोड़), जो आज के उपकरणों के लिए बहुत कम है; इसीलिए 128-बिट IPv6 लाया गया।"},
  {"id":"gk-science-tech-229","question":"Unlike a computer virus, a computer worm:","options":["Disguises itself as useful software to trick the user into installing it","Encrypts the victim's files and then demands a ransom to unlock them","Spreads across networks on its own without attaching to a host file","Can spread only through removable media such as USB flash drives"],"answer":2,"explanation":"A worm self-replicates over networks without needing a host program or user action; a virus attaches to files. Disguise describes a Trojan and file encryption describes ransomware.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO","questionHi":"कंप्यूटर वायरस के विपरीत, कंप्यूटर वर्म:","optionsHi":["उपयोगी सॉफ़्टवेयर का वेश धरकर उपयोगकर्ता को उसे इंस्टॉल करने के लिए बरगलाता है","पीड़ित की फ़ाइलें एन्क्रिप्ट करके उन्हें खोलने के लिए फिरौती माँगता है","किसी होस्ट फ़ाइल से जुड़े बिना अपने आप नेटवर्क पर फैलता है","केवल USB फ़्लैश ड्राइव जैसे हटाए जा सकने वाले मीडिया के माध्यम से ही फैल सकता है"],"explanationHi":"वर्म बिना होस्ट प्रोग्राम या उपयोगकर्ता की क्रिया के नेटवर्क पर अपनी प्रतियाँ बनाकर फैलता है; वायरस फ़ाइलों से जुड़ता है। वेश धरना ट्रोजन का और फ़ाइल एन्क्रिप्शन रैनसमवेयर का वर्णन है।"},
  {"id":"gk-science-tech-230","question":"An attacker types database commands into a website's login box so that the site's database reveals or changes data. This attack is called:","options":["Cross-site scripting","SQL injection","Session hijacking","Phishing"],"answer":1,"explanation":"SQL injection exploits input that is passed unchecked into database queries. Cross-site scripting injects scripts that run in other users' browsers.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO","questionHi":"कोई हमलावर किसी वेबसाइट के लॉगिन बॉक्स में डेटाबेस कमांड लिखता है ताकि साइट का डेटाबेस डेटा उजागर करे या बदल दे। इस हमले को क्या कहते हैं?","optionsHi":["क्रॉस-साइट स्क्रिप्टिंग","SQL इंजेक्शन","सेशन हाइजैकिंग","फ़िशिंग"],"explanationHi":"SQL इंजेक्शन उस इनपुट का फ़ायदा उठाता है जो बिना जाँच के डेटाबेस क्वेरी में पहुँच जाता है। क्रॉस-साइट स्क्रिप्टिंग ऐसी स्क्रिप्टें डालती है जो अन्य उपयोगकर्ताओं के ब्राउज़र में चलती हैं।"},
  {"id":"gk-science-tech-231","question":"A distributed denial-of-service (DDoS) attack mainly aims to:","options":["Make a service unavailable by flooding it with traffic from many sources","Steal users' passwords by sending them convincing fake login pages by e-mail","Secretly record keystrokes on infected computers across a network","Change the content of a website to display the attacker's message"],"answer":0,"explanation":"DDoS uses many machines, often a botnet, to overwhelm a server or network so genuine users cannot reach it. Fake login pages are phishing and altering a site is defacement.","difficulty":"moderate","source":"SSC CGL · IBPS SO","questionHi":"वितरित सेवा-अवरोध (DDoS) हमले का मुख्य उद्देश्य क्या होता है?","optionsHi":["अनेक स्रोतों से ट्रैफ़िक की बाढ़ लाकर किसी सेवा को अनुपलब्ध बना देना","उपयोगकर्ताओं को ई-मेल से विश्वसनीय दिखने वाले नकली लॉगिन पेज भेजकर उनके पासवर्ड चुराना","नेटवर्क के संक्रमित कंप्यूटरों पर चुपके से की-स्ट्रोक्स रिकॉर्ड करना","वेबसाइट की सामग्री बदलकर हमलावर का संदेश प्रदर्शित करना"],"explanationHi":"DDoS में अनेक मशीनों, प्रायः बॉटनेट, का उपयोग करके सर्वर या नेटवर्क को इतना लाद दिया जाता है कि असली उपयोगकर्ता उस तक पहुँच न सकें। नकली लॉगिन पेज फ़िशिंग हैं और साइट को बदलना डिफ़ेसमेंट कहलाता है।"},
  {"id":"gk-science-tech-232","question":"In public-key (asymmetric) encryption, if A wants to send B a message that only B can read, A should encrypt it with:","options":["A's own private key","A's own public key","B's private key","B's public key"],"answer":3,"explanation":"Anything encrypted with B's public key can be decrypted only with B's private key, which only B holds. A's private key is used for signing, not secrecy, and A never has B's private key.","difficulty":"very-hard","source":"UPSC Prelims · IBPS SO","questionHi":"सार्वजनिक-कुंजी (असममित) एन्क्रिप्शन में, यदि A, B को ऐसा संदेश भेजना चाहता है जिसे केवल B पढ़ सके, तो A को उसे किससे एन्क्रिप्ट करना चाहिए?","optionsHi":["A की अपनी निजी कुंजी से","A की अपनी सार्वजनिक कुंजी से","B की निजी कुंजी से","B की सार्वजनिक कुंजी से"],"explanationHi":"B की सार्वजनिक कुंजी से एन्क्रिप्ट की गई कोई भी चीज़ केवल B की निजी कुंजी से डिक्रिप्ट हो सकती है, जो केवल B के पास होती है। A की निजी कुंजी हस्ताक्षर के लिए प्रयुक्त होती है, गोपनीयता के लिए नहीं, और A के पास B की निजी कुंजी कभी नहीं होती।"},
  {"id":"gk-science-tech-233","question":"Assertion (A): A digital signature lets the receiver check who sent a message and that it was not altered. Reason (R): The sender signs with their private key, and anyone can verify the signature with the matching public key.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Only the holder of the private key can produce a signature that the public key verifies, and any change to the message breaks verification, giving authenticity and integrity.","difficulty":"hard","source":"UPSC Prelims · IBPS SO","questionHi":"अभिकथन (A): डिजिटल हस्ताक्षर प्राप्तकर्ता को यह जाँचने देता है कि संदेश किसने भेजा और उसमें कोई बदलाव नहीं हुआ। कारण (R): भेजने वाला अपनी निजी कुंजी से हस्ताक्षर करता है, और कोई भी उस हस्ताक्षर को संबंधित सार्वजनिक कुंजी से सत्यापित कर सकता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"केवल निजी कुंजी का धारक ही ऐसा हस्ताक्षर बना सकता है जिसे सार्वजनिक कुंजी सत्यापित करे, और संदेश में कोई भी बदलाव सत्यापन को तोड़ देता है, जिससे प्रामाणिकता और अखंडता मिलती है।"},
  {"id":"gk-science-tech-234","question":"In Shreya Singhal v. Union of India (2015), the Supreme Court struck down which provision of the Information Technology Act, 2000 as unconstitutional?","options":["Section 69A, on blocking public access to websites","Section 79, on safe harbour for intermediaries","Section 43, on penalties for damage to computers","Section 66A, on sending offensive messages online"],"answer":3,"explanation":"Section 66A was struck down for vagueness, violating free speech. The Court upheld Section 69A blocking powers and read down Section 79.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"श्रेया सिंघल बनाम भारत संघ (2015) में सर्वोच्च न्यायालय ने सूचना प्रौद्योगिकी अधिनियम, 2000 के किस प्रावधान को असंवैधानिक ठहराकर रद्द कर दिया?","optionsHi":["धारा 69A, वेबसाइटों तक सार्वजनिक पहुँच अवरुद्ध करने पर","धारा 79, मध्यस्थों के लिए सेफ़ हार्बर पर","धारा 43, कंप्यूटरों को क्षति पहुँचाने पर दंड पर","धारा 66A, ऑनलाइन आपत्तिजनक संदेश भेजने पर"],"explanationHi":"धारा 66A को अस्पष्टता के कारण और अभिव्यक्ति की स्वतंत्रता के उल्लंघन के लिए रद्द किया गया। न्यायालय ने धारा 69A की अवरोधन शक्तियों को बरकरार रखा और धारा 79 का सीमित अर्थ लगाया।"},
  {"id":"gk-science-tech-235","question":"Under the Digital Personal Data Protection Act, 2023, complaints of personal data breaches are handled, and penalties imposed, by the:","options":["Data Protection Authority of India","Data Protection Board of India","Indian Computer Emergency Response Team","Telecom Regulatory Authority of India"],"answer":1,"explanation":"The 2023 Act creates the Data Protection Board of India. A 'Data Protection Authority' was proposed in the withdrawn 2019 Bill; CERT-In handles cyber incidents.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"डिजिटल व्यक्तिगत डेटा संरक्षण अधिनियम, 2023 के अंतर्गत व्यक्तिगत डेटा उल्लंघन की शिकायतों का निपटारा और दंड का आरोपण कौन करता है?","optionsHi":["भारतीय डेटा संरक्षण प्राधिकरण","भारतीय डेटा संरक्षण बोर्ड","भारतीय कंप्यूटर आपातकालीन प्रतिक्रिया दल","भारतीय दूरसंचार विनियामक प्राधिकरण"],"explanationHi":"2023 का अधिनियम भारतीय डेटा संरक्षण बोर्ड का गठन करता है। \"डेटा संरक्षण प्राधिकरण\" का प्रस्ताव वापस लिए गए 2019 के विधेयक में था; CERT-In साइबर घटनाओं को देखता है।"},
  {"id":"gk-science-tech-236","question":"The Open Network for Digital Commerce (ONDC), launched in 2022, is:","options":["A government-run online marketplace used by ministries for public procurement","A payment system that settles card payments for small shops","An open network that lets different e-commerce apps trade with each other","A fibre broadband network to connect every gram panchayat"],"answer":2,"explanation":"ONDC lets a buyer on one app buy from a seller listed on another, built on open protocols like UPI. Public procurement is GeM's role and village broadband is BharatNet.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"2022 में शुरू किया गया ओपन नेटवर्क फ़ॉर डिजिटल कॉमर्स (ONDC) क्या है?","optionsHi":["सार्वजनिक खरीद के लिए मंत्रालयों द्वारा प्रयुक्त सरकार-संचालित ऑनलाइन बाज़ार","छोटी दुकानों के कार्ड भुगतानों का निपटान करने वाली भुगतान प्रणाली","खुला नेटवर्क जो विभिन्न ई-कॉमर्स ऐप्स को आपस में व्यापार करने देता है","प्रत्येक ग्राम पंचायत को जोड़ने वाला फ़ाइबर ब्रॉडबैंड नेटवर्क"],"explanationHi":"ONDC एक ऐप पर मौजूद खरीदार को दूसरे ऐप पर सूचीबद्ध विक्रेता से खरीदने देता है, जो UPI जैसे खुले प्रोटोकॉल पर बना है। सार्वजनिक खरीद GeM की भूमिका है और ग्रामीण ब्रॉडबैंड भारतनेट है।"},
  {"id":"gk-science-tech-237","question":"The National Supercomputing Mission, launched in 2015, is implemented by C-DAC together with:","options":["IIT Bombay","ISRO, Bengaluru","IISc Bengaluru","DRDO, New Delhi"],"answer":2,"explanation":"C-DAC, Pune, and the Indian Institute of Science, Bengaluru, implement the mission for the Ministry of Electronics and IT and the Department of Science and Technology.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2015 में शुरू किया गया राष्ट्रीय सुपरकंप्यूटिंग मिशन C-DAC के साथ किसके द्वारा क्रियान्वित किया जाता है?","optionsHi":["IIT बॉम्बे","ISRO, बेंगलुरु","IISc बेंगलुरु","DRDO, नई दिल्ली"],"explanationHi":"C-DAC, पुणे, और भारतीय विज्ञान संस्थान, बेंगलुरु, इलेक्ट्रॉनिकी और सूचना प्रौद्योगिकी मंत्रालय तथा विज्ञान और प्रौद्योगिकी विभाग के लिए इस मिशन को क्रियान्वित करते हैं।"},
  {"id":"gk-science-tech-238","question":"Pratyush, a high-performance computing system installed in 2018 at the Indian Institute of Tropical Meteorology, Pune, is used mainly for:","options":["Weather and climate forecasting","Simulation of nuclear reactor cores","Analysis of genome sequences","Cryptanalysis for defence agencies"],"answer":0,"explanation":"Pratyush (IITM Pune) and Mihir (NCMRWF, Noida) run India's weather and climate models under the Ministry of Earth Sciences.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"2018 में भारतीय उष्णदेशीय मौसम विज्ञान संस्थान, पुणे में स्थापित उच्च-निष्पादन कंप्यूटिंग प्रणाली प्रत्यूष का उपयोग मुख्यतः किसके लिए होता है?","optionsHi":["मौसम और जलवायु पूर्वानुमान","परमाणु रिएक्टर कोरों का अनुकरण","जीनोम अनुक्रमों का विश्लेषण","रक्षा एजेंसियों के लिए क्रिप्टविश्लेषण"],"explanationHi":"प्रत्यूष (IITM पुणे) और मिहिर (NCMRWF, नोएडा) पृथ्वी विज्ञान मंत्रालय के अंतर्गत भारत के मौसम और जलवायु मॉडल चलाते हैं।"},
  {"id":"gk-science-tech-239","question":"Moore's law, as revised by Gordon Moore in 1975, states that:","options":["Processor clock speeds double roughly every twelve months","The cost of an equivalent computer halves about every ten years","Storage capacity on a disk grows in a straight line with time","Transistor counts on a chip double about every two years"],"answer":3,"explanation":"Moore observed that transistor counts on integrated circuits double roughly every two years; clock speeds stopped scaling like this in the mid-2000s.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO","questionHi":"गॉर्डन मूर द्वारा 1975 में संशोधित मूर का नियम क्या कहता है?","optionsHi":["प्रोसेसर की क्लॉक गति लगभग हर बारह महीने में दोगुनी हो जाती है","समतुल्य कंप्यूटर की लागत लगभग हर दस वर्ष में आधी हो जाती है","डिस्क की भंडारण क्षमता समय के साथ सीधी रेखा में बढ़ती है","चिप पर ट्रांज़िस्टरों की संख्या लगभग हर दो वर्ष में दोगुनी हो जाती है"],"explanationHi":"मूर ने देखा कि एकीकृत परिपथों पर ट्रांज़िस्टरों की संख्या लगभग हर दो वर्ष में दोगुनी होती है; क्लॉक गति ने 2000 के दशक के मध्य में इस तरह बढ़ना बंद कर दिया।"},
  {"id":"gk-science-tech-240","question":"In 2023 the Union Cabinet approved Micron Technology's semiconductor assembly, testing, marking and packaging (ATMP) plant at:","options":["Dholera, Gujarat","Hosur, Tamil Nadu","Noida, Uttar Pradesh","Sanand, Gujarat"],"answer":3,"explanation":"Micron's ATMP unit is at Sanand. Dholera was later chosen for the Tata–PSMC chip fabrication plant approved in 2024.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2023 में केंद्रीय मंत्रिमंडल ने माइक्रोन टेक्नोलॉजी के अर्धचालक असेंबली, परीक्षण, मार्किंग और पैकेजिंग (ATMP) संयंत्र को कहाँ स्वीकृति दी?","optionsHi":["धोलेरा, गुजरात","होसूर, तमिलनाडु","नोएडा, उत्तर प्रदेश","साणंद, गुजरात"],"explanationHi":"माइक्रोन की ATMP इकाई साणंद में है। धोलेरा को बाद में 2024 में स्वीकृत टाटा–PSMC चिप निर्माण संयंत्र के लिए चुना गया।"},
  {"id":"gk-science-tech-241","question":"Wi-Fi wireless local area networks are based on which family of IEEE standards?","options":["IEEE 802.3","IEEE 802.15","IEEE 802.16","IEEE 802.11"],"answer":3,"explanation":"Wi-Fi follows IEEE 802.11. Wired Ethernet is 802.3, 802.15 covers personal area networks such as Bluetooth and 802.16 is WiMAX.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO","questionHi":"वाई-फ़ाई वायरलेस लोकल एरिया नेटवर्क IEEE मानकों के किस परिवार पर आधारित हैं?","optionsHi":["IEEE 802.3","IEEE 802.15","IEEE 802.16","IEEE 802.11"],"explanationHi":"वाई-फ़ाई IEEE 802.11 का पालन करता है। वायर्ड ईथरनेट 802.3 है, 802.15 ब्लूटूथ जैसे व्यक्तिगत क्षेत्र नेटवर्क को कवर करता है और 802.16 वाईमैक्स है।"},
  {"id":"gk-science-tech-242","question":"A kibibyte (KiB) is exactly:","options":["1,000 bytes","1,024 bytes","1,000 bits","1,024 bits"],"answer":1,"explanation":"Binary prefixes use powers of 2: 1 KiB = 2^10 = 1,024 bytes, while the SI kilobyte (kB) is 1,000 bytes.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO","questionHi":"एक किबिबाइट (KiB) ठीक कितने के बराबर होता है?","optionsHi":["1,000 बाइट","1,024 बाइट","1,000 बिट","1,024 बिट"],"explanationHi":"बाइनरी उपसर्ग 2 की घातों का उपयोग करते हैं: 1 KiB = 2^10 = 1,024 बाइट, जबकि SI किलोबाइट (kB) 1,000 बाइट का होता है।"},
  {"id":"gk-science-tech-243","question":"In machine learning, 'supervised learning' means training a model on:","options":["Unlabelled data, so that it finds hidden groupings by itself","Rewards and penalties received from an environment it acts in","Examples labelled with the correct outputs it should predict","Data generated entirely by another trained model"],"answer":2,"explanation":"Supervised learning maps inputs to known labels, as in spam filters trained on marked e-mails. Finding structure in unlabelled data is unsupervised learning; rewards define reinforcement learning.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO","questionHi":"मशीन लर्निंग में \"पर्यवेक्षित अधिगम (सुपरवाइज़्ड लर्निंग)\" का अर्थ है किसी मॉडल को किस पर प्रशिक्षित करना?","optionsHi":["बिना लेबल वाले डेटा पर, ताकि वह छिपे हुए समूह स्वयं खोज ले","जिस परिवेश में वह कार्य करता है उससे मिले पुरस्कार और दंड पर","सही आउटपुट के लेबल वाले उदाहरणों पर, जिनका उसे पूर्वानुमान लगाना है","पूरी तरह किसी अन्य प्रशिक्षित मॉडल द्वारा बनाए गए डेटा पर"],"explanationHi":"पर्यवेक्षित अधिगम इनपुट को ज्ञात लेबलों से जोड़ता है, जैसे चिह्नित ई-मेलों पर प्रशिक्षित स्पैम फ़िल्टर। बिना लेबल वाले डेटा में संरचना खोजना अपर्यवेक्षित अधिगम है; पुरस्कार से प्रबलन अधिगम (रीइन्फ़ोर्समेंट लर्निंग) परिभाषित होता है।"},
  {"id":"gk-science-tech-244","question":"The 'transformer' architecture used in most large language models was introduced in a 2017 research paper titled:","options":["Attention Is All You Need","Deep Residual Learning for Image Recognition","Generative Adversarial Nets","ImageNet Classification with Deep Convolutional Networks"],"answer":0,"explanation":"Researchers at Google proposed the transformer, built on self-attention, in 'Attention Is All You Need' (2017). The other titles introduced ResNets, GANs and AlexNet.","difficulty":"hard","source":"UPSC Prelims · IBPS SO","questionHi":"अधिकांश बड़े भाषा मॉडलों में प्रयुक्त \"ट्रांसफ़ॉर्मर\" आर्किटेक्चर 2017 के किस शोधपत्र में प्रस्तुत किया गया था?","optionsHi":["Attention Is All You Need","Deep Residual Learning for Image Recognition","Generative Adversarial Nets","ImageNet Classification with Deep Convolutional Networks"],"explanationHi":"Google के शोधकर्ताओं ने स्व-ध्यान (सेल्फ़-अटेंशन) पर आधारित ट्रांसफ़ॉर्मर को \"Attention Is All You Need\" (2017) में प्रस्तावित किया। अन्य शीर्षकों ने ResNets, GANs और AlexNet प्रस्तुत किए।"},
  {"id":"gk-science-tech-245","question":"The 'Kessler syndrome', a concern in debates on anti-satellite tests and space debris, describes:","options":["Damage to satellite electronics caused by strong solar storms","A cascade of collisions in which debris causes ever more debris","Loss of bone density suffered by astronauts on long space missions","Radio interference between satellites in neighbouring slots"],"answer":1,"explanation":"Donald Kessler warned in 1978 that crowded orbits could reach a point where each collision creates fragments that cause further collisions, making some orbits unusable.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उपग्रह-रोधी परीक्षणों और अंतरिक्ष मलबे की चर्चाओं में उठने वाली \"केसलर सिंड्रोम\" की चिंता किसका वर्णन करती है?","optionsHi":["तीव्र सौर तूफ़ानों से उपग्रहों के इलेक्ट्रॉनिक्स को पहुँचने वाली क्षति","टकरावों की शृंखला, जिसमें मलबा और अधिक मलबा पैदा करता जाता है","लंबे अंतरिक्ष मिशनों में अंतरिक्ष यात्रियों की अस्थि घनत्व में कमी","पास-पास के स्लॉटों में स्थित उपग्रहों के बीच रेडियो व्यवधान"],"explanationHi":"डोनाल्ड केसलर ने 1978 में चेताया था कि भीड़-भरी कक्षाएँ ऐसी स्थिति में पहुँच सकती हैं जहाँ हर टकराव ऐसे टुकड़े बनाता है जो आगे और टकराव कराते हैं, जिससे कुछ कक्षाएँ अनुपयोगी हो जाती हैं।"},
  {"id":"gk-science-tech-246","question":"A satellite in a geosynchronous orbit that is inclined to the equator, like some NavIC satellites, appears to an observer on the ground to:","options":["Stay fixed at one single point in the sky all day long","Rise in the west and set in the east every day","Trace a figure-of-eight path in the sky each day","Cross the whole sky several times each day"],"answer":2,"explanation":"Its period matches Earth's rotation, but the inclination makes it drift north and south, tracing an analemma-like figure of eight; only a geostationary satellite over the equator appears fixed.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भूमध्य रेखा से झुकी हुई भूतुल्यकालिक कक्षा का उपग्रह, जैसे NavIC के कुछ उपग्रह, ज़मीन पर खड़े पर्यवेक्षक को कैसा दिखाई देता है?","optionsHi":["पूरे दिन आकाश में एक ही बिंदु पर स्थिर","प्रतिदिन पश्चिम में उगता और पूर्व में अस्त होता","प्रतिदिन आकाश में आठ की आकृति का पथ बनाता","प्रतिदिन कई बार पूरे आकाश को पार करता"],"explanationHi":"इसका आवर्तकाल पृथ्वी के घूर्णन के बराबर होता है, पर झुकाव के कारण यह उत्तर-दक्षिण खिसकता है और अनैलेमा जैसी आठ की आकृति बनाता है; केवल भूमध्य रेखा के ऊपर का भूस्थिर उपग्रह स्थिर दिखता है।"},
  {"id":"gk-science-tech-247","question":"The International Space Station, at about 400 km altitude, orbits Earth roughly 16 times a day, while a geostationary satellite orbits once a day. This is because:","options":["Lower orbits need higher speeds and shorter paths, giving a period of about 90 minutes","The ISS keeps its engines firing all the time, while geostationary satellites coast freely","Geostationary satellites move against the Earth's rotation, which slows them","Atmospheric drag at 400 km pushes the ISS forward and speeds it up each orbit"],"answer":0,"explanation":"By Kepler's third law the period grows with orbital radius; at about 400 km the speed is about 7.7 km/s and the period about 92 minutes. Drag slows the ISS, and it needs only occasional reboosts.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"लगभग 400 km ऊँचाई पर स्थित अंतरराष्ट्रीय अंतरिक्ष स्टेशन दिन में लगभग 16 बार पृथ्वी की परिक्रमा करता है, जबकि भूस्थिर उपग्रह दिन में एक बार करता है। ऐसा इसलिए है क्योंकि:","optionsHi":["निचली कक्षाओं में अधिक चाल और छोटे पथ चाहिए, जिससे आवर्तकाल लगभग 90 मिनट होता है","ISS अपने इंजन हर समय चालू रखता है, जबकि भूस्थिर उपग्रह स्वतंत्र रूप से बहते रहते हैं","भूस्थिर उपग्रह पृथ्वी के घूर्णन के विपरीत चलते हैं, जिससे वे धीमे हो जाते हैं","400 km पर वायुमंडलीय घर्षण ISS को आगे धकेलकर हर परिक्रमा में उसकी चाल बढ़ा देता है"],"explanationHi":"केप्लर के तीसरे नियम से आवर्तकाल कक्षीय त्रिज्या के साथ बढ़ता है; लगभग 400 km पर चाल लगभग 7.7 km/s और आवर्तकाल लगभग 92 मिनट होता है। घर्षण ISS को धीमा करता है, और उसे केवल कभी-कभार कक्षा-उन्नयन की आवश्यकता होती है।"},
  {"id":"gk-science-tech-248","question":"Software released under the GNU General Public License (GPL) comes with the condition that:","options":["Distributed modified versions must also be released under the GPL, with source code","It may be used only for non-commercial, academic and educational purposes","Its source code must stay secret, though the compiled program may be shared freely","It must be registered with a government agency before it can legally be distributed"],"answer":0,"explanation":"The GPL is a 'copyleft' licence: anyone may use, study, change and sell the software, but distributed derivatives must carry the same freedoms, including access to source code.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO","questionHi":"GNU जनरल पब्लिक लाइसेंस (GPL) के अंतर्गत जारी सॉफ़्टवेयर के साथ कौन-सी शर्त आती है?","optionsHi":["वितरित संशोधित संस्करण भी सोर्स कोड सहित GPL के अंतर्गत जारी किए जाने चाहिए","इसका उपयोग केवल गैर-व्यावसायिक, शैक्षणिक और शिक्षा संबंधी प्रयोजनों के लिए ही हो सकता है","इसका सोर्स कोड गुप्त रहना चाहिए, यद्यपि संकलित प्रोग्राम स्वतंत्र रूप से साझा किया जा सकता है","वैध रूप से वितरित होने से पहले इसे किसी सरकारी एजेंसी में पंजीकृत कराना होगा"],"explanationHi":"GPL एक \"कॉपीलेफ़्ट\" लाइसेंस है: कोई भी सॉफ़्टवेयर का उपयोग, अध्ययन, परिवर्तन और विक्रय कर सकता है, पर वितरित व्युत्पन्न संस्करणों में वही स्वतंत्रताएँ, सोर्स कोड तक पहुँच सहित, रहनी चाहिए।"},
  {"id":"gk-science-tech-249","question":"The 2019 Nobel Prize in Chemistry, shared by John Goodenough, Stanley Whittingham and Akira Yoshino, was awarded for developing:","options":["Lithium-ion batteries","Organic light-emitting diodes","Graphene","Blue light-emitting diodes"],"answer":0,"explanation":"The three laid the groundwork for rechargeable lithium-ion batteries. Blue LEDs won the 2014 Physics prize and graphene the 2010 Physics prize.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"जॉन गुडएनफ़, स्टेनली व्हिटिंगम और अकीरा योशिनो द्वारा साझा किया गया 2019 का रसायन विज्ञान का नोबेल पुरस्कार किसके विकास के लिए दिया गया?","optionsHi":["लिथियम-आयन बैटरियाँ","कार्बनिक प्रकाश-उत्सर्जक डायोड","ग्रैफ़ीन","नीले प्रकाश-उत्सर्जक डायोड"],"explanationHi":"तीनों ने पुनःआवेशनीय लिथियम-आयन बैटरियों की नींव रखी। नीले LED को 2014 का और ग्रैफ़ीन को 2010 का भौतिकी पुरस्कार मिला।"},
  {"id":"gk-science-tech-250","question":"In a computer, 'cache memory' is:","options":["Permanent storage that keeps its data when the power is switched off","A part of the hard disk used as extra memory when the RAM is full","A small, fast memory near the processor that holds frequently used data","Memory set aside only for the graphics card to store images shown on screen"],"answer":2,"explanation":"Cache (usually SRAM) sits between the CPU and main memory to cut access time. Using disk space when RAM is full is virtual memory, and permanent storage is non-volatile memory.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO","questionHi":"कंप्यूटर में \"कैश मेमोरी\" क्या है?","optionsHi":["स्थायी संग्रहण जो बिजली बंद होने पर भी अपना डेटा बनाए रखता है","हार्ड डिस्क का वह भाग जो RAM भर जाने पर अतिरिक्त मेमोरी के रूप में प्रयुक्त होता है","प्रोसेसर के निकट स्थित छोटी, तेज़ मेमोरी जो बार-बार प्रयुक्त डेटा रखती है","केवल ग्राफ़िक्स कार्ड के लिए अलग रखी गई मेमोरी जो स्क्रीन पर दिखने वाले चित्र संग्रहीत करती है"],"explanationHi":"कैश (प्रायः SRAM) CPU और मुख्य मेमोरी के बीच रहकर पहुँच समय घटाती है। RAM भर जाने पर डिस्क स्थान का उपयोग वर्चुअल मेमोरी है, और स्थायी संग्रहण अवाष्पशील (नॉन-वोलेटाइल) मेमोरी है।"},
];

export default questions;
